-- SkillMap. Loaded from topcv-skillmap-processed.csv (TopCV, 2026-10-11).
BEGIN TRANSACTION;
CREATE TABLE jobs (
    source TEXT NOT NULL,
    source_job_id TEXT PRIMARY KEY,
    source_url TEXT,
    collected_at TEXT,
    title_raw TEXT,
    company_raw TEXT,
    location_raw TEXT,
    experience_raw TEXT,
    salary_raw TEXT,
    job_description_raw TEXT,
    candidate_requirements_raw TEXT,
    date_posted TEXT,
    valid_through TEXT,
    job_group TEXT,
    source_files TEXT,
    role TEXT,
    role_note TEXT,
    scope_status TEXT,
    scope_reason TEXT
);
CREATE INDEX idx_jobs_role ON jobs(role);
COMMIT;
