INSERT INTO "jobs" VALUES('TopCV','1637186','https://www.topcv.vn/viec-lam/ky-su-tri-tue-nhan-tao-ai-vtnet/1637186.html','2026-10-11T19:40:00+07:00','Kỹ Sư Trí Tuệ Nhân Tạo - AI - VTNet','Tổng Công ty Mạng lưới Viettel – Chi nhánh Tập đoàn Công nghiệp – Viễn thông Quân đội','Hà Nội','1 năm','15 - 25 triệu','phát triển sản phẩm nội bộ; Chatbot; CV (Computer Vision); OCR; Voice2Text; đảm bảo chất lượng dữ liệu; đảm bảo kết quả mô hình; báo cáo định kỳ tự động; bảo trì; cải thiện, làm sạch, thao tác dữ liệu; khắc phục sự cố; thiết kế API; tích hợp giải pháp với các nhóm khác; đóng gói, triển khai môi trường Product; Docker; docker-compose; xây dựng tài liệu thiết kế tổng thể, chi tiết; tài liệu giám sát','1 năm kinh nghiệm vị trí tương đương; tốt nghiệp ĐH Khoa học dữ liệu/KHMT/CNTT/Toán ứng dụng/Điện tử; cấu trúc dữ liệu và giải thuật; lý thuyết đồ thị; xác suất thống kê; đại số tuyến tính; giải tích; RDBMS; Graph Databases; NoSQL; Machine Learning; Deep Learning; NLP; Scikit-learn; TensorFlow; Keras; PyTorch; Python; SQL; đọc bài báo khoa học; lập trình lại thuật toán; trực quan hóa dữ liệu; Docker; Kubernetes; conversational AI; information extraction; text summarization; LangChain; vector embeddings; NLTK; GPT-3; GPT-4; ChatGPT; numpy; matplotlib; seaborn; pandas; kiến trúc, phát triển, triển khai giải pháp phân tích dữ liệu; Teamwork','2026-09-27','2026-10-30','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2125555','https://www.topcv.vn/viec-lam/ky-su-giai-phap-ai-camera-smart-solutions/2125555.html','2026-10-11T19:40:00+07:00','Kỹ Sư Giải Pháp AI Camera & Smart Solutions','CÔNG TY CỔ PHẦN VIỄN THÔNG CÔNG NGHỆ TTP GROUP','Hồ Chí Minh','2 năm','15 - 28 triệu','phân tích yêu cầu khách hàng; khảo sát hạ tầng; đề xuất giải pháp tổng thể (Camera, AI Box, phần mềm, lưu trữ, mạng); thiết kế kiến trúc hệ thống (Topology); lựa chọn thiết bị; mô hình triển khai (On-premise/Cloud); tài liệu kỹ thuật (Proposal, BoQ, thuyết minh, hồ sơ thầu); demo và tư vấn giải pháp; đào tạo đội ngũ kinh doanh; cấu hình hệ thống; tính toán chi phí, xây dựng báo giá; phối hợp Kỹ thuật và R&D; kiểm thử, đánh giá tính năng AI; đề xuất cải tiến sản phẩm; quản lý thư viện tài liệu kỹ thuật','tốt nghiệp Đại học CNTT/Điện tử Viễn thông/Tự động hóa; 2+ năm Presales/Solution Engineer; lĩnh vực CCTV/AI Camera/Smart City/Access Control/IT-Network; Camera IP, NVR, Server, lưu trữ, mạng LAN/WAN/4G; AI cơ bản (nhận diện khuôn mặt, nhận dạng biển số, phân tích hành vi); giao thức ONVIF, RTSP, WebRTC, MQTT, Edge AI, AI Box; tư duy hệ thống; phân tích; đọc hiểu bản vẽ kỹ thuật; PowerPoint, Excel; Visio, AutoCAD; kỹ năng giao tiếp, thuyết trình; đọc hiểu tài liệu tiếng Anh; tiếng Trung là lợi thế','','2026-10-29','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2136061','https://www.topcv.vn/viec-lam/ai-engineer/2136061.html','2026-10-11T19:40:00+07:00','AI Engineer','Công ty Cổ phần Tập đoàn TDI','Hà Nội','1 năm','Thoả thuận','Xây dựng, triển khai sản phẩm/giải pháp AI Agent từ thử nghiệm đến production; Phát triển bài toán AI theo định hướng đơn vị; Thu thập, làm sạch, chuẩn hóa dữ liệu; Xây dựng pipeline dữ liệu phục vụ huấn luyện/inference; Training/fine-tuning mô hình, đánh giá theo metric; Xây dựng demo/POC nhanh, phối hợp team kỹ thuật triển khai thành tính năng sản phẩm; Tích hợp mô hình qua API/service; Tối ưu inference (latency/cost); Tài liệu hóa, báo cáo tiến độ, chia sẻ kiến thức nội bộ','Tốt nghiệp ĐH Bách Khoa Hà Nội/FPT/ĐH Công Nghệ, chuyên ngành KHMT/CNTT/Data Science/AI/Học máy; Kiến thức, thực hành ML/DL (đồ án, lab, thesis); Đọc hiểu tài liệu tiếng Anh; Đam mê AI, tự học mạnh; Chủ động giải quyết vấn đề, teamwork; Lợi thế: kinh nghiệm triển khai/training AI thực tế (intern, freelance, nghiên cứu, dự án cá nhân); RAG, embedding, vector database (FAISS/Milvus/Pinecone); Sản phẩm cá nhân (GitHub, portfolio, bài viết kỹ thuật, Kaggle, cuộc thi)','2026-09-20','2026-10-16','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2236920','https://www.topcv.vn/viec-lam/ai-engineer-llm-rag-ai-automation-thu-duc-thu-nhap-15-25-trieu/2236920.html','2026-10-11T19:40:00+07:00','AI Engineer (LLM/RAG/AI Automation) Thủ Đức, Thu Nhập 15 - 25 Triệu','CÔNG TY TNHH NEXGEN BROS','Hồ Chí Minh','1 năm','15 - 25 triệu','xây dựng và tối ưu workflow RAG/agent; xử lý & chuẩn bị dữ liệu (parsing, embedding, vector search); gọi và tích hợp LLM API; đánh giá chất lượng output và tối ưu prompt; tham gia sprint & code review','Python; REST API; Database; nền tảng LLM (prompt, loop, embedding, tokenization, context window); 1–2 dự án RAG/Chatbot/prompt engineering; đọc hiểu tài liệu tiếng Anh; điểm cộng: LangChain, LlamaIndex, LangGraph, vector DB (FAISS, Chroma, Pinecone, Qdrant), FastAPI, Docker, CI/CD, Cloud AWS/GCP/Azure, Platform APIs, Multimodal/Computer Vision, MLOps (MLflow, vLLM, Kubernetes), GitHub/portfolio','2026-10-04','2026-10-31','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2240008','https://www.topcv.vn/brand/ahv/tuyen-dung/intern-ai-driven-fullstack-engineer-j2240008.html','2026-10-11T19:40:00+07:00','Intern AI-Driven Fullstack Engineer','CÔNG TY CỔ PHẦN ĐẦU TƯ AHV HOLDING','Thái Nguyên','Không yêu cầu','Thoả thuận','tham gia phát triển dự án phần mềm Web/App; ứng dụng công cụ AI (ChatGPT, Claude, Gemini, Copilot, Cursor) hỗ trợ lập trình, tối ưu quy trình phát triển phần mềm; xây dựng giao diện Frontend và xử lý nghiệp vụ Backend; hỗ trợ phát triển, kiểm thử, tối ưu hệ thống; nghiên cứu, đề xuất, triển khai giải pháp AI vào sản phẩm thực tế; phối hợp đội ngũ kỹ thuật hoàn thành nhiệm vụ được giao','sinh viên năm 3, năm 4 hoặc mới tốt nghiệp CNTT, Khoa học máy tính, Kỹ thuật phần mềm; kiến thức cơ bản HTML, CSS, JavaScript; Framework Frontend (ReactJS, NextJS, VueJS) là lợi thế; kiến thức cơ bản Backend (NodeJS, PHP, Python hoặc tương đương); yêu thích công nghệ, AI; tư duy logic; chủ động học hỏi; tinh thần trách nhiệm cao; ưu tiên từng sử dụng công cụ AI hỗ trợ lập trình','2026-09-20','2026-10-19','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: tiêu đề intern; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2284624','https://www.topcv.vn/viec-lam/thuc-tap-sinh-phat-trien-ai-llm-model/2284624.html','2026-10-11T19:40:00+07:00','Thực Tập Sinh Phát Triển AI/LLM MODEL','CÔNG TY TNHH MEKONGAI','Đà Nẵng','Không yêu cầu','Tới 4 triệu','nghiên cứu và phát triển hệ thống RAG (Retrieval-Augmented Generation); truy xuất tri thức, hỏi đáp trên tài liệu; xây dựng pipeline xử lý dữ liệu (Document Processing, Chunking, Embedding, Vector Database); Retrieval, Hybrid Search, Reranking; đánh giá chất lượng Retrieval và câu trả lời LLM; phân tích lỗi, đề xuất cải tiến; nghiên cứu, lựa chọn LLM mã nguồn mở; thu thập, làm sạch, chuẩn hóa dữ liệu huấn luyện; fine-tuning (SFT, LoRA/QLoRA, PEFT); đánh giá mô hình; ứng dụng RAG/LLM trong Cybersecurity; phân tích tài liệu bảo mật, lỗ hổng','Python, Machine Learning/Deep Learning, Transformer, LLM; RAG, Embedding, Vector Database; Fine-tuning LLM; đọc hiểu tài liệu tiếng Anh; project RAG hoặc Fine-tuning LLM; PyTorch, Hugging Face, LangChain/LlamaIndex, PEFT, Qdrant, ChromaDB; kiến thức cơ bản Cybersecurity, OWASP, CVE/CWE, Web/API Security, Penetration Testing; GitHub; tư duy phân tích, giải quyết vấn đề; tự học; thiết kế thử nghiệm; chủ động, có trách nhiệm','2026-09-27','2026-10-31','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: tiêu đề thực tập sinh; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2290551','https://www.topcv.vn/viec-lam/ai-developer/2290551.html','2026-10-11T19:40:00+07:00','AI Developer','Công ty cổ phần CTNET','Đà Nẵng','2 năm','Thoả thuận','Tích hợp AI-powered features và AI Agents vào nền tảng SaaS; Phát triển AI Core Services bằng Python/FastAPI; Thiết kế AI Agent / Agentic Workflows; Tích hợp LLM với APIs, databases, business services qua Function Calling / Tool Use; Conversation state, memory, context management, AI evaluation; Prompts, guardrails, permission controls, fallback, human handoff; Phối hợp Backend, Frontend, Product teams tối ưu data flow, latency, security, scalability','Kinh nghiệm LLMs (OpenAI, Claude, Llama); LangChain, CrewAI, LlamaIndex, Autogen; AI Agents / Agentic Workflows; Python (bắt buộc); RESTful APIs, Microservices; JSON, Webhooks; Vector Database (ChromaDB, Pinecone, Qdrant); Git/GitHub; Product-minded thinking','2026-10-08','2026-11-07','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2293829','https://www.topcv.vn/viec-lam/edge-ai-engineer/2293829.html','2026-10-11T19:40:00+07:00','Edge AI Engineer','CÔNG TY CỔ PHẦN THIẾT BỊ CÔNG NGHIỆP GEIC','Hà Nội','1 năm','Thoả thuận','nghiên cứu/thiết kế/phát triển firmware, middleware, HAL/BSP cho hệ nhúng (MCU/MPU/SoC); thiết kế và tối ưu thuật toán xử lý ảnh (ISP: giảm nhiễu, cân bằng trắng, demosaic, hiệu chỉnh màu, tăng sắc nét); tích hợp/tối ưu/triển khai mô hình AI/ML trên thiết bị Edge (CPU/GPU/NPU/AI Accelerator); phát triển phần mềm cho pipeline Camera AI (Driver, HAL/BSP, middleware); tối ưu hiệu năng/bộ nhớ/năng lượng; kiểm thử, tích hợp, gỡ lỗi; phối hợp nhóm Hardware/AI/QA','thành thạo C/C++ (bắt buộc), bash shell, Python; Makefile/CMake, U-Boot, đa luồng/đa tiến trình, microservice; lập trình nhúng MCU/MPU (STM32), RTOS, Linux Embedded (build kernel, Raspberry Pi, Jetson Nano, Qualcomm), UART/SPI/I2C/USB; AI xử lý ảnh (object detection, classification, segmentation, OCR), fine-tuning, training model, PyTorch, TensorFlow, ONNX; Git, GitLab, SVN','','2026-11-09','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2295237','https://www.topcv.vn/viec-lam/tts-ai-thanh-thao-antigravity-lam-du-an-thuc-te/2295237.html','2026-10-11T19:40:00+07:00','TTS AI – THÀNH THẠO ANTIGRAVITY, Làm Dự Án Thực Tế','CÔNG TY TNHH BAHA HOMES','Hồ Chí Minh','Không yêu cầu','1 - 3 triệu','dùng Antigravity/AI Agent phân tích yêu cầu, triển khai và hoàn thiện công việc; xây dựng website, ứng dụng, hệ thống quản trị, sản phẩm công nghệ; số hóa, tự động hóa quy trình và nghiên cứu giải pháp AI/Automation; kiểm thử, phát hiện lỗi, xử lý và hoàn thiện sản phẩm; làm việc với Git/GitHub, API, Database; nghiên cứu công nghệ, viết tài liệu và triển khai dự án thực tế','bắt buộc thành thạo Antigravity (đã dùng trong học tập/dự án cá nhân/công việc); biết giao việc cho AI Agent bằng prompt rõ ràng; chia nhỏ nhiệm vụ, theo dõi và kiểm tra kết quả; không phụ thuộc hoàn toàn vào AI, phát hiện và sửa lỗi AI; chủ động, học nhanh, đa nhiệm; tiếng Anh đọc hiểu tài liệu kỹ thuật; ưu tiên Git/GitHub, Web/App, Python, JavaScript/TypeScript, API, Database, n8n/Automation, Docker, UI/UX, AI Agent, IoT/Robot','2026-09-11','2026-11-01','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: tiêu đề tts; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2301090','https://www.topcv.vn/viec-lam/thuc-tap-sinh-ai-big-data/2301090.html','2026-10-11T19:40:00+07:00','Thực Tập Sinh AI-Big Data','Công Ty Cổ Phần Đầu Tư Thương Mại Và Phát Triển Công Nghệ FSI','Hà Nội','Không yêu cầu','Thoả thuận','nghiên cứu và phát triển mô hình Trí tuệ nhân tạo; Thị giác máy tính (Computer Vision); Xử lý ngôn ngữ tự nhiên (NLP); xây dựng pipeline xử lý tài liệu số; huấn luyện/tối ưu hóa mô hình nhận dạng, bóc tách thông tin; triển khai tích hợp mô hình vào hệ thống thực tế','sinh viên năm cuối/sắp tốt nghiệp CNTT, Khoa học Máy tính, Trí tuệ nhân tạo, Hệ thống thông tin; Python; tư duy logic; cấu trúc dữ liệu, thuật toán; kiến thức cơ bản Machine Learning/Deep Learning; PyTorch hoặc TensorFlow; bài toán Computer Vision (OCR); NLP (phân loại văn bản, bóc tách thực thể); đóng gói mô hình, viết API cơ bản (FastAPI); Linux, Git; đọc hiểu tài liệu tiếng Anh chuyên ngành; chủ động, tinh thần học hỏi; thực tập tối thiểu 3-4 ngày/tuần','2026-09-20','2026-10-14','ai_ml_engineer','de_aiml','ai_ml_engineer','tiêu đề chứa cả AI và Data; ưu tiên AI theo nhiệm vụ','eligible','Phù hợp: tiêu đề thực tập sinh; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2302497','https://www.topcv.vn/viec-lam/ky-su-huan-luyen-ai-chuyen-doi-so-linh-vuc-co-khi-che-tao-may/2302497.html','2026-10-11T19:40:00+07:00','Kỹ Sư Huấn Luyện AI – Chuyển Đổi Số Lĩnh Vực Cơ Khí, Chế Tạo Máy','CTY TNHH R TECHNO VIỆT NAM','Hồ Chí Minh','2 năm','Từ 40 triệu','phát triển và triển khai mô hình AI/Machine Learning; Computer Vision; Generative AI; tối ưu hóa quy trình làm việc kỹ thuật; phương pháp dựa trên dữ liệu; phối hợp với kỹ sư thiết kế cơ khí; chuyển đổi kiến thức chuyên môn tại hiện trường (domain knowledge)','2+ năm kinh nghiệm AI/ML thực tế; Python, PyTorch; đọc hiểu mô hình CAD 2D/3D; bản vẽ kỹ thuật; quy trình sản xuất cơ khí; ưu tiên 2+ năm thiết kế 2D/3D (AutoDesk, SolidWorks)','','2026-10-15','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2307451','https://www.topcv.vn/viec-lam/ky-su-ai-may-hoc-ai-ml-engineer-25-70-trieu-ho-chi-minh-hoc-mon-quan-12/2307451.html','2026-10-11T19:40:00+07:00','Kỹ Sư AI/ Máy Học (AI/ML Engineer) - 25-70 Triệu - Hồ Chí Minh (Hóc Môn/ Quận 12)','Công Ty Cổ Phần Thực Phẩm Fresco','Hồ Chí Minh','2 năm','25 - 70 triệu','triển khai công nghệ số và công cụ AI vào quá trình vận hành; ChatGPT; Copilot; Gemini; hệ thống tự động hóa; tối ưu quy trình; phân tích quy trình làm việc cũ; đề xuất giải pháp số hóa; rút ngắn thời gian; hướng dẫn, tập huấn kỹ năng sử dụng công cụ số và AI cho các phòng ban, cán bộ nhân viên; xây dựng, quản lý cơ sở dữ liệu; bảo mật thông tin theo quy định an toàn mạng','tốt nghiệp đại học CNTT/Trí tuệ nhân tạo/Khoa học dữ liệu; tối thiểu 2 năm kinh nghiệm vị trí tương đương; ưu tiên kinh nghiệm triển khai giải pháp AI/tự động hóa trong doanh nghiệp sản xuất; thành thạo nền tảng số; nắm bắt xu hướng và công cụ AI mới; kiến thức, kinh nghiệm thực tế AI/Machine Learning; xử lý và quản trị dữ liệu; phân tích quy trình nghiệp vụ; đề xuất giải pháp số hóa; giao tiếp, truyền đạt dễ hiểu; hướng dẫn người khác; tư duy giải quyết vấn đề thực tiễn','2026-09-27','2026-10-20','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2313038','https://www.topcv.vn/viec-lam/ai-engineer-intern/2313038.html','2026-10-11T19:40:00+07:00','AI Engineer Intern','CÔNG TY CỔ PHẦN ĐẦU TƯ GALAX NH','Hà Nội','Không yêu cầu','Thoả thuận','Tự động hóa quy trình (nhập liệu, email khách hàng, hóa đơn); tích hợp mô hình AI (OpenAI, Anthropic, mã nguồn mở) vào phần mềm/website/cơ sở dữ liệu; RAG; bảo trì & kiểm soát chi phí API','Python; Prompt Engineering; No-Code/Low-Code (Make, Zapier, agent framework); tư duy kinh doanh; sinh viên năm cuối/mới tốt nghiệp CNTT/KHMT/Khoa học Dữ liệu; giao tiếp tiếng Việt/Anh; dự án cá nhân/GitHub/demo AI API; SQL; REST API; Google Workspace/Microsoft 365 automation','2026-09-27','2026-10-25','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: tiêu đề intern; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2315254','https://www.topcv.vn/viec-lam/ai-engineer-du-an-cntt/2315254.html','2026-10-11T19:40:00+07:00','AI Engineer – Dự Án CNTT','CÔNG TY CỔ PHẦN GTECH VIỆT NAM','Hà Nội','1 năm','20 - 25 triệu','xây dựng/tối ưu RAG pipeline, vector search, agent AI; phát triển giải pháp AI cho tài liệu, tìm kiếm, tự động hoá; phối hợp BA/team phần mềm triển khai hệ thống; phát triển tính năng mới, cải tiến hiệu năng, bảo mật','Python; LLM API; LangChain/LlamaIndex; RAG; vector database; prompt engineering; REST API; Docker; CI/CD; AI frameworks; SQL/NoSQL; tiếng Anh đọc hiểu tài liệu kỹ thuật','','2026-12-05','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2315676','https://www.topcv.vn/brand/nganhangthuongmaicophanquandoi/tuyen-dung/mb-trainee-ai-engineer-fresher-intern-khoi-cong-nghe-thong-tin-2025td924-j2315676.html','2026-10-11T19:40:00+07:00','MB Trainee - AI Engineer (Fresher, Intern) - Khối Công Nghệ Thông Tin (2025TD924)','NGÂN HÀNG TMCP QUÂN ĐỘI – MBBANK','Hà Nội','Không yêu cầu','Thoả thuận','phát triển, ứng dụng, tối ưu, tích hợp mô hình AI (Computer Vision, NLP) cho bài toán ngân hàng; tham gia kiến trúc hệ thống, thiết kế mô hình hoạt động, tối ưu performance; coding, test metrics, service và unittest theo DevOps/MLOps; nghiên cứu bài báo khoa học AI/ML/DL; tham gia chương trình đào tạo và dự án Trainee','sinh viên năm 4 hoặc tốt nghiệp dưới 1 năm ngành CNTT/KHMT/ĐTVT/CNPM/HTTT; ưu tiên tốt nghiệp giỏi/xuất sắc, có giải thưởng/nghiên cứu khoa học; onsite tối thiểu 7/10 buổi/tuần; Python, C/C++; FastAPI/Flask/Django; Tensorflow, Pytorch, DGL, PyG, Onnx; RESTful/gRPC API; Git, Git Flow; Docker, Kubernetes; Kubeflow/MLFlow; TritonServer, Tensorflow Serving; CNN/RNN/Transformer/Attention, SVM/KNN/Clustering, GNN; Knowledge Distillation, Model Prune, Model Quantization; Supervised learning, Reinforcement Learning; xử lý ảnh/video/âm thanh/NLP','','2026-10-29','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: tiêu đề intern; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2315696','https://www.topcv.vn/brand/nganhangthuongmaicophanquandoi/tuyen-dung/ai-software-engineer-python-go-c-c-backend-ai-agents-khoi-cong-nghe-thong-tin-2026td450888-j2315696.html','2026-10-11T19:40:00+07:00','AI Software Engineer (Python/Go/C/C++ Backend & AI Agents) - Khối Công Nghệ Thông Tin (2026TD450888)','NGÂN HÀNG TMCP QUÂN ĐỘI – MBBANK','Hà Nội','Không yêu cầu','Thoả thuận','thiết kế và phát triển hệ thống Backend tích hợp AI/LLM Agents; xây dựng Agentic Workflow (Planning – Tool Use – Memory – Execution); phát triển dịch vụ AI dạng Microservices (FastAPI/Flask/Django hoặc Java/Go services); tích hợp mô hình AI vào sản phẩm qua REST/gRPC APIs; triển khai hệ thống AI production-ready với Docker/Kubernetes; tối ưu hiệu năng inference (latency, throughput, cost); nghiên cứu và ứng dụng kỹ thuật mới (RAG, Function Calling, Multi-agent systems, Reinforcement Learning Agents); đảm bảo tiêu chuẩn bảo mật, an toàn, khả năng mở rộng của hệ thống AI','Python; Go; C/C++; kinh nghiệm Backend thực tế; Microservice Architecture; PostgreSQL; MongoDB; API design (RESTful/gRPC); tối ưu hiệu năng hệ thống; LLM Agents (GPT, Gemini, Claude); LangChain; LangGraph; ADK; Autogen; RAG pipelines; Vector Database (Milvus, pgvector); Tool-use Agents (Function Calling); Memory + Planning + Multi-step reasoning; Git/GitFlow; Docker; Kubernetes; NLP; Computer Vision; Speech; Video Understanding; CNN; RNN; Transformer; Attention; GNN; AI Safety; Guardrails; Model Monitoring; tốt nghiệp Đại học CNTT/KHMT/CNPM/HTTT/Tự động hóa/ĐTVT','','2026-10-29','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2316598','https://www.topcv.vn/viec-lam/ky-su-machine-vision-ai-vision/2316598.html','2026-10-11T19:40:00+07:00','Kỹ Sư Machine Vision-Ai Vision','CÔNG TY CỔ PHẦN THƯƠNG MẠI VÀ SẢN XUẤT THIẾT BỊ CÔNG NGHIỆP ANH PHÁT','Hà Nội','1 năm','15 - 30 triệu','Thiết kế/triển khai hệ thống Machine Vision/AI trong công nghiệp; lập trình và xử lý ảnh 2D/3D, AI Vision; tích hợp camera/cảm biến/PLC/Robot vào hệ thống tự động hóa; phát triển thuật toán phát hiện lỗi, đo kiểm kích thước, nhận dạng sản phẩm; lắp đặt, chạy thử, bàn giao hệ thống tại nhà máy; tư vấn/hỗ trợ kỹ thuật cho khách hàng','Kiến thức Machine Vision/AI; Halcon; Cognex; OpenCV; camera công nghiệp; chiếu sáng; ống kính; AutoCAD; C#; SolidWorks; PLC; tiếng Anh TOEIC 550','2026-10-04','2026-12-29','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2316943','https://www.topcv.vn/viec-lam/ai-agent-engineer-ai-automation-developer-ky-su-trien-khai-tac-nhan-ai-va-tu-dong-hoa-cho-doanh-nghiep-thu-nhap-10-30-trieu-thang-tai-ha-noi/2316943.html','2026-10-11T19:40:00+07:00','AI Agent Engineer / AI Automation Developer – Kỹ sư triển khai tác nhân AI và tự động hoá cho doanh nghiệp (Thu nhập 10–30 triệu/tháng) tại Hà Nội','CÔNG TY CỔ PHẦN TẬP ĐOÀN KHOA HỌC KỸ THUẬT HDC (HDC Group)','Hà Nội','Không yêu cầu kinh nghiệm','10 - 30 triệu','phát triển AI Agent & tự động hoá quy trình nghiệp vụ; thiết kế và triển khai giải pháp AI Agent cho khách hàng doanh nghiệp; khảo sát nhu cầu, tư vấn giải pháp AI; vận hành, tối ưu và phát triển tính năng theo nhu cầu doanh nghiệp; nghiên cứu công nghệ mới ứng dụng vào sản phẩm','AI Agent, AI Automation; hệ sinh thái n8n, Make/Zapier; tích hợp API, nền tảng dữ liệu và mô hình AI vào quy trình doanh nghiệp; tư duy quy trình, phân tích nghiệp vụ; giao tiếp, trình bày tốt','2026-10-04','2027-01-06','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2319950','https://www.topcv.vn/viec-lam/ai-engineer/2319950.html','2026-10-11T19:40:00+07:00','AI Engineer','CÔNG TY CỔ PHẦN PARALINE SOFTWARE','Hà Nội','2 năm','20 - 27 triệu','phát triển hệ thống backend tích hợp AI/LLM Agents; xây dựng hệ thống AI/LLM Applications phục vụ sản phẩm thực tế; thiết kế và triển khai AI Agents, Multi-agent Workflows, Autonomous Systems; xây dựng RAG Pipelines, Retrieval Systems, Knowledge-based AI Systems; tích hợp LLM (GPT, Claude, Gemini); làm việc với Vector Database và Semantic Search; tối ưu chất lượng phản hồi, độ chính xác và hiệu năng; triển khai Evaluation Pipelines; triển khai AI Systems ở môi trường Production; đảm bảo khả năng mở rộng, bảo mật, ổn định','từ 1,5 năm Python hoặc phát triển AI/LLM Applications; tốt nghiệp ĐH CNTT/ĐTVT/Tài chính/Ngân hàng/Kinh tế; kỹ thuật sản phẩm Production AI (NLP/LLM, CV, Graph AI); LangChain, LangGraph, Autogen, Google ADK; LLM APIs (OpenAI GPT, Claude, Gemini); Backend Systems, Async Processing, Microservices (lợi thế)','2026-10-04','2026-11-07','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2322109','https://www.topcv.vn/viec-lam/ai-engineer/2322109.html','2026-10-11T19:40:00+07:00','AI Engineer','CÔNG TY TNHH AZ-ROBOTICS','Đà Nẵng','1 năm','Thoả thuận','phát triển hệ thống định vị, lập bản đồ; SLAM; xử lý dữ liệu không gian 3D; UAV; Camera; IMU; LiDAR; GNSS; VIO; LIO; LIVO; Digital Twin; tái cấu trúc 3D; SfM; đám mây điểm; point clouds; mesh reconstruction; 3DGS; thuật toán Computer Vision; detection; tracking; segmentation; ước tính độ sâu; bản đồ ngữ nghĩa 3D; phát hiện thay đổi; ước tính góc chụp camera; hiệu chuẩn cảm biến; đồng bộ hóa thời gian; hợp nhất đa cảm biến; hệ thống tránh vật cản; nhận diện chướng ngại vật; định vị khi mất tín hiệu GNSS; tối ưu hóa quỹ đạo bay; phân bổ nhiệm vụ; phối hợp vận hành nhiều UAV; tích hợp module AI/Perception vào phần mềm điều khiển UAV; ROS2; MAVLink; PX4; ArduPilot; Python; C++; thiết kế thử nghiệm; test thực địa','tốt nghiệp Đại học KHMT/AI/Robotics/Tự động hóa/Kỹ thuật Điện-Điện tử; thành thạo Python; C++; Linux; Git; computer vision; đại số tuyến tính; hình học không gian; tối ưu hóa; machine learning; OpenCV; PyTorch; dự án/nghiên cứu/thực tập SLAM, VIO, LIO/LIVO, SfM, tái cấu trúc 3D, đám mây điểm, 3DGS; đọc hiểu papers; công cụ AI lập trình; Claude Code; Cursor; Codex; ROS2; MAVLink; PX4; ArduPilot; IMU; LiDAR; GNSS; COLMAP; Open3D; PCL; NeRF; path planning; A*; Dijkstra; RRT; CUDA; ONNX; TensorRT; NVIDIA Jetson; AI/Computer Vision; 3D reconstruction','2026-10-07','2026-11-06','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2324036','https://www.topcv.vn/brand/elcom/tuyen-dung/applied-ai-engineer-ai-agent-llm-j2324036.html','2026-10-11T19:40:00+07:00','Applied AI Engineer (AI Agent, LLM)','Công ty cổ phần công nghệ - viễn thông Elcom','Hà Nội','1 năm','Thoả thuận','phát triển AI Agent cho nghiệp vụ hành chính công (code, test, tích hợp agent xử lý hồ sơ, tra cứu văn bản pháp quy, hỗ trợ soạn thảo, tổng hợp báo cáo); xây dựng tools và MCP server kết nối agent với API, database, hệ thống quản lý văn bản; structured output; human-in-the-loop; pipeline RAG (xử lý tài liệu tiếng Việt, văn bản scan, bảng biểu, công văn; chunking; tạo embedding; đánh chỉ mục; hybrid search; re-ranking); triển khai mô hình on-premise trên hạ tầng GPU nội bộ/air-gapped; vận hành inference engine (vLLM, SGLang, TensorRT-LLM, NVIDIA Dynamo, llm-d) trên Kubernetes; tối ưu KV cache, định tuyến request, lượng tử hóa (FP8, FP4); đánh giá chất lượng evals (độ chính xác, hallucination); thiết lập guardrails, lọc dữ liệu cá nhân, audit log; theo dõi log, latency, chi phí; tinh chỉnh prompt và context; xử lý sự cố production; dùng AI coding agent trong công việc hằng ngày','Python; backend; xây REST API; làm việc với cơ sở dữ liệu; kinh nghiệm xây ứng dụng dùng LLM (chatbot, RAG, agent); nguyên lý RAG, embedding, tool calling; Git; AI coding agent; đọc hiểu tài liệu kỹ thuật tiếng Anh; ý thức an toàn thông tin, bảo vệ dữ liệu cá nhân; ưu tiên: LangGraph, LlamaIndex, OpenAI Agents SDK, Claude Agent SDK, Google ADK; MCP server; tự host mô hình open-weight (vLLM, SGLang); lượng tử hóa FP8/FP4; KV cache; NVIDIA Dynamo; llm-d; Docker; Linux; Kubernetes; vector database (Qdrant, Milvus, pgvector, Elasticsearch); Langfuse; Ragas; DeepEval; xử lý văn bản tiếng Việt (OCR, trích xuất thông tin, phân loại văn bản); fine-tuning LoRA/QLoRA; tốt nghiệp Đại học CNTT/KHMT/AI','2026-10-07','2026-11-15','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2325817','https://www.topcv.vn/viec-lam/ai-ml-engineer-pcb-rd/2325817.html','2026-10-11T19:40:00+07:00','AI/ML Engineer – PCB R&D','CÔNG TY TNHH CÔNG NGHỆ SKYCADRAI','Đà Nẵng','1 năm','10 - 25 triệu','nghiên cứu, phát triển giải pháp AI/ML cho PCB và điện tử; phát triển ứng dụng AI cho thiết kế, phân tích, tối ưu; khám phá Generative AI, LLM, RAG, AI Agents; phối hợp nhóm phần mềm, kỹ thuật để tích hợp giải pháp AI vào sản phẩm; làm việc trong nhóm R&D','bằng Đại học trở lên CNTT/AI/Khoa học dữ liệu/Kỹ thuật/Toán; 1+ năm kinh nghiệm AI/ML, Deep Learning, R&D; Python; C/C++; kiến thức ML/DL; phát triển mô hình AI/ML; xử lý dữ liệu; APIs; phát triển phần mềm; tiếng Anh giao tiếp; PyTorch; TensorFlow; scikit-learn; Computer Vision; Generative AI; thiết kế PCB/điện tử; bài báo nghiên cứu','2026-10-08','2026-11-07','ai_ml_engineer','de_aiml','ai_ml_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2166770','https://www.topcv.vn/viec-lam/ai-lead/2166770.html','2026-10-11T19:40:00+07:00','AI Lead','CÔNG TY CỔ PHẦN ĐẦU TƯ CÔNG NGHỆ & ĐỔI MỚI VIỆT','Hà Nội','Trên 5 năm','Thoả thuận','Nghiên cứu/phát triển tính năng AI cho hệ thống và sản phẩm; xây dựng AI Agent, Chatbot AI, Automation, Workflow, Multi-agent system; giải pháp RAG, Document AI, AI Workspace, AI automation; tích hợp OpenAI, Gemini, Claude, Ollama, open-source LLM; xây dựng pipeline dữ liệu (Embedding, Vector DB, Prompt engineering, Fine-tuning); tối ưu hiệu năng, chi phí, độ chính xác; phối hợp backend/frontend tích hợp AI vào sản phẩm','Python; AI/ML; LLM; AI Agent; LangChain/LangGraph; Vector Database; Prompt Engineering; API integration; RAG architecture; Embedding; MCP/Agent workflow; Multi-agent system; tư duy sản phẩm','2026-09-27','2026-10-31','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2178330','https://www.topcv.vn/viec-lam/ai-engineer-lead/2178330.html','2026-10-11T19:40:00+07:00','AI Engineer Lead','CÔNG TY CỔ PHẦN CÔNG NGHỆ ALPHAWAY','Hà Nội','2 năm','Thoả thuận','triển khai giải pháp AI trong lĩnh vực Ngân hàng; phát triển và tối ưu mô hình AI; phân tích yêu cầu nghiệp vụ; đánh giá giải pháp từ bên thứ ba; điều phối các phòng ban; đưa sáng kiến AI vào vận hành hiệu quả','Python; PyTorch; TensorFlow; hệ sinh thái LLM (OpenAI, LangChain, LangGraph, Vector Database); deploy và tối ưu mô hình (TensorRT); điện toán đám mây (AWS/Azure/GCP); tích hợp API; phân tích bài toán nghiệp vụ ngân hàng; giao tiếp tiếng Việt & tiếng Anh; điều phối công việc; quản lý tiến độ; làm việc với vendor; nghiên cứu nhanh công nghệ mới','','2026-10-24','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2231942','https://www.topcv.vn/viec-lam/fullstack-ai-leader/2231942.html','2026-10-11T19:40:00+07:00','Fullstack AI Leader','CÔNG TY CỔ PHẦN CÔNG NGHỆ ALPHAWAY','Hà Nội','2 năm','Thoả thuận','phát triển, triển khai, vận hành sản phẩm, nền tảng nội bộ và dịch vụ khách hàng tại Techcom Life; xây dựng API backend bằng Python (FastAPI/Django/Flask); thiết kế database, tối ưu hiệu năng; phát triển front-end bằng React (ưu tiên TypeScript), đảm bảo UX, responsiveness, khả năng mở rộng; hợp tác Data/ML và Product tích hợp mô-đun AI (mô hình, RAG, agentic workflows); thiết kế kiến trúc, pipelines dữ liệu; tích hợp dịch vụ bên thứ ba (vector DB, LLMs, message queues, authentication); code review, unit/integration tests, CI/CD, logging, monitoring, alerting; đánh giá công nghệ, đề xuất cải tiến hiệu suất, chi phí, độ an toàn','2+ năm phát triển fullstack Python (backend) và ReactJS (frontend); API REST/GraphQL; WebSockets; Postgres/MySQL; NoSQL (MongoDB, Redis); triển khai ứng dụng production; CI/CD; containerization (Docker, Kubernetes cơ bản); kỹ năng giải quyết vấn đề; giao tiếp tiếng Việt tốt; (ưu tiên) RAG, retrieval (Pinecone/FAISS/Weaviate), kết nối LLMs (OpenAI, Llama); agentic systems; prompt engineering; evaluation pipelines; triển khai/scale inference; ETL/streaming (Kafka, RabbitMQ); cloud (AWS/GCP/Azure); bảo mật ứng dụng','','2026-10-15','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2242716','https://www.topcv.vn/viec-lam/ai-engineer-ai-agent-agentic-ai/2242716.html','2026-10-11T19:40:00+07:00','AI Engineer (AI Agent/ Agentic AI)','CÔNG TY TNHH MỘT THÀNH VIÊN AN NINH MẠNG VIETTEL','Hà Nội','4 năm','Thoả thuận','phát triển AI Agent cho use case hệ thống; chatbot hỏi-đáp; tra cứu dữ liệu; text-to-SQL; xây dựng và tối ưu RAG pipeline; chunking; embedding; vector search; reranking; câu trả lời có trích dẫn; prompt engineering; function/tool calling; structured output; tích hợp LLM với API, cơ sở dữ liệu; kiểm chứng độ chính xác của AI Agent; tối ưu và đảm bảo an toàn; triển khai đánh giá (eval), monitoring và tracing; áp dụng guardrails; chuyển yêu cầu nghiệp vụ thành luồng AI Agent; xử lý lỗi và fallback; phối hợp với nhóm sản phẩm, chuyên gia an ninh mạng, vận hành','4 năm kinh nghiệm phát triển phần mềm/AI-ML; từng làm sản phẩm ứng dụng LLM/agent; thành thạo Python; Git; REST API; thiết kế module; unit test; tích hợp API LLM; prompt engineering; function/tool calling; structured output; RAG thực tế; embedding; Qdrant; Milvus; pgvector; retrieval; citation; triển khai ≥1 dự án Agentic AI; LangGraph; LangChain; CrewAI; AutoGen; dữ liệu tabular và text; tốt nghiệp Đại học ATTT/CNTT/KHMT; MCP (Model Context Protocol); text-to-SQL; semantic layer; LLMOps; RAGAS; DeepEval; promptfoo; Langfuse; LangSmith; SQL; NoSQL; container; message queue; Spark; notebook; tư duy hệ thống; định hướng sản phẩm','','2026-12-31','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Yêu cầu kinh nghiệm 4 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2258880','https://www.topcv.vn/brand/smartosc/tuyen-dung/senior-ai-engineer-good-english-j2258880.html','2026-10-11T19:40:00+07:00','Senior AI Engineer (Good English)','CÔNG TY CỔ PHẦN SMARTOSC','Hà Nội','Trên 5 năm','Thoả thuận','Đưa hệ thống LLM (RAG pipelines, multi-agent workflows, conversational assistants) từ demo lên production ổn định; xây dựng evaluation layer (regression testing prompts/agents, hallucination & safety checks, đo lường chất lượng retrieval, latency/cost/quality tradeoffs); vận hành AI (observability, alerting, retries/fallbacks, security review, incident-readiness); cải thiện cloud infrastructure và deployment pipelines; mentoring engineers về testing, code quality, documentation','6+ năm software engineering, 2+ năm triển khai LLM/AI production; kinh nghiệm RAG và agentic AI systems; Python; JS/TS frontend; cloud provider (AWS) với infrastructure-as-code và Docker; testing, evaluation, monitoring, cost/performance tuning; giao tiếp tiếng Anh tốt','2026-09-20','2026-12-30','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2269102','https://www.topcv.vn/viec-lam/ai-engineer-middle-senior/2269102.html','2026-10-11T19:40:00+07:00','AI Engineer (Middle/ Senior)','VIETTEL DIGITAL SERVICES CORPORATION - BRANCH OF VIETTEL GROUP','Hà Nội','3 năm','Thoả thuận','Nghiên cứu/thiết kế/xây dựng giải pháp AI (LLM, AI Agent); triển khai ứng dụng AI vào sản phẩm (xử lý dữ liệu, lựa chọn/tinh chỉnh mô hình); xây dựng nền tảng dữ liệu AI-ready; đánh giá chất lượng mô hình/hệ thống; tối ưu độ chính xác/tốc độ/chi phí/khả năng mở rộng; triển khai an toàn, giám sát & xử lý sự cố; cập nhật công nghệ mới','Đại học loại Giỏi+ (ưu tiên thạc sĩ/tiến sĩ khoa học dữ liệu); Tiếng Anh TOEIC 650; 3+ năm kinh nghiệm AI; Python; thiết kế hệ thống; LLM; context engineering; RAG; fine-tuning; đánh giá/đo lường chất lượng mô hình AI (multi-agent); production (containerize, CI/CD, giám sát hệ thống); an toàn AI; đọc tài liệu tiếng Anh; tư duy logic; tư duy sản phẩm; giao tiếp; làm việc nhóm','','2026-11-02','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2300778','https://www.topcv.vn/viec-lam/applied-ai-engineer/2300778.html','2026-10-11T19:40:00+07:00','Applied AI Engineer','CÔNG TY TNHH EVERFIT TECHNOLOGIES VIỆT NAM','Đà Nẵng','4 năm','Thoả thuận','xây dựng hệ thống AI production-grade (agent workflows, RAG, tool calling, evals) ~70%; xây dựng và duy trì backend services ~30%; workflow AI bền vững trên Temporal (jobs định kỳ, quy trình đa bước); pipeline AI đáng tin cậy (validation, retries, fallbacks, guardrails, observability); tích hợp production OpenAI và Anthropic; đưa AI từ thử nghiệm lên production; evals và monitoring; dịch vụ backend Node.js/TypeScript; thử nghiệm công nghệ AI mới nổi; làm việc cùng PM, AI Engineers, QA; xử lý sự cố production; thúc đẩy thực hành phát triển AI-native','4+ năm backend engineering; Node.js/TypeScript/Python; REST APIs; microservices; distributed systems; databases (MongoDB, PostgreSQL, Redis); đã ship ít nhất 1 LLM feature lên production; sử dụng AI coding tools (Claude Code, Codex); giao tiếp tiếng Anh tốt; tò mò, chủ động; (ưu tiên) Python/FastAPI; RAG pipelines; agentic systems; Pydantic/LangGraph; Qdrant; Langfuse; MCP; AWS/Docker/message queues; cloud-native; recommendation systems','','2026-12-30','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Yêu cầu kinh nghiệm 4 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2306163','https://www.topcv.vn/viec-lam/ai-engineer/2306163.html','2026-10-11T19:40:00+07:00','AI Engineer','Công Ty Cổ Phần Công Nghệ VMO Holdings','Hà Nội','3 năm','Thoả thuận','Design, develop, deploy end-to-end ML/AI solutions (traditional ML, predictive analytics, time series forecasting, deep learning, Generative AI); Translate business problems thành AI solutions mở rộng được; Develop, optimize NLP, LLM, deep learning models; Build LLM-powered applications, RAG systems, Agentic AI workflows; Production-grade ML/AI pipelines (Python, PySpark); Data analysis, feature engineering, model development, evaluation, optimization, deployment; Leverage GenAI tools/Agentic AI frameworks; Communicate với technical/non-technical audiences; Research emerging technologies','3+ năm Data Science/ML/AI Engineering; Python; Machine Learning; Predictive Analytics; Deep Learning; Time Series modeling/forecasting; PySpark, large-scale data processing; Production-grade ML/AI deployment; NLP; Transformers; LLMs; Generative AI; GenAI focus: 2+ năm prompt engineering, GenAI development; Hiểu business requirements; Communication, problem-solving; Tiếng Anh; Ưu tiên: LLM apps, RAG, Agentic AI, NLP products; End-to-end AI product development; GenAI/Agentic AI frameworks; Azure/cloud; Vibe Coding, AI-assisted dev tools; Healthcare domain','','2026-11-30','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2306535','https://www.topcv.vn/viec-lam/ai-engineer-product-agentic-llm-nlp/2306535.html','2026-10-11T19:40:00+07:00','AI Engineer (Product, Agentic, LLM, NLP...)','Công ty Cổ phần Công nghệ KiotViet','Hà Nội','3 năm','Tới 40 triệu','Build & ship production AI systems; Architect, fine-tune, deploy ML/DL/LLMs; Quality bars (stability, latency, accuracy, scalability); Rollback/canary strategies; Multi-agent systems (LangGraph, LangChain); RAG pipelines, knowledge bases, tool use, memory; Prompt engineering; Evaluation frameworks (Langfuse); Conversational AI (chatbots, voice assistants); Computer Vision & Document AI: OCR, image-to-order parsing, receipt understanding, detection/OCR pipelines; NLP: search, text classification, intent detection, information extraction; MLOps/LLMOps: ML pipelines, data ingestion, feature stores, model registry, versioning, A/B testing, monitoring (drift, hallucination rates), prompt versioning; Cross-functional: partner PMs/BAs, data engineers, code review, mentor juniors, evaluate emerging models/frameworks','3+ năm ML/AI engineering (2+ năm shipping to prod); Python; PyTorch; TensorFlow; FastAPI; Async patterns; LLM applications (RAG, agent orchestration, prompt engineering); 2 trong: CV, OCR/document AI, NLP, conversational AI, MLOps (model registry, monitoring, A/B testing, observability); Đọc paper, prototype nhanh; Ưu tiên: LangGraph, LangChain, multi-agent systems, Langfuse, Weights & Biases, commerce/POS/retail/F&B domain, inference cost optimization (quantization, prompt compression, caching)','','2026-10-18','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2313245','https://www.topcv.vn/brand/nganhangthuongmaicophanquandoi/tuyen-dung/chuyen-vien-cao-cap-cong-nghe-mo-hinh-senior-machine-learning-engineer-khoi-du-lieu-2026td456629-j2313245.html','2026-10-11T19:40:00+07:00','Chuyên Viên Cao Cấp Công Nghệ Mô Hình - Senior Machine Learning Engineer - Khối Dữ Liệu (2026TD456629)','NGÂN HÀNG TMCP QUÂN ĐỘI – MBBANK','Hà Nội','3 năm','Thoả thuận','xây dựng và duy trì kiến trúc hạ tầng MLOps lai (hybrid); phát triển các đường ống tự động; phát triển, tích hợp và tối ưu hóa đường ống trích xuất đặc trưng (Feature Pipelines); refactor thành mã Production chuẩn OOP; đóng gói mô hình (Dockerization); thiết lập dashboard giám sát các chỉ số hệ thống (CPU, RAM, Latency, Throughput); xây dựng tiêu chuẩn mã nguồn (Coding Guidelines); xây dựng quy chuẩn bàn giao (SOP)','Python (OOP, Design Patterns); SQL; kinh nghiệm Machine Learning Engineer/Data Engineer/Backend; Experiment Tracking (MLflow, Weights & Biases); kỹ năng cần có: Python, Docker, MLOps, Gitlab CI, Hopsworks; ưu tiên: kinh nghiệm triển khai mô hình phân tích rủi ro tín dụng (Credit Risk); Đại học trở lên','','2026-10-25','ai_ml_engineer;data_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2313250','https://www.topcv.vn/brand/nganhangthuongmaicophanquandoi/tuyen-dung/pho-phong-cong-nghe-mo-hinh-deputy-head-of-machine-learning-engineering-khoi-du-lieu-2026td456609-j2313250.html','2026-10-11T19:40:00+07:00','Phó Phòng Công Nghệ Mô Hình - Deputy Head Of Machine Learning Engineering - Khối Dữ Liệu (2026TD456609)','NGÂN HÀNG TMCP QUÂN ĐỘI – MBBANK','Hà Nội','5 năm (yêu cầu thêm 2 năm kinh nghiệm quản lý)','Thoả thuận','đảm bảo thiết kế, xây dựng và chuyển đổi hệ thống sang nền tảng MLOps lai (hybrid); dẫn dắt pipeline đưa cụm mô hình trọng yếu (mô hình Chấm điểm rủi ro - Scoring, Hạn mức - Limit) và mô hình Kinh doanh từ MVP vào hệ thống lõi thực tế; đánh giá, thiết kế, quy hoạch kiến trúc nền tảng MLOps tập trung; chiến lược triển khai kiến trúc lai (Hybrid On-premise/Cloud); ra quyết định công nghệ cho kiến trúc Feature Store; đảm bảo tính nhất quán của dữ liệu phục vụ huấn luyện (Offline Batch) và dự đoán theo thời gian thực (Online Real-time); refactor mô hình sang chuẩn mã nguồn Production (OOP); triển khai qua đường ống CI/CD tự động; xây dựng và ban hành bộ Tiêu chuẩn vận hành (MLE SOP); chuẩn tài liệu hóa, chuyển giao logic trích xuất đặc trưng phức tạp lên Feature Store; điều phối kỹ thuật, bám sát milestones, nghiệm thu hạng mục bàn giao với đối tác vendor trong giai đoạn MVP','cử nhân khoa học dữ liệu/khoa học máy tính/thống kê/Toán tin; tối thiểu 5 năm Data Engineering/Backend/System Architecture/Machine Learning Engineering; 2-3 năm quản lý đội ngũ kỹ thuật (Engineering Manager/Tech Lead); kiến trúc phần mềm phân tán; vòng đời MLOps; Feature Store (Hopsworks, Feast); Experiment Tracking (MLflow, DVC); ưu tiên: thiết kế và đưa lên Production mô hình rủi ro tài chính, mô hình Kinh doanh quy mô lớn; kỹ năng cần có: Docker, MLOps, FastAPI, Gitlab CI, Triton Inference Server, Hopsworks; Đại học trở lên','2026-09-27','2026-10-25','ai_ml_engineer','de_aiml','ai_ml_engineer','chức danh quản lý','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2315482','https://www.topcv.vn/viec-lam/ai-specialist-lead-dinh-huong-de/2315482.html','2026-10-11T19:40:00+07:00','AI Specialist (Lead) - Định Hướng DE','Công ty TNHH Giải pháp Phân tích dữ liệu Insight Data','Hà Nội','1 năm','Thoả thuận','làm sạch, biến đổi, phân tích dữ liệu phục vụ Data/AI; xây dựng và xử lý Data Pipeline; ETL/ELT; phát triển và tích hợp giải pháp AI/ML/GenAI; phối hợp BA/DA triển khai bài toán Data/AI; phát triển chuyên môn theo hướng Data Engineer','tốt nghiệp CĐ/ĐH CNTT; 1+ năm kinh nghiệm Data/AI/Software; nền tảng SQL, Database, xử lý dữ liệu; Python/SQL; ETL/ELT, Data Pipeline; kiến thức cơ bản AI/ML/GenAI; tư duy logic; định hướng Data Engineer','','2026-10-29','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2315683','https://www.topcv.vn/brand/nganhangthuongmaicophanquandoi/tuyen-dung/ai-expert-khoi-cong-nghe-thong-tin-2026td450200-j2315683.html','2026-10-11T19:40:00+07:00','AI Expert - Khối Công Nghệ Thông Tin (2026TD450200)','NGÂN HÀNG TMCP QUÂN ĐỘI – MBBANK','Hà Nội','3 năm','Thoả thuận','định hướng, giám sát, điều phối và phát triển dự án/sản phẩm/dịch vụ AI; xây dựng và triển khai định hướng dự án AI; lập kế hoạch chi tiết và quản lý dự án; giám sát và hỗ trợ đội ngũ phát triển; phối hợp phòng ban Trung tâm AI (LLM, NLP, Computer Vision, Chatbot, R&D); cập nhật công nghệ AI mới; đảm bảo chất lượng và hiệu suất; xác định và đánh giá rủi ro triển khai; tuyển dụng, huấn luyện và phát triển đội ngũ','tối thiểu 3 năm AI/ML; hiểu biết sâu AI/ML/Computer Vision/NLP/LLM/Deep learning; chuyên môn quản trị dữ liệu; kỹ năng lập kế hoạch/tổ chức/quản lý; ra quyết định/giải quyết vấn đề/quản lý xung đột; truyền cảm hứng cho đội ngũ; hiểu biết quy định pháp lý/đạo đức AI; quản trị rủi ro và tiêu chuẩn ngành','','2026-10-29','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2315686','https://www.topcv.vn/brand/nganhangthuongmaicophanquandoi/tuyen-dung/senior-ai-expert-khoi-cong-nghe-thong-tin-2026td450201-j2315686.html','2026-10-11T19:40:00+07:00','Senior AI Expert - Khối Công Nghệ Thông Tin (2026TD450201)','NGÂN HÀNG TMCP QUÂN ĐỘI – MBBANK','Hà Nội','5 năm','Thoả thuận','cố vấn và xây dựng chiến lược/định hướng phát triển AI cho ban lãnh đạo; giám sát, điều phối và phát triển dự án/sản phẩm/dịch vụ AI; trực tiếp tham gia dự án AI trọng điểm; lập kế hoạch và quản lý dự án AI; giám sát và hỗ trợ đội ngũ phát triển; phối hợp Trung tâm AI (LLM, NLP, Computer Vision, Chatbot, R&D) và khối dữ liệu/phần mềm/kiểm thử/BA; cập nhật công nghệ AI mới; kiểm tra và đánh giá chất lượng định kỳ; tuyển dụng, huấn luyện và phát triển đội ngũ','tối thiểu 5 năm AI/ML; hiểu biết sâu AI/ML/Computer Vision/NLP/LLM/Deep learning; chuyên môn quản trị dữ liệu; kỹ năng lập kế hoạch/tổ chức/quản lý; ra quyết định/giải quyết vấn đề/quản lý xung đột; truyền cảm hứng cho đội ngũ; kinh nghiệm lãnh đạo AI (lợi thế); hiểu biết quy định pháp lý/đạo đức AI; quản trị rủi ro và tiêu chuẩn ngành','2026-10-04','2026-10-29','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2315690','https://www.topcv.vn/brand/nganhangthuongmaicophanquandoi/tuyen-dung/senior-ai-engineer-computer-vision-nlp-llm-khoi-cong-nghe-thong-tin-2026td450878-j2315690.html','2026-10-11T19:40:00+07:00','Senior AI Engineer (Computer Vision/NLP/LLM) - Khối Công Nghệ Thông Tin (2026TD450878)','NGÂN HÀNG TMCP QUÂN ĐỘI – MBBANK','Hà Nội','2 năm','Thoả thuận','phát triển, ứng dụng, tối ưu, tích hợp mô hình AI (Computer Vision, NLP) cho bài toán ngân hàng; tham gia kiến trúc hệ thống, thiết kế mô hình hoạt động, luồng hoạt động, tối ưu performance; coding, test metrics, service và unittest theo DevOps/MLOps; nghiên cứu bài báo khoa học AI/ML/DL mới nhất','từ 2 năm AI; Python, C/C++; FastAPI/Flask/Django; Tensorflow, Pytorch, DGL, PyG, Onnx; RESTful/gRPC API; Git, Git Flow; Docker, Kubernetes; Kubeflow/MLFlow; TritonServer, Tensorflow Serving; CNN/RNN/Transformer/Attention, SVM/KNN/Clustering, GNN; Knowledge Distillation, Model Prune, Model Quantization; Supervised learning, Reinforcement Learning; Computer Vision/video/audio/NLP','','2026-10-29','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2317685','https://www.topcv.vn/viec-lam/truong-nhom-ai-engineer/2317685.html','2026-10-11T19:40:00+07:00','Trưởng Nhóm AI Engineer','CÔNG TY CỔ PHẦN CÔNG NGHỆ META GAME','Hà Nội','3 năm','40 - 50 triệu','Xây dựng AI application & automation; Khảo sát luồng làm việc các bộ phận, xác định điểm nghẽn, ước lượng thời gian/chi phí; Tối ưu inference cost, latency, model performance; Human-in-the-loop cho workflow quan trọng; Phối hợp Marketing: AI-assisted creative/content generation, sinh/biến thể ad copy, concept/iteration creative, phân tích performance campaign/creative, tự động hóa reporting/insight, audience/player segmentation, A/B testing; Phối hợp Product/Game Design: phân tích feedback/review người chơi, phân loại/tổng hợp player feedback, game/content concepts, nghiên cứu/phân tích/prototype, tự động hóa content production, internal AI tools, AI-powered analytics/recommendation; Ứng dụng AI vào sản xuất Creative (image, video, animation, voice, 3D asset, Playable Ads) và sản xuất Game/App (Game Design, Art, Code, Level Design, QA/Test, prototype); Xây dựng AI Agent, internal tools, automation; Workflow nhiều AI Agent phối hợp; Kết nối AI với API, dữ liệu, hệ thống nội bộ; Đo lường Before/After, năng suất đo được và nhân rộng','3+ năm Software Engineering/AI/ML; Strong Python; Đưa AI/ML system vào production; LLM/Generative AI; RAG; AI Agents; Embeddings/Vector Database; Prompt engineering & evaluation; ML pipelines; AI API integration; Software engineering fundamentals (API, Database, Git, Testing, CI/CD, Cloud, Monitoring); Thiết kế hệ thống; Làm việc với Product/Marketing; Ưu tiên: game/mobile game; Recommendation/personalization; Computer Vision/image generation/multimodal AI; AI Agent/automation; Game product logic, player behavior, retention, monetization; Data-driven problem solving; Problem → PoC → Production; Review code, mentoring','','2026-10-31','ai_ml_engineer','de_aiml','ai_ml_engineer','chức danh quản lý','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2318001','https://www.topcv.vn/viec-lam/ai-engineer-tier2-qn/2318001.html','2026-10-11T19:40:00+07:00','AI Engineer (Tier2 - QN)','FPT Software','Gia Lai','3 năm','Thoả thuận','Thiết kế/triển khai/tối ưu generative AI models; cập nhật nghiên cứu generative AI thành giải pháp thực tiễn; tích hợp mô hình vào hệ thống production; đánh giá hiệu năng mô hình (độ chính xác, hiệu quả, chuẩn mực đạo đức); viết tài liệu nghiên cứu và kỹ thuật; giao tiếp kỹ thuật song ngữ Anh-Việt','LLM & NLP; thiết kế/tối ưu generative AI; deep learning architectures; machine learning; xử lý large datasets; cloud platforms (Azure AI, GCP Vertex AI, AWS SageMaker); Langchain; kỹ năng tiếng Anh giao tiếp xuất sắc; problem-solving','','2026-10-31','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2318667','https://www.topcv.vn/viec-lam/truong-phong-giai-phap-ai/2318667.html','2026-10-11T19:40:00+07:00','Trưởng Phòng Giải Pháp AI','CÔNG TY CỔ PHẦN CÔNG NGHỆ ALPHAWAY','Hà Nội','5 năm','40 - 70 triệu','Đề xuất use case AI phù hợp và lập kế hoạch triển khai cùng quản lý; Thiết kế giải pháp AI, lựa chọn công nghệ phù hợp (API LLM, mô hình open-source, RAG, agent); Trực tiếp phát triển, làm PoC và đưa giải pháp vào vận hành; Hướng dẫn, hỗ trợ các thành viên trong team; Phối hợp với team kinh doanh để tư vấn giải pháp kỹ thuật khi cần','5 năm trở lên phát triển phần mềm, ít nhất 2 năm AI/ML; 1 năm kinh nghiệm quản lý; Tham gia ít nhất 1 dự án AI triển khai thực tế; Python; LLM, RAG, vector database; LangChain, LlamaIndex; Docker; Hiểu biết cơ bản cloud; Đọc hiểu tài liệu tiếng Anh tốt','2026-10-04','2026-10-31','ai_ml_engineer','de_aiml','ai_ml_engineer','chức danh quản lý','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2318746','https://www.topcv.vn/viec-lam/truong-phong-giai-phap-ai/2318746.html','2026-10-11T19:40:00+07:00','Trưởng Phòng Giải Pháp AI','Công ty Cổ phần Công nghệ Alphaway','Hà Nội','5 năm','45 - 65 triệu','Đề xuất use case AI phù hợp và lập kế hoạch triển khai; Thiết kế giải pháp AI, lựa chọn công nghệ (API LLM, mô hình open-source, RAG, agent); Trực tiếp phát triển, làm PoC và đưa giải pháp vào vận hành; Hướng dẫn, hỗ trợ thành viên team; Phối hợp team kinh doanh tư vấn giải pháp kỹ thuật','5 năm phát triển phần mềm, 2 năm AI/ML; Dự án AI triển khai thực tế; Python; LLM, RAG, vector database; LangChain, LlamaIndex; Docker; Cloud; Đọc hiểu tài liệu tiếng Anh','','2026-10-31','ai_ml_engineer','de_aiml','ai_ml_engineer','chức danh quản lý','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2319243','https://www.topcv.vn/viec-lam/truong-nhom-du-lieu-va-tri-tue-nhan-tao/2319243.html','2026-10-11T19:40:00+07:00','Trưởng Nhóm Dữ Liệu Và Trí Tuệ Nhân Tạo','Công ty Cổ phần Y Dược Vietlife','Hà Nội','5 năm','Thoả thuận','Xây dựng lộ trình Dữ liệu, BI và AI theo giai đoạn chuyển đổi số; Quản trị Dữ liệu chủ (MDM); Thiết kế kiến trúc và mô hình dữ liệu (MDM, DWH, BI/KPI, dashboard, AI); Quản lý/phối hợp Data Engineer, BI Analyst, AI Engineer; Tích hợp dữ liệu đa nguồn (HIS, CRM, HRM, ERP, DMS); Xây dựng dashboard cho Ban lãnh đạo, bệnh viện, phòng ban; Triển khai bài toán AI thực tế (chatbot nội bộ, trợ lý nghiệp vụ, phân tích hành vi khách hàng, CSKH); Tuân thủ và bảo mật dữ liệu','Kinh nghiệm chuyên sâu Dữ liệu, BI, DWH, Data Platform, ứng dụng AI; SQL; PostgreSQL, SQL Server; Thiết kế mô hình dữ liệu, luồng ETL/ELT, kho dữ liệu, dashboard; Data Governance, kiểm soát chất lượng, phân quyền dữ liệu; LLM, RAG, Chatbot (lợi thế); Ưu tiên ứng viên ngành Y tế, Dược, Bán lẻ, Bảo hiểm, mô hình chuỗi','','2026-11-01','ai_ml_engineer','de_aiml','ai_ml_engineer','chức danh quản lý','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2319398','https://www.topcv.vn/viec-lam/ai-engineer-lead/2319398.html','2026-10-11T19:40:00+07:00','AI Engineer (Lead)','CÔNG TY CỔ PHẦN CÔNG NGHỆ ALPHAWAY','Hà Nội','3 năm','20 - 34 triệu','Triển khai giải pháp AI trong lĩnh vực Ngân hàng; Phát triển và tối ưu hóa mô hình AI; Phân tích yêu cầu nghiệp vụ; Đánh giá giải pháp bên thứ ba; Điều phối với các phòng ban để đưa sáng kiến AI vào vận hành','Tốt nghiệp CNTT/KHMT/AI (Khá trở lên); 3 năm kinh nghiệm AI Engineer/Data Scientist/Solution Engineer; Python; PyTorch, TensorFlow; Hệ sinh thái LLM (OpenAI, LangChain, LangGraph, Vector Database); Deploy và tối ưu mô hình (TensorRT); AWS/Azure/GCP; Tích hợp API','2026-10-04','2026-11-02','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2321417','https://www.topcv.vn/viec-lam/ai-engineer-tu-3-nam-kinh-nghiem/2321417.html','2026-10-11T19:40:00+07:00','AI Engineer Từ 3 Năm Kinh Nghiệm','Công ty TNHH Digital Innovation','Hà Nội','3 năm','Tới 30 triệu','nghiên cứu, phát triển và triển khai giải pháp AI (OCR, Computer Vision, Vision-Language Models); xây dựng và tối ưu pipeline xử lý hình ảnh, tài liệu, dữ liệu visual; phát triển giải pháp OCR nhận diện và trích xuất thông tin từ tài liệu, hình ảnh; xử lý bài toán Computer Vision (image classification, object detection, image preprocessing, document understanding); nghiên cứu và ứng dụng VLM vào bài toán hình ảnh, tài liệu, visual understanding; đánh giá chất lượng model, phân tích lỗi, tối ưu độ chính xác và hiệu năng','3 năm kinh nghiệm AI/ML; ưu tiên kinh nghiệm OCR/Computer Vision; kiến thức xử lý ảnh, image preprocessing; kinh nghiệm OCR framework/model; xử lý dữ liệu document/image; hiểu biết/kinh nghiệm thực tế với Vision-Language Models (VLM); Python; thư viện/framework AI/Computer Vision; đọc hiểu paper/documentation; tư duy phân tích; debugging; tối ưu model/pipeline; làm việc nhóm; học vấn Cao Đẳng trở lên','2026-10-05','2026-11-04','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2323085','https://www.topcv.vn/viec-lam/ai-software-engineer-fintech-lead/2323085.html','2026-10-11T19:40:00+07:00','AI Software Engineer – Fintech (Lead)','CÔNG TY CỔ PHẦN CHỨNG KHOÁN SMARTINVEST','Hà Nội','2 năm','25 - 40 triệu','phát triển nền tảng Fintech mới; AI-native development; Codex; Claude Code; coding agents; phân tích; lập trình; testing; review; làm việc với Product Owner; tìm hiểu kiến trúc và yêu cầu hệ thống; phát triển chức năng end-to-end; tìm hiểu yêu cầu nghiệp vụ; hỗ trợ thiết kế, coding, testing, review; phát triển database, backend/API, frontend; review, kiểm tra code do AI tạo; viết, duy trì automated tests; xử lý bug; refactor; cải tiến chất lượng code; cập nhật tài liệu kỹ thuật; nghiên cứu công nghệ mới','nền tảng lập trình; tư duy software engineering; backend stack; Java; Spring Boot; C#; .NET; Node.js; TypeScript; database quan hệ; SQL; API; Git; đọc, hiểu code; tự học công nghệ mới; chủ động; kiên trì; trách nhiệm; full-stack; Codex; Claude Code; Cursor; GitHub Copilot; AI coding; Docker; CI/CD; cloud; Fintech; chứng khoán; ngân hàng; hệ thống tài chính; xây dựng sản phẩm từ giai đoạn đầu','2026-10-06','2026-11-05','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2323277','https://www.topcv.vn/viec-lam/senior-ai-scientist/2323277.html','2026-10-11T19:40:00+07:00','Senior AI Scientist','FPT Software','Huế','3 năm','Thoả thuận','Tối ưu hệ thống AI Chatbot cho khách hàng; Thiết kế, tích hợp, tối ưu LLM models (GPT, Claude, Gemini, Llama, Gemma), Embedding, Vector Search; Phát triển RAG, Hybrid Search, Vector Databases (Milvus, PGVector, Chroma, OpenSearch); Xây dựng workflows với Agentic AI (LangGraph/LangChain), MCP protocol, Voice AI; Backend hiệu năng cao, realtime bằng Python (FastAPI, WebSocket, PostgreSQL)','Python Backend và phát triển hệ thống AI; Kinh nghiệm thực chiến AI Agent, RAG System, Voice AI, Multi-Agent Platform, Enterprise AI Assistant; LangGraph, LangChain, MCP, LLM APIs, Open-source models; Semantic/Hybrid Search, Milvus, PGVector, Chroma, OpenSearch; FastAPI, WebSocket, PostgreSQL; Problem Solving, Solution Design','2026-10-06','2026-12-16','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2324828','https://www.topcv.vn/viec-lam/ai-engineer-llm-agentic-ai-singing-bonus/2324828.html','2026-10-11T19:40:00+07:00','AI Engineer (LLM & Agentic AI) - Singing Bonus','Công ty Cổ phần Công nghệ KiotViet','Hà Nội','3 năm','32 - 40 triệu','build & ship production AI systems; architect, fine-tune, deploy ML/DL/LLM models; full lifecycle prototype→production; đảm bảo stability, latency, accuracy, scalability; rollback/canary strategies; graceful degradation; design multi-agent systems (LangGraph, LangChain); implement RAG pipelines, knowledge bases, tool use, memory cho agents; prompt engineering; evaluation frameworks (Langfuse/eval pipelines); build conversational AI (chatbots, voice assistants, sales assistants); develop/productionize models OCR, image-to-order parsing, receipt understanding, product image generation/scanning; tune detection/OCR pipelines cho ảnh mobile chất lượng thấp; build search, text classification, intent detection, structured information extraction; build/maintain ML pipelines (data ingestion, feature stores, model registry, versioning, A/B testing); monitoring model drift, hallucination rates, prompt versioning, eval, cost, latency; cost optimization inference (LLM API spend, GPU utilization); partner với Product Managers/BAs; review code, mentor junior engineers; evaluate emerging models/frameworks','3-5 năm ML/AI engineering; 2+ năm shipping AI features to production at scale; Python; PyTorch/TensorFlow; FastAPI; async patterns; backend infrastructure; LLM applications in production (RAG, agent orchestration, prompt engineering, eval); Computer Vision; OCR/Document AI; NLP; conversational AI; MLOps (model registry, monitoring, A/B testing, observability); read papers, prototype nhanh; ưu tiên: LangGraph, LangChain; multi-agent systems; Langfuse; Weights & Biases; domain commerce/POS/retail/F&B; inference cost optimization (model quantization, prompt compression, caching); Đại học trở lên','2026-10-08','2026-11-07','ai_ml_engineer','de_aiml','ai_ml_engineer','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2305329','https://www.topcv.vn/viec-lam/middle-ai-engineer-applied-ai/2305329.html','2026-10-11T19:40:00+07:00','Middle AI Engineer – Applied AI','CÔNG TY TNHH CÔNG NGHỆ UMBALABS','Hồ Chí Minh','1 năm','Thoả thuận','Xây dựng pipeline xử lý media (đọc metadata, cắt frame/segment, trích audio, tạo thumbnail); Tích hợp OCR, ASR, vision/multimodal model, AI API thành tín hiệu có cấu trúc; Thiết kế schema, validation, post-processing cho đầu ra AI; Prompt/inference workflow có quản lý phiên bản, logging, xử lý lỗi, khả năng tái lập; Evaluation set, metrics, failure analysis; Đóng gói logic thành worker/service có API/queue contract; Tối ưu độ trễ, thông lượng','Python; AI/ML; AI API; Computer vision; NLP; Speech; Tích hợp model/API vào ứng dụng/pipeline; Structured output, schema/validation, post-processing; Evaluation (test set, metrics, regression, failure analysis); Phân rã vấn đề, gỡ lỗi; API, background job; Bảo mật, dữ liệu; Giao tiếp kỹ thuật; Quản lý phiên bản prompt/model/config; Điểm cộng: FFmpeg, OpenCV, PyAV; OCR/ASR (Whisper), speech/vision API; Multimodal API/model, structured generation, tool calling; Embeddings/vector search, feature extraction; GPU inference, batching, model serving, inference optimization','','2026-10-17','ai_ml_engineer','de_aiml','ai_ml_engineer','','review','Cấp Middle/All Level cần kiểm tra');
INSERT INTO "jobs" VALUES('TopCV','2315670','https://www.topcv.vn/brand/nganhangthuongmaicophanquandoi/tuyen-dung/ai-engineer-all-level-computer-vision-nlp-llm-khoi-cong-nghe-thong-tin-2026td450582-j2315670.html','2026-10-11T19:40:00+07:00','AI Engineer (All Level - Computer Vision/NLP/LLM) - Khối Công Nghệ Thông Tin (2026TD450582)','NGÂN HÀNG TMCP QUÂN ĐỘI – MBBANK','Hà Nội','Không yêu cầu','Thoả thuận','thiết kế và triển khai giải pháp AI/ML end-to-end (LLM, pipeline RAG, semantic search, AI Agent, chatbot, fraud detection); thiết kế và triển khai giải pháp AI/ML thị giác máy tính (eKYC, OCR, segmentation, classification, camera AI); coding, test metrics, service và unit test theo mô hình DevOps/MLOps; tích hợp và tối ưu hóa quy trình làm việc AI bằng LangChain, LangGraph, LlamaIndex, Hugging Face; nghiên cứu và áp dụng nghiên cứu mới SOTA (Reinforcement Learning, Self-Supervised Learning, Parameter-Efficient Fine-Tuning); fresher tham gia chương trình đào tạo và dự án mới tại MB','Python; C/C++; Backend Service/Microservices (FastAPI, Flask, Django); PyTorch; TensorFlow; Supervised Learning; Reinforcement Learning; CNN; Transformer; Knowledge Distillation; Model Pruning; Model Quantization; Inference Optimization; Computer Vision; Image Processing; Video Analytics; eKYC; Document AI; NLP; Speech/Audio Processing; Fraud Detection; Git; Docker; Kubernetes; MLflow; Kubeflow; TensorFlow Serving; Triton Inference Server; Git Flow; Restful; gRPC; onnx; clustering; Attention; SVM; KNN; GNN; tốt nghiệp Đại học CNTT/KHMT/KTPM/HTTT/ĐTVT/AI/KHDL trở lên','','2026-10-29','ai_ml_engineer','de_aiml','ai_ml_engineer','','review','Cấp Middle/All Level cần kiểm tra');
INSERT INTO "jobs" VALUES('TopCV','1738456','https://www.topcv.vn/viec-lam/chuyen-vien-phan-tich-doanh-thu-revenue-analyst/1738456.html','2026-10-11T19:17:47+07:00','Chuyên Viên Phân Tích Doanh Thu (Revenue Analyst)','Công ty Cổ phần Tập đoàn Mường Thanh','Hà Nội: Tòa nhà Mường Thanh, Lô CC5 Bán đảo Linh Đàm, Phường Hoàng Liệt (Phường Hoàng Liệt có thể thuộc các quận Hoàng Mai, Thanh Trì cũ)','1 năm','Thoả thuận','Tổng hợp/quản lý/cập nhật dữ liệu kinh doanh, đảm bảo chính xác/đầy đủ/kịp thời; theo dõi phân tích chỉ số kinh doanh, doanh thu, khách hàng, thị trường, hiệu quả bán hàng; lập báo cáo kinh doanh định kỳ, bảng biểu, dashboard; quản lý dữ liệu khách hàng, hợp đồng, báo giá, khuyến mại; theo dõi thực hiện kế hoạch kinh doanh, phân tích biến động, đề xuất cải tiến; phối hợp thu thập/đối soát/chuẩn hóa dữ liệu; thực hiện báo cáo phân tích theo yêu cầu quản lý.','Ưu tiên kinh nghiệm Kinh doanh Nhà hàng/Khách sạn/Du lịch, E-commerce; hiểu biết nền tảng OTA (Booking.com, Agoda, Expedia); tốt nghiệp CĐ/ĐH Tài chính, Quản trị Du lịch/Khách sạn, Kinh tế...; thành thạo phân tích dữ liệu, phân tích tài chính; Excel nâng cao; kỹ năng lập kế hoạch, báo cáo chuyên nghiệp; giao tiếp, đàm phán, thuyết phục; tư duy logic, nhạy số liệu, làm việc độc lập, chịu áp lực. (Mục Tổng quan ghi độ tuổi 23–35.)','','2026-10-19','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','1935054','https://www.topcv.vn/viec-lam/data-analyst-realtime-analyst/1935054.html','2026-10-11T19:17:47+07:00','Data Analyst (Realtime Analyst)','Công ty TNHH GEAR INC VN','Đà Nẵng','1 năm','Thoả thuận','giám sát khối lượng công việc realtime và tuân thủ lịch trình qua công cụ nội bộ; điều phối, quản lý lịch sự kiện offline ngắn hạn cho moderation agents; phân tích xu hướng: volume, AHT, latency, utilization, shrinkages, attendance; lập kế hoạch nhân sự chống quá tải/thiếu hụt; trao đổi Help Desk nội bộ và bên ngoài về sự cố ảnh hưởng hiệu suất; báo cáo hiệu suất trung tâm (recent, current, future productivity); đảm bảo service level targets và schedule adherence','tốt nghiệp đại học (data analyst hoặc tương đương); tối thiểu 1 năm kinh nghiệm vị trí liên quan; giao tiếp tiếng Anh thành thạo; tạo và phân tích báo cáo chất lượng; kiến thức realtime management analysis, ra quyết định; quen thuộc content moderation (lợi thế); phân tích dữ liệu, tư duy logic; root cause analysis; MS Excel thành thạo cao; chú ý chi tiết','','2026-10-14','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2167677','https://www.topcv.vn/viec-lam/data-analyst-performance-ads/2167677.html','2026-10-11T19:17:47+07:00','Data Analyst (Performance Ads)','GEMS UNITED JOINT STOCK COMPANY','Đà Nẵng (134 đường 30 Tháng 4, Phường Hòa Cường)','Dưới 1 năm','8 - 16 triệu','Triển khai/theo dõi/tối ưu chiến dịch quảng cáo trả phí (Google, Facebook); phân tích hiệu quả truyền thông trả phí đa nguồn; theo dõi hiệu suất chiến dịch, hỗ trợ xây dựng báo cáo; nhận định dựa trên dữ liệu để định hướng chiến lược/ngân sách/nội dung.','Tốt nghiệp Kinh tế/Thống kê/Digital Marketing/sư phạm Toán/kỹ thuật; ưu tiên môi trường Digital Marketing/TMDT/POD; TOEIC >750 hoặc IELTS 6.5; kinh nghiệm phân tích dữ liệu quảng cáo TMDT/POD; tư duy logic; Excel/Google Sheets; chủ động, giao tiếp tốt.','2026-10-04','2026-11-02','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2180185','https://www.topcv.vn/viec-lam/data-analyst/2180185.html','2026-10-11T19:17:47+07:00','Data Analyst','CÔNG TY TNHH UNIMOB VIỆT NAM (UNIMOB STUDIO)','Hà Nội','2 năm','Thoả thuận','thu thập, xây dựng pipeline, phân tích dữ liệu kinh doanh; thiết kế báo cáo, dashboard, chỉ số KPI theo nhu cầu phòng ban; xây dựng và duy trì báo cáo tự động; phân tích xu hướng game, chi tiêu người dùng, sự kiện trong game; đưa ra insight cải tiến và phát triển game; đề xuất cải tiến tối ưu hiệu suất game và hiệu quả kinh doanh; đề xuất A/B test; dự đoán phục vụ marketing chạy campaign','tối thiểu 2 năm Data Analyst trong ngành mobile game; BigQuery, Looker Studio (Data Studio); xây dựng luồng ETL, chuẩn hoá, làm sạch dữ liệu; Python xử lý dữ liệu, connect API; giải thích kết quả phân tích rõ ràng, logic; giao tiếp, trình bày tốt; teamwork; Airflow, Machine Learning (ưu tiên)','','2026-10-25','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2198057','https://www.topcv.vn/viec-lam/quan-tri-du-lieu-mis-hieu-suat-kinh-doanh-bfm/2198057.html','2026-10-11T19:17:47+07:00','Quản Trị Dữ Liệu MIS & Hiệu Suất Kinh Doanh BFM','VNDIRECT','Hà Nội (Phường Cầu Giấy)','2 năm','Thoả thuận','Vai trò MIS — trụ cột công nghệ/dữ liệu của bộ phận Tài chính Kinh doanh: thu thập/làm sạch/tích hợp dữ liệu từ hệ thống lõi, thiết kế dashboard (Power BI/Tableau/Looker Studio) theo dõi realtime hiệu suất, doanh thu, chi phí, KPI; giám sát chất lượng dữ liệu; số hóa KPI, cảnh báo sớm; phân tích insight, đánh giá incentive; cầu nối với Data Engineer, tối ưu Data Warehouse/ETL, tự động hóa báo cáo thủ công.','Đại học MIS/CNTT/khoa học dữ liệu/thống kê/kinh tế tài chính định lượng; 2–5 năm MIS/Data Analyst/Business Analyst, ưu tiên tài chính/chứng khoán/ngân hàng; SQL nâng cao; Power BI/Tableau; Excel nâng cao (Power Query/Pivot, VBA là lợi thế); Python/R là điểm cộng; tư duy logic, giao tiếp, chịu áp lực.','2026-10-04','2026-10-31','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2289634','https://www.topcv.vn/viec-lam/chuyen-vien-phan-tich-quan-tri/2289634.html','2026-10-11T19:17:47+07:00','Chuyên Viên Phân Tích Quản Trị','BỆNH VIỆN ĐA KHOA HỒNG NGỌC PHÚC TRƯỜNG MINH','Hà Nội (Số 8 đường Châu Văn Liêm, Phường Từ Liêm)','2 năm','Thoả thuận','Xây dựng báo cáo, phân tích dữ liệu đa chiều (dữ liệu phòng marketing); làm rõ yêu cầu nghiệp vụ, thu thập dữ liệu đa nguồn; quản lý/xây dựng data warehouse, data mart, bảo mật thông tin; tham gia dự án chuyển đổi số, tích hợp hệ thống, tự động hóa quy trình.','Cao đẳng trở lên, kinh nghiệm 2 năm; nhạy bén với dữ liệu; Looker Studio/Power BI/Tableau; lập trình; cập nhật công nghệ mới, cloud là lợi thế; MySQL/SQL Server; thu thập/biến đổi/lưu trữ dữ liệu; giao tiếp, làm việc nhóm.','','2026-11-04','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2290377','https://www.topcv.vn/viec-lam/chuyen-vien-phan-tich-du-lieu/2290377.html','2026-10-11T19:17:47+07:00','Chuyên Viên Phân Tích Dữ Liệu','CÔNG TY CỔ PHẦN ALC PHÚ QUÝ','Hà Nội: 10 Xuân Thuỷ, Cầu Giấy, Phường Cầu Giấy (Phường Cầu Giấy thuộc quận Cầu Giấy cũ)','2 năm','15 - 25 triệu','1. Xây dựng và quản trị Master Data ngành hàng: chuẩn hóa/duy trì dữ liệu danh mục sản phẩm, NCC, mã hàng, nhóm ngành; kiểm tra, đối soát dữ liệu đầu vào, đảm bảo toàn vẹn/đồng nhất. 2. Phân tích dữ liệu và báo cáo ngành hàng: thiết kế/xây dựng báo cáo quản trị ngành hàng (mua hàng, tồn kho, doanh số, vòng đời...); phối hợp phân tích hành vi người tiêu dùng, xu hướng ngành hàng. 3. Xây dựng mô hình dự báo tự động: phối hợp mua hàng xây mô hình dự báo xu hướng bán hàng; triển khai dashboard và hệ thống cảnh báo KPI theo thời gian thực. 4. Quản trị hệ thống BI và công cụ phân tích: quản lý/tối ưu hệ thống BI (Power BI); training và hỗ trợ người dùng nội bộ. 5. Cải tiến quy trình dữ liệu vận hành ngành hàng. 6. Nghiệp vụ quản trị trên ERP.','Tốt nghiệp ĐH Kinh tế, Thống kê, CNTT, HTTTQL, Toán tin...; tối thiểu 2–3 năm vị trí liên quan BI/Data Analyst, ưu tiên kinh nghiệm ngành hàng tiêu dùng; kỹ năng xử lý/phân tích dữ liệu (SQL, Python, R...); trực quan hóa (Power BI/Tableau/Looker...); quản trị hệ thống ERP (SAP, Odoo, Oracle...); hiểu quy trình phát triển sản phẩm, mua hàng, merchandising; tư duy logic, đưa ra insight, dự báo; kỹ năng trình bày, giao tiếp với non-tech users; chính xác, tỉ mỉ, bảo mật dữ liệu. (Mục Tổng quan ghi độ tuổi 24–36.)','2026-10-09','2026-11-09','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2300763','https://www.topcv.vn/brand/congtycophangsm/tuyen-dung/data-analyst-van-hanh-xanh-bike-lam-viec-tai-royal-city-ha-noi-j2300763.html','2026-10-11T19:17:47+07:00','Data Analyst - Vận Hành Xanh Bike - Làm Việc Tại Royal City Hà Nội','CÔNG TY CỔ PHẦN DI CHUYỂN XANH VÀ THÔNG MINH GSM','Hà Nội: Tòa Royal City, Nguyễn Trãi, Phường Thanh Xuân (Phường Thanh Xuân thuộc quận Thanh Xuân cũ)','Không yêu cầu','Thoả thuận','(1) Phân tích dữ liệu & tối ưu hiệu suất: phân tích, dự báo, đưa ra insight vận hành qua hệ thống dữ liệu, xác định vấn đề trọng yếu; xây dựng chính sách, quy chuẩn tài xế; rà soát vận hành định kỳ; dẫn dắt sáng kiến cải tiến; (2) Điều phối dự án (PMO): điều phối, kiểm soát tiến độ dự án; phân tích, đánh giá hiệu quả tối ưu dự án vận hành; phối hợp với công nghệ triển khai dự án tự động hóa, cải tiến sản phẩm/app tối ưu quy trình; phối hợp phòng ban nội bộ và đối tác bên ngoài triển khai kế hoạch phát triển.','Tốt nghiệp Đại học Kinh tế, Tài chính, Kiểm toán, CNTT hoặc ngành liên quan; ưu tiên kinh nghiệm PMO, data analyst, business analyst tại công ty logistics/vận chuyển; tư duy hệ thống, lập luận logic, khả năng lập kế hoạch; thành thạo SQL, Power BI, PowerPoint; kỹ năng phân tích, báo cáo dữ liệu, xử lý tập dữ liệu lớn, rút ra insight thực tế; chủ động, tự quản lý công việc end-to-end, làm việc trực tiếp với stakeholder.','2026-10-07','2026-10-21','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2302348','https://www.topcv.vn/viec-lam/data-analytics-e-commerce-domain-saas-oms-wms/2302348.html','2026-10-11T19:17:47+07:00','Data Analytics (E-Commerce Domain, Saas, OMS/WMS)','CÔNG TY CỔ PHẦN CÔNG NGHỆ UPBASE','Hà Nội (Tầng 3, Hanoi Centerpoint, Lê Văn Lương, Phường Thanh Xuân)','2 năm','15 - 30 triệu','Phối hợp các phòng ban thu thập yêu cầu, phân tích dữ liệu, cung cấp insight hỗ trợ ra quyết định; xây dựng/tối ưu/duy trì dashboard, báo cáo theo dõi doanh thu, traffic, conversion, retention, hiệu quả chiến dịch; phân tích chuyên sâu (ad-hoc), phát hiện xu hướng, xác định root cause, đề xuất giải pháp; xây dựng văn hóa data-driven; phối hợp Data/Tech đảm bảo chất lượng dữ liệu, chuẩn hóa tracking.','Ưu tiên tốt nghiệp đại học Kỹ thuật/Kinh tế/CNTT; chịu áp lực, kiên trì; kiến thức nền tảng hệ quản trị CSDL và mô hình hóa dữ liệu; học và dùng ít nhất một công cụ BI (Power BI/Redash/Superset); tư duy lập trình là lợi thế. Tech stack: Container/K8S, ClickHouse, SQL/Spark, Airflow, Superset.','','2026-10-15','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2303888','https://www.topcv.vn/viec-lam/data-analyst-f21-up-to-1500-net-1-yoe/2303888.html','2026-10-11T19:17:47+07:00','Data Analyst (F21 - Up To 1500$ Net | 1 YOE)','Công ty Cổ phần Falcon Technology','Hà Nội','1 năm','Tới 35 triệu','phân tích dữ liệu từ data warehouse: hành vi người chơi, xu hướng thị trường, yếu tố ảnh hưởng doanh thu; phát triển và duy trì báo cáo định kỳ, dashboard theo dõi KPI game; phối hợp team server đảm bảo thu thập dữ liệu chính xác; mô hình hóa, dự đoán, tối ưu kết quả kinh doanh bằng thống kê; phân tích dữ liệu phức tạp thành khuyến nghị cụ thể; thiết kế giải pháp tối ưu, tự động hóa, khả năng mở rộng; phối hợp MKT, Kế toán cung cấp dữ liệu phát triển sản phẩm','tốt nghiệp đại học Kinh tế, CNTT; ít nhất 1 năm phân tích dữ liệu; giỏi toán, tư duy tốt, giải quyết vấn đề; SQL, hệ quản trị CSDL lớn; Power BI, Excel; Python/R (lợi thế); làm việc độc lập, môi trường nhanh; teamwork','2026-09-20','2026-10-16','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2304208','https://www.topcv.vn/viec-lam/data-analyst/2304208.html','2026-10-11T19:17:47+07:00','Data Analyst','CÔNG TY TNHH BRALY','Hà Nội','2 năm','20 - 35 triệu','thu thập, xử lý, phân tích dữ liệu từ hệ thống/Mobile App; phân tích hành vi người dùng, xu hướng, pattern, điểm bất thường; phân tích User Funnel, Conversion, Retention, Engagement, Churn; xây dựng dashboard/report theo dõi KPI sản phẩm; phân tích hiệu quả feature mới trước/sau release; phối hợp Product/PO/PM, Developer xác định nhu cầu dữ liệu, metrics, tracking; phân tích ad-hoc, tìm nguyên nhân vấn đề; đảm bảo chính xác, đầy đủ, nhất quán dữ liệu; đề xuất cải thiện sản phẩm, trải nghiệm người dùng, hiệu quả kinh doanh','2+ năm Data Analyst/Product Analyst/Business Data Analyst; SQL; Data Analysis, Data Modeling, Data Mining, Data Segmentation; Power BI, Tableau, Looker Studio; Statistics; xử lý dữ liệu lớn với độ chính xác cao; tốt nghiệp CS/IT/Toán/Thống kê/Kinh tế; phân tích Mobile App/Digital Product (cộng); User Behavior, Funnel/Cohort/Retention/Churn/Conversion (cộng); Firebase Analytics, GA4, Mixpanel, Amplitude (cộng); BigQuery/Data Warehouse (cộng); Python (cộng); A/B Testing (cộng); Event Tracking/Tracking Plan (cộng); Agile/Scrum (cộng)','','2026-10-16','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2304450','https://www.topcv.vn/viec-lam/data-analyst/2304450.html','2026-10-11T19:17:47+07:00','Data Analyst','VIEN SON COMPUTER TECHNOLOGY COMPANY LIMITED','Hồ Chí Minh','2 năm','Thoả thuận','thu thập dữ liệu từ ERP, CRM, Google Sheet, Excel, Database, phần mềm nội bộ; làm sạch, chuẩn hóa, kiểm tra chính xác dữ liệu; kiểm soát chất lượng dữ liệu; xây dựng hệ thống dữ liệu phục vụ báo cáo; phân tích số liệu kinh doanh, vận hành, hiệu suất hoạt động; theo dõi chỉ số, phân tích xu hướng/biến động/nguyên nhân; đề xuất insight và khuyến nghị cải tiến dựa trên dữ liệu; báo cáo phân tích định kỳ và theo yêu cầu; thiết kế dashboard (Power BI, Excel Dashboard); tự động hóa báo cáo; hỗ trợ xây dựng hệ thống KPI; tham gia dự án chuyển đổi số, ERP, BI, data warehouse, automation','trình độ đại học; tiếng Anh (IELTS 6.5+/TOEIC 800+), tin học văn phòng; Excel nâng cao; Power BI/Looker Studio; hiểu dữ liệu, KPI, Business Metrics, Dashboard Visualization; kiến thức Data, Automation, AI Tools; trình bày, trực quan hóa dữ liệu; làm việc độc lập và liên phòng ban; chủ động học công nghệ mới','','2026-10-17','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2304879','https://www.topcv.vn/viec-lam/chuyen-vien-phan-tich-du-lieu/2304879.html','2026-10-11T19:17:47+07:00','Chuyên Viên Phân Tích Dữ Liệu','CÔNG TY CỔ PHẦN THỜI TRANG QUỐC TẾ GLAMOR','Hồ Chí Minh','1 năm','12 - 20 triệu','Phân tích dữ liệu kinh doanh Sàn/Online/Offline, tập trung sàn TMĐT (Shopee, TikTok Shop); thu thập, xử lý, đối soát dữ liệu đơn hàng, doanh thu, giá vốn, phí sàn, phí vận chuyển, voucher, quảng cáo, affiliate; xây dựng báo cáo lãi/lỗ thực tế theo đơn hàng, SKU, sàn; phân tích hiệu quả sản phẩm/khuyến mãi/quảng cáo; đề xuất tối ưu giá bán, chi phí, lợi nhuận; xây dựng/tự động hóa báo cáo Dashboard bằng Excel, Google Sheets hoặc Power BI.','Tốt nghiệp CĐ/ĐH Tài chính, Kế toán, Kiểm toán hoặc liên quan, chuyên môn sâu Tài chính – Kế toán – Kiểm toán; ưu tiên ≥1 năm kinh nghiệm phân tích dữ liệu; thành thạo Excel, có kinh nghiệm phần mềm Sapo và báo cáo sàn TMĐT; tư duy logic, phản biện; làm việc độc lập và nhóm; gửi CV tiếng Việt.','2026-09-20','2026-10-23','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2305962','https://www.topcv.vn/viec-lam/nhan-vien-ke-toan-phan-tich-du-lieu-tai-chinh-nghi-thu-bay-va-chu-nhat-co-xe-dua-don/2305962.html','2026-10-11T19:17:47+07:00','Nhân Viên Kế Toán (Phân Tích Dữ Liệu Tài Chính) - Nghỉ Thứ Bảy Và Chủ Nhật, Có Xe Đưa Đón','CÔNG TY TNHH MEKTEC MANUFACTURING (VIỆT NAM)','Hưng Yên, Hà Nội','1 năm','Thoả thuận','theo dõi, kiểm soát, phân tích biến động hàng tồn kho; cập nhật, kiểm soát, phân tích chi phí biến động hàng tháng/quý/năm; theo dõi, lập kế hoạch, cập nhật ngân sách (budgeting) định kỳ; tính giá thành thực tế, phân tích yếu tố cấu thành giá thành; thu thập, xử lý, phân tích dữ liệu tài chính cho báo cáo quản trị; báo cáo nghiệp vụ và báo cáo phân tích theo yêu cầu cấp trên','tốt nghiệp đại học Tài chính, Kế toán, Kiểm toán; 1+ năm kế toán tổng hợp/quản trị/giá thành/phân tích dữ liệu tài chính; tin học văn phòng; Excel nâng cao (lợi thế); tiếng Anh đọc hiểu tài liệu chuyên ngành (TOEIC 500+); tư duy phân tích số liệu tốt, cẩn thận, teamwork','2026-09-20','2026-10-18','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2306227','https://www.topcv.vn/viec-lam/chuyen-vien-he-thong-phan-tich-du-lieu-nhan-su/2306227.html','2026-10-11T19:17:47+07:00','Chuyên Viên Hệ Thống & Phân Tích Dữ Liệu Nhân Sự','Công ty CP Dây cáp điện Việt Nam (CADIVI)','Hồ Chí Minh','2 năm','Thoả thuận','quản trị & chuẩn hóa dữ liệu nhân sự: headcount, turnover, hiệu suất, C&B, L&D; thiết lập tiêu chuẩn dữ liệu thống nhất giữa đơn vị/phòng ban; kiểm soát đầy đủ, chính xác, toàn vẹn dữ liệu nhân sự (KPI/OKR); xây dựng hệ thống báo cáo nhân sự định kỳ và theo yêu cầu; phân tích xu hướng nhân sự, hiệu quả tuyển dụng, hiệu suất làm việc; cung cấp insights hỗ trợ ra quyết định quản trị nhân sự; quản trị, tối ưu dữ liệu trên HRIS, ATS; kiểm soát quy trình nhập liệu, truy xuất dữ liệu; đề xuất cải tiến quy trình dữ liệu, tự động hóa báo cáo; phối hợp dự án chuyển đổi số và cải tiến hệ thống quản trị nhân sự','tốt nghiệp đại học QTNS, Thống kê, Kinh tế, Dữ liệu; 2-3 năm vị trí tương đương; HR Metrics, quy trình vận hành nhân sự; Excel, Power BI; giao tiếp tốt, làm việc với HR và stakeholders','','2026-10-18','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2310256','https://www.topcv.vn/viec-lam/business-development-and-data-analysis-intern/2310256.html','2026-10-11T19:17:47+07:00','Business Development And Data Analysis Intern','CÔNG TY CỔ PHẦN WECARE GROUP','Hồ Chí Minh','Không yêu cầu','2 - 3.5 triệu','Thực tập sinh làm việc trực tiếp với senior operator trên 2 mảng: phát triển kinh doanh (nghiên cứu khách hàng tiềm năng nhà máy, theo dõi pipeline/funnel, hỗ trợ đề xuất/báo giá) và phân tích dữ liệu (làm sạch, đối chiếu dữ liệu ERP/CRM/thị trường; tính toán funnel chuyển đổi, doanh thu, độ phủ; xây dựng workbook Excel và dashboard; đưa insight một dòng kèm hành động đề xuất).','Đang học hoặc mới tốt nghiệp các ngành business analytics, finance, economics, data analytics hoặc liên quan; Excel tốt, biết SQL/Python/BI là lợi thế; tư duy phân tích, có cấu trúc; giao tiếp viết tiếng Việt và tiếng Anh rõ ràng; chủ động, tỉ mỉ, ham học hỏi; quan tâm B2B công nghiệp/sản xuất là lợi thế.','','2026-10-24','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: tiêu đề intern; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2313002','https://www.topcv.vn/viec-lam/data-analyst-tieng-anh-tot/2313002.html','2026-10-11T19:17:47+07:00','Data Analyst - Tiếng Anh Tốt','Công ty Cổ phần Data Impact','Hà Nội','2 năm','Thoả thuận','thu thập, tổng hợp, làm sạch dữ liệu từ nhiều nguồn; tư duy business-first: thấu hiểu mục tiêu kinh doanh trước khi phân tích; xây dựng, duy trì, tối ưu dashboard, report, tài liệu theo dõi KPI; viết truy vấn SQL khai thác dữ liệu; diễn giải kết quả phân tích thành insight ứng dụng cho business; phối hợp khách hàng, PM, BA, DE làm rõ yêu cầu người dùng; kiểm tra chất lượng dữ liệu đầu vào, đề xuất cải thiện; ứng dụng AI tối ưu hiệu suất, tự động hóa quy trình; đề xuất tự động hóa báo cáo, tối ưu quy trình phân tích','tốt nghiệp đại học Kinh tế, Toán, Thống kê, CNTT, Hệ thống thông tin; tối thiểu 2 năm Data Analyst/Business Analyst; SQL thành thạo; kinh nghiệm BI tool (Power BI, Tableau); giao tiếp tốt, chuyển yêu cầu business thành phân tích; tiếng Anh 6.5 IELTS hoặc tương đương; Python phân tích dữ liệu/tự động hóa báo cáo (ưu tiên); môi trường Agile/Scrum với khách hàng nước ngoài (ưu tiên); kinh nghiệm phân tích business sản xuất, logistics; FDE (ưu tiên)','','2026-10-25','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2313259','https://www.topcv.vn/viec-lam/data-analyst/2313259.html','2026-10-11T19:17:47+07:00','Data Analyst','CÔNG TY TNHH ROOSTERX GLOBAL','Hà Nội (Tầng 5A, Tòa 25T2 Nguyễn Thị Thập, Phường Cầu Giấy)','2 năm','25 - 35 triệu','Thu thập/xử lý/phân tích dữ liệu từ hệ thống/Mobile App để cung cấp insight hỗ trợ Product và Business ra quyết định; phân tích hành vi người dùng, xu hướng, pattern, điểm bất thường; phân tích User Funnel/Conversion/Retention/Engagement/Churn để đánh giá hiệu quả sản phẩm; xây dựng/duy trì dashboard/report, theo dõi chỉ số và KPI quan trọng; phân tích hiệu quả feature mới, đánh giá thay đổi chỉ số trước/sau release; phối hợp Product/PO/PM/Developer xác định nhu cầu dữ liệu, metrics, yêu cầu tracking; phân tích ad-hoc, tìm nguyên nhân vấn đề, đưa insight/recommendation; đảm bảo tính chính xác/đầy đủ/nhất quán của dữ liệu; đề xuất cơ hội cải thiện sản phẩm, UX và hiệu quả kinh doanh.','Từ 2 năm kinh nghiệm Data Analyst/Product Analyst/Business Data Analyst hoặc tương đương; thành thạo SQL (truy vấn, tổng hợp, xử lý dữ liệu); kiến thức Data Analysis/Modeling/Mining/Segmentation; công cụ reporting/visualization (Power BI, Tableau, Looker Studio); kiến thức Statistics và phương pháp thống kê; thu thập/làm sạch/tổ chức/phân tích dữ liệu lớn với độ chính xác cao; tư duy phân tích và giải quyết vấn đề, chuyển dữ liệu thành insight; viết report và trình bày rõ ràng; tốt nghiệp Computer Science/IT/Mathematics/Statistics/Economics hoặc liên quan; điểm cộng: phân tích Mobile App/Digital Product, User Behavior/Funnel/Cohort/Retention/Churn/Conversion, Firebase Analytics/GA4/Mixpanel/Amplitude, BigQuery/Data Warehouse, Python, A/B Testing, Event Tracking/Tracking Plan, Agile/Scrum.','','2026-10-25','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2315450','https://www.topcv.vn/viec-lam/business-analyst-data-he-thong-phan-phoi-che-do-tot/2315450.html','2026-10-11T19:17:47+07:00','Business Analyst - Data Hệ Thống Phân Phối - Chế Độ Tốt','CÔNG TY CỔ PHẦN THƯƠNG MẠI QUỐC TẾ LB GLOBAL','Hà Nội: Phường Cầu Giấy (Phường Cầu Giấy thuộc quận Cầu Giấy cũ) - Phạm vi làm việc trên toàn khu vực trên.','Dưới 1 năm','12 - 22 triệu','Khảo sát, phân tích nhu cầu và quy trình các phòng ban (Sales, Marketing, HCNS, Kế toán); thiết kế tool/workflow ứng dụng AI trên ChatGPT/Claude; xây dựng, chuẩn hóa, tối ưu prompt AI theo nghiệp vụ; giải pháp tự động hóa báo cáo, tổng hợp, trích xuất dữ liệu; hệ thống lưu trữ, kết nối, tra cứu thông tin liên phòng ban; kết nối AI với Google Sheets/Excel, Google Drive, công cụ quản lý nội bộ; dùng n8n/Make/Zapier/Apps Script/API/Webhook xây dựng automation; test, tối ưu, hướng dẫn và đưa tool vào sử dụng; nghiên cứu, đề xuất ứng dụng AI mới.','Tư duy Business Analyst, logic hệ thống, Automation; sử dụng tốt ChatGPT/Claude hoặc AI/LLM tương đương; viết và tối ưu prompt; Excel/Google Sheets tốt, tư duy xử lý và tổ chức dữ liệu; biết n8n/Make/Zapier/Apps Script là lợi thế; kiến thức API, Webhook, JSON, Database là lợi thế; ưu tiên ứng viên tự xây dựng tool AI/workflow/automation có demo; không bắt buộc Developer chuyên sâu nhưng cần chuyển yêu cầu nghiệp vụ thành giải pháp.','2026-10-04','2026-10-31','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2315981','https://www.topcv.vn/viec-lam/business-data-analyst/2315981.html','2026-10-11T19:17:47+07:00','Business Data Analyst','Công ty Cổ phần viễn thông FPT','Hà Nội','2 năm','30 - 45 triệu','Phân tích dữ liệu phục vụ quản trị và ra quyết định trong 5 mảng: hạ tầng & đầu tư, mạng lưới, vận hành, khách hàng & dịch vụ, kinh doanh & tài chính; xây dựng KPI & framework phân tích (root cause analysis, phát hiện bất thường/xu hướng); chuyển hóa kết quả thành insight và khuyến nghị hành động, phối hợp các đơn vị nghiệp vụ kiểm chứng giả thuyết.','Tốt nghiệp Đại học trở lên các ngành Data Science, Toán – Thống kê, Kinh tế, Tài chính, CNTT, Hệ thống thông tin, Viễn thông hoặc liên quan; 2–5 năm kinh nghiệm Data Analytics/BI/Business Analytics; ưu tiên Telco/ISP; thành thạo SQL, Python, Power BI/Superset/Tableau; hiểu Data Quality, Data Modeling/Data Warehouse; kỹ năng data storytelling, làm việc đa bên.','2026-10-04','2026-10-29','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2317839','https://www.topcv.vn/viec-lam/chuyen-vien-phan-tich-du-lieu-bi/2317839.html','2026-10-11T19:17:47+07:00','Chuyên Viên Phân Tích Dữ Liệu (BI)','CÔNG TY CỔ PHẦN CÔNG NGHỆ ALPHAWAY','Hà Nội','2 năm','25 - 43 triệu','xây dựng hệ thống chỉ tiêu, KPI, metrics đo lường hiệu quả hoạt động/kinh doanh; khai thác, phân tích dữ liệu từ hệ thống nghiệp vụ (định kỳ và chuyên sâu); mapping dữ liệu; xây dựng/phát triển/vận hành mô hình dữ liệu, dashboard, sản phẩm phân tích; kiểm thử, đối soát Data Mart với dữ liệu nguồn','đại học/thạc sĩ Tài chính ngân hàng/Thống kê/KHDL; 2+ năm BI/Data Analytics/Reporting; Power BI (ưu tiên), SQL tốt, Python/R; data modeling, ETL, OLAP; ngân hàng/tài chính hoặc dự án dữ liệu lớn (ưu tiên); ML models (XGBoost, LightGBM, CatBoost, transformer) (ưu tiên); data governance/metadata; mảng Bán buôn/Bán lẻ/Vận hành (ưu tiên)','2026-10-04','2026-10-30','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2321660','https://www.topcv.vn/brand/thoitrangsixdo/tuyen-dung/chuyen-vien-phan-tich-du-lieu-ban-le-j2321660.html','2026-10-11T19:17:47+07:00','Chuyên Viên Phân Tích Dữ Liệu Bán Lẻ','CÔNG TY CỔ PHẦN THỜI TRANG SIXDO.','Hà Nội: Lô 5, KCN Vĩnh Tuy, Đ. Lĩnh Nam, Phường Hoàng Mai (Phường Hoàng Mai thuộc quận Hoàng Mai cũ)','1 năm','13 - 25 triệu','Tổng hợp báo cáo, theo dõi chỉ số vận hành tại cửa hàng, cập nhật/quản lý dữ liệu trên hệ thống; quản lý tồn kho và hàng hoá; theo dõi, giám sát, triển khai điều phối hàng hóa hệ thống; tổng hợp, đánh giá, báo cáo, phân tích chỉ số kinh doanh, đề xuất giải pháp; dự báo, cảnh báo tồn kho để đề nghị bổ sung tái sản xuất/nhập hàng; tổng hợp dữ liệu bán hàng, tồn kho, so sánh cùng kỳ, đề xuất danh mục hàng cho chương trình; hỗ trợ triển khai chương trình kinh doanh, theo dõi kết quả khuyến mãi; thiết kế báo cáo, dashboard trực quan hỗ trợ ra quyết định; tham gia họp kinh doanh, cập nhật thông tin thị trường.','Tốt nghiệp Kinh tế, Quản trị kinh doanh, Thương mại...; kiến thức về chuỗi bán lẻ; thành thạo tin học văn phòng, Excel, Google Sheet, Power BI; tư duy logic, cẩn thận, xử lý số liệu tốt; kỹ năng tìm kiếm và phân tích thông tin; sẵn sàng đi công tác; từ 1 năm kinh nghiệm vị trí tương đương, ưu tiên hệ thống thời trang, bán lẻ; năng động, chủ động, teamwork.','2026-10-05','2026-11-05','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2322531','https://www.topcv.vn/viec-lam/fresher-data-analyst-f21-up-to-20m/2322531.html','2026-10-11T19:17:47+07:00','Fresher Data Analyst (F21 - Up To 20M)','Công ty Cổ phần Falcon Technology','Hà Nội','1 năm','Thoả thuận (tiêu đề ghi Up To 20M)','phân tích dữ liệu từ data warehouse (hành vi người chơi, xu hướng thị trường, yếu tố ảnh hưởng doanh thu); phát triển/duy trì báo cáo định kỳ, dashboard KPI game; phối hợp team server đảm bảo thu thập dữ liệu chính xác; mô hình hóa, dự đoán, tối ưu kết quả kinh doanh bằng thống kê; phân tích dữ liệu phức tạp thành khuyến nghị cụ thể; thiết kế giải pháp tối ưu hướng tự động hóa và mở rộng; phối hợp MKT, Kế toán cung cấp dữ liệu phát triển sản phẩm','đại học Kinh tế/CNTT; giỏi toán, tư duy tốt, giải quyết vấn đề; SQL, hệ quản trị CSDL lớn; Power BI, Excel; Python/R (lợi thế); làm việc độc lập, môi trường nhanh; teamwork; tiếng Anh đọc hiểu','2026-10-06','2026-11-05','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: tiêu đề fresher; kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2324652','https://www.topcv.vn/viec-lam/chuyen-vien-du-lieu-data-analyst-sql-python/2324652.html','2026-10-11T19:17:47+07:00','Chuyên Viên Dữ Liệu (Data Analyst – SQL/Python)','HỘ KINH DOANH HALA THẾ GIỚI GIA DỤNG','Hồ Chí Minh: 1132/21 Tỉnh Lộ 10, Phường Tân Tạo (Phường Tân Tạo thuộc quận Bình Tân cũ)','2 năm','15 - 18 triệu','Công ty kinh doanh đồ gia dụng nhiều thương hiệu riêng trên Shopee, TikTok Shop (~40 nhân sự), dữ liệu đơn hàng/giao dịch hàng triệu dòng; cần người kỹ thuật vững xây dựng hệ thống dữ liệu từ đầu; báo cáo trực tiếp cho chủ doanh nghiệp; (1) đối soát dữ liệu sàn với kế toán: xây quy trình tự động đối chiếu doanh thu, phí, thanh toán từ các sàn với dữ liệu kế toán; (2) hệ thống đánh giá hiệu quả kho: kết nối dữ liệu qua API, tự động tính chỉ số năng suất, chất lượng theo từng nhân viên; (3) hệ thống đánh giá hiệu quả Marketing: kết nối dữ liệu nội dung và TikTok Ads, tự động tính hiệu quả theo từng video và nhân sự; xây dashboard KPI cho Marketing và Ban Giám đốc; viết tài liệu mô tả cho mọi công thức, script, luồng dữ liệu.','Bắt buộc: thành thạo SQL (truy vấn, ghép bảng, tổng hợp dữ liệu lớn); viết Python lấy dữ liệu qua API (đọc JSON), làm sạch dữ liệu, chạy tự động định kỳ; từng làm việc với tập dữ liệu hàng trăm nghìn dòng trở lên; làm sạch và ghép dữ liệu nhiều nguồn; làm dashboard trên Looker Studio, Power BI hoặc tương đương; thành thạo Excel/Google Sheets; cẩn thận, chủ động, giải thích kết quả kỹ thuật bằng ngôn ngữ dễ hiểu. Lợi thế: BigQuery/PostgreSQL/MySQL; dùng AI hỗ trợ viết code và phân tích; kinh nghiệm dữ liệu sàn TMĐT, kế toán, quảng cáo, kho vận.','2026-10-08','2026-11-07','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2326590','https://www.topcv.vn/viec-lam/nhan-vien-phan-tich-du-lieu-kinh-doanh/2326590.html','2026-10-11T19:17:47+07:00','Nhân Viên Phân Tích Dữ Liệu Kinh Doanh','CÔNG TY CỔ PHẦN DƯỢC AIKYA','Hồ Chí Minh','1 năm','Thoả thuận','phân tích dữ liệu và hiệu quả kinh doanh: doanh số, KPI, kế hoạch; phân tích biến động doanh số theo thời gian, sản phẩm, khu vực, khách hàng; theo dõi chỉ số kinh doanh, nhận diện xu hướng bất thường, cảnh báo rủi ro; đề xuất giải pháp cải thiện hiệu quả bán hàng dựa trên dữ liệu; xây dựng, cập nhật báo cáo và dashboard cho quản lý; hỗ trợ lập kế hoạch: theo dõi Sales Commitment, Sales Forecast; phân tích chênh lệch thực tế vs mục tiêu; phân tích khu vực/sản phẩm/khách hàng tiềm năng tăng trưởng; báo cáo quản trị định kỳ; kiểm tra tính chính xác, đầy đủ, nhất quán của dữ liệu bán hàng; rà soát, cải tiến quy trình tổng hợp và báo cáo dữ liệu','tốt nghiệp đại học QTKD, Kinh tế, Tài chính, HTTTQL, Phân tích Dữ liệu; 1-2 năm Phân tích dữ liệu, Sales Operations, Sales Admin, Business Analysis (ưu tiên); kinh nghiệm bán lẻ, thực phẩm chức năng (ưu tiên); Excel thành thạo; hiểu chỉ số kinh doanh và hoạt động Sales; tư duy phân tích, nhạy bén số liệu; Power BI hoặc công cụ trực quan hóa (lợi thế); đọc hiểu tài liệu tiếng Anh','2026-10-09','2026-11-08','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2327052','https://www.topcv.vn/brand/educa/tuyen-dung/chuyen-vien-phan-tich-du-lieu-kinh-doanh-bi-analyst-business-intelligence-j2327052.html','2026-10-11T19:17:47+07:00','Chuyên Viên Phân Tích Dữ Liệu Kinh Doanh (BI Analyst / Business Intelligence)','CÔNG TY CỔ PHẦN GIÁO DỤC EDUCA CORPORATION (Edupia)','Hà Nội','2 năm','20 - 40 triệu','xây dựng hệ thống báo cáo quản trị, phân tích chỉ báo hoạt động; đồng hành Ban Lãnh đạo hoạch định chiến lược (CEO Office); thiết lập, vận hành, cải tiến hệ thống BI; theo dõi chỉ báo kinh doanh hàng ngày, phát hiện rủi ro, cảnh báo sớm; đánh giá hiệu quả kinh doanh hàng tháng; thu thập/xử lý dữ liệu cho kỳ chiến lược, kế hoạch dài hạn 3–5 năm; chuẩn bị dữ liệu họp CEO, rà soát tờ trình, theo dõi dự án trọng điểm','đại học phân tích dữ liệu, HTTTQL, tài chính, QTKD; từ 2–4 năm BI/Business Analyst/Data Analyst tại doanh nghiệp phức tạp; Power BI, Tableau, SQL, Excel nâng cao thành thạo; tư duy phân tích số liệu sắc bén, nhạy bén chỉ số kinh doanh; tổng hợp, trình bày, giao tiếp với lãnh đạo; chủ động, tỉ mỉ, trách nhiệm, bảo mật, chịu áp lực','2026-10-10','2026-11-09','data_analyst','data_analyst','data_analyst','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','1658215','https://www.topcv.vn/viec-lam/truong-nhom-phan-tich-du-lieu-data-analyst/1658215.html','2026-10-11T19:17:47+07:00','Trưởng Nhóm Phân Tích Dữ Liệu (Data Analyst)','VNDIRECT','Hà Nội (Phường Thanh Xuân)','3 năm','Thoả thuận','Xây dựng nền tảng dữ liệu (khảo sát yêu cầu, data dictionary, thiết kế tầng dữ liệu, data model/backtest); xây dựng báo cáo/insights, trực quan hóa; đảm bảo chất lượng, chuẩn hóa hạ tầng dữ liệu; quản lý dự án; đào tạo đội ngũ; cải tiến quy trình, tự động hóa luồng xử lý dữ liệu; nghiên cứu best practice, công cụ mới.','Đại học (quản trị kinh tế/CNTT/tài chính ngân hàng; CFA/CAAC là lợi thế); 3–5 năm kinh nghiệm phân tích nghiệp vụ, ưu tiên tài chính/chứng khoán/bảo hiểm; phân tích, phản biện, giao tiếp, thuyết trình; tool visualize, data governance; quản trị dự án; AI/big data; tư duy hệ thống, khách hàng.','','2026-11-04','data_analyst','data_analyst','data_analyst','chức danh quản lý','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2157606','https://www.topcv.vn/viec-lam/data-analyst-lead/2157606.html','2026-10-11T19:17:47+07:00','Data Analyst (Lead)','CÔNG TY CỔ PHẦN ĐẦU TƯ CÔNG NGHỆ & ĐỔI MỚI VIỆT','Hà Nội (Tòa nhà Tasco, Lô HH2-2, Phạm Hùng, Phường Từ Liêm)','3 năm','25 - 35 triệu','Phân tích dữ liệu & báo cáo (thẩm định bảo hiểm, bồi thường, hành vi khách hàng, tài chính); phân tích kinh doanh & chiến lược (xu hướng, bất thường, đánh giá rủi ro); tối ưu hiệu quả kinh doanh bảo hiểm (cross/up-selling, phân khúc khách hàng, tối ưu conversion); mô hình dự đoán & đánh giá rủi ro (phối hợp actuarial, phát hiện gian lận); phối hợp & giao tiếp.','Đại học CNTT/HTTT/quản lý dự án; trên 3 năm, ưu tiên bảo hiểm/tài chính/ngân hàng; thành thạo SQL; phân tích, giải quyết vấn đề; làm việc độc lập/nhóm, áp lực cao; giao tiếp tốt; chủ động, linh hoạt.','2026-09-27','2026-10-31','data_analyst','data_analyst','data_analyst','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2218056','https://www.topcv.vn/brand/sapovn/tuyen-dung/data-analyst-ha-noi-thu-nhap-canh-tranh-tu-4-nam-kinh-nghiem-j2218056.html','2026-10-11T19:17:47+07:00','Data Analyst [Hà Nội] - Thu Nhập Cạnh Tranh, Từ 4 Năm Kinh Nghiệm','Công ty cổ phần Công nghệ Sapo','Hà Nội: Đội Cấn, Phường Ba Đình (Phường Ba Đình thuộc quận Ba Đình cũ)','4 năm','Thoả thuận','(1) Thu thập & xử lý dữ liệu: phối hợp phòng ban thu thập, khai thác, xử lý dữ liệu; làm sạch, chuẩn hóa, đảm bảo chính xác/nhất quán. (2) Xây dựng báo cáo & dashboard: thiết kế, phát triển, chuẩn hóa hệ thống báo cáo/dashboard; tự động hóa báo cáo. (3) Phân tích & đề xuất: phân tích xu hướng, hành vi khách hàng, yếu tố tác động hiệu quả kinh doanh; trực quan hóa, trình bày insight; đề xuất tối ưu vận hành. (4) Tham gia dự án AI & Data: phối hợp đội AI chuẩn bị dữ liệu, xây dựng/triển khai mô hình ML. (5) Cải tiến công cụ & quy trình: đánh giá/tối ưu quy trình phân tích; nghiên cứu công nghệ/công cụ mới.','(1) Kiến thức & kinh nghiệm: tốt nghiệp ĐH (Khoa học dữ liệu, Toán-Thống kê, CNTT, HTTT...); từ 4 năm kinh nghiệm Data Analyst hoặc tương đương. (2) Kỹ năng chuyên môn: thành thạo SQL (SQL Server, MySQL, PostgreSQL); thành thạo Power BI; dùng Python trong xử lý/phân tích/trực quan hóa; kinh nghiệm BI/Data Viz (Power BI, Tableau, Metabase...); hiểu thống kê, phân tích dữ liệu, ML cơ bản. (3) Kỹ năng khác: phân tích, tư duy logic, giải quyết vấn đề; giao tiếp, trình bày, truyền đạt insight; chủ động, ham học hỏi, teamwork; đọc hiểu tài liệu tiếng Anh chuyên ngành.','2026-10-04','2026-10-31','data_analyst','data_analyst','data_analyst','','excluded','Yêu cầu kinh nghiệm 4 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2272110','https://www.topcv.vn/viec-lam/data-analyst-leader/2272110.html','2026-10-11T19:17:47+07:00','Data Analyst Leader','CÔNG TY CỔ PHẦN TƯ VẤN CÔNG NGHỆ NGS','Hà Nội (6th Element Nguyễn Văn Huyên, Phường Nghĩa Đô)','4 năm','Thoả thuận','Lập kế hoạch/phân chia công việc cho nhóm; tư vấn phương pháp phân tích dữ liệu, lựa chọn KPI; đề xuất giải pháp kinh doanh/kỹ thuật/xử lý dữ liệu tự động/trực quan hóa báo cáo; xây dựng luồng ETL, mô hình hóa dữ liệu, bố cục báo cáo; tài liệu hướng dẫn và đào tạo người dùng; quản lý hệ thống báo cáo BI; quản trị dữ liệu/chất lượng dữ liệu; phân quyền truy cập.','Đại học hệ thống thông tin/CSDL/IT phần mềm; 4–6 năm Data Analyst/Data Analyst Leader; làm việc độc lập, lãnh đạo nhóm; thành thạo Power BI, ETL & DWH (Azure, SQL, Power Query); mô hình hóa dữ liệu/dữ liệu lớn; tiếng Anh giao tiếp tốt với khách hàng; ưu tiên: R/Python, Power Apps/Automate, MDM, dự án tài chính ngân hàng, chứng chỉ Power BI.','2026-09-20','2026-10-23','data_analyst','data_analyst','data_analyst','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2299813','https://www.topcv.vn/viec-lam/data-analyst-supervisor-medicine/2299813.html','2026-10-11T19:17:47+07:00','Data Analyst Supervisor (Medicine)','Công Ty Cổ Phần Dược Phẩm Pharmacity','Hồ Chí Minh','3 năm','Thoả thuận','thu thập, duy trì, phân tích dữ liệu cho Medicine Trading team; thành viên Medicine Committee; quản lý danh mục thuốc core/non-core; đánh giá định kỳ với dữ liệu thị trường IQVIA; kiểm soát assortment cửa hàng, can thiệp khi phát hiện bất thường; quản trị dữ liệu assortment trên AX, Relex, BI; theo dõi hàng cận date, điều chuyển hàng chậm luân chuyển; báo cáo phân tích tuần/tháng/ad-hoc (doanh số, lợi nhuận gộp, tồn kho, vendor performance); phối hợp BI team làm báo cáo và trực quan hóa; mapping dữ liệu Pharmacity - IQVIA - đối thủ - bệnh viện; chỉ đạo, phân công, đánh giá nhân viên','cử nhân QTKD, Tài chính, Kế toán hoặc liên quan; 3 năm Data Analysis/Business Analysis; kinh nghiệm dược phẩm, bán lẻ, y tế (lợi thế); tư duy phân tích; ưu tiên tốc độ và sắp xếp công việc; kỹ năng trình bày và giao tiếp; kinh nghiệm Retail, Pharmaceutical, FMCG (ưu tiên)','2026-09-13','2026-10-12','data_analyst','data_analyst','data_analyst','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2300211','https://www.topcv.vn/viec-lam/data-analysis-strategy-team-leader-collection/2300211.html','2026-10-11T19:17:47+07:00','Data Analysis & Strategy Team Leader (Collection)','CÔNG TY TÀI CHÍNH TRÁCH NHIỆM HỮU HẠN MỘT THÀNH VIÊN LOTTE VIỆT NAM','Hồ Chí Minh','3 năm','Thoả thuận','phân tích chuyên sâu hiệu suất, năng suất, đặc điểm khách hàng, sản phẩm, khu vực trong thu hồi nợ; nhận diện xu hướng, vấn đề, đề xuất giải pháp cải thiện; đề xuất, triển khai, đánh giá chương trình thử nghiệm chiến lược/chiến thuật; cung cấp phân tích, số liệu, khuyến nghị cho cấp quản lý; khai thác, quản lý, hướng dẫn sử dụng dữ liệu và hệ thống báo cáo (DWH); phối hợp CNTT cải tiến hệ thống; phối hợp khối vận hành LPS; quản lý, phân công, giám sát, đào tạo nhân sự trong nhóm','tốt nghiệp đại học Tài chính – Ngân hàng, Kinh tế, Toán – Thống kê, QTKD; tối thiểu 3 năm phân tích dữ liệu cho thu hồi nợ tại tổ chức tài chính/ngân hàng; tối thiểu 1 năm vị trí tương đương; hiểu sản phẩm/dịch vụ/khách hàng tài chính – ngân hàng, cho vay tiêu dùng; Excel nâng cao, SQL/Oracle, VBA, PowerPoint; kỹ năng trình bày, làm việc với cấp quản lý; hiểu nghiệp vụ thu hồi nợ (lợi thế); tư duy logic, chịu áp lực, trách nhiệm cao','','2026-10-14','data_analyst','data_analyst','data_analyst','chức danh quản lý','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2300370','https://www.topcv.vn/viec-lam/lead-phan-tich-du-lieu-data-analyst/2300370.html','2026-10-11T19:17:47+07:00','Lead Phân Tích Dữ Liệu (Data Analyst)','CÔNG TY CỔ PHẦN CÔNG NGHỆ SICIX','Hà Nội','3 năm','20 - 35 triệu','xây dựng báo cáo và dashboard trực quan cho lãnh đạo và phòng ban; thiết kế, quản lý, tối ưu hệ thống báo cáo KPI; phân tích hành vi khách hàng, xu hướng thị trường, hiệu quả hoạt động; đưa ra insight, cảnh báo, khuyến nghị hành động; phối hợp phòng ban nghiệp vụ chuyển yêu cầu kinh doanh thành chỉ số đo lường; triển khai, tùy chỉnh, vận hành dashboard (Apache Superset/Power BI/Tableau); đảm bảo báo cáo ổn định, cập nhật realtime/near realtime; tư vấn giải pháp, hỗ trợ ra quyết định dựa trên dữ liệu','tốt nghiệp đại học CNTT, Toán – Thống kê, Kinh tế; tối thiểu 3 năm Data Analyst/BI; SQL, DAX, MDX; Power BI, Tableau, Google Data Studio, Qlik, Apache Superset; hiểu cấu trúc dữ liệu, mô hình dữ liệu, ETL cơ bản; trực quan hóa dữ liệu (line, bar, heatmap, funnel); dashboard tương tác, drill-down, lọc đa chiều; tối ưu hiệu năng báo cáo với dữ liệu lớn (ưu tiên); tư duy phản biện, data storytelling, giao tiếp, teamwork','','2026-10-14','data_analyst','data_analyst','data_analyst','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2300709','https://www.topcv.vn/brand/galaxydebt/tuyen-dung/data-analyst-lead-nganh-tai-chinh-j2300709.html','2026-10-11T19:17:47+07:00','Data Analyst Lead (Ngành Tài Chính)','GALAXY DEBT TRADING COMPANY LIMITED','Hồ Chí Minh','2 năm','Thoả thuận','quản lý hệ thống cơ sở dữ liệu DWH phục vụ phân tích, báo cáo; phân tích nhân sự, nghiệp vụ, kết quả thu hồi nợ, productivity theo tháng/quý so với benchmark; phát triển dự án dashboard trực quan; báo cáo, phân tích, đánh giá kết quả làm việc nhân viên/nhóm/vùng hàng tháng; xây dựng auto report/dashboard/funnel theo chiến lược kinh doanh; xây dựng mô hình dự thu, hiệu quả kinh doanh; cải thiện hệ thống báo cáo, đo lường, kiểm soát chất lượng; tham vấn xây dựng chính sách thưởng, contest; đảm bảo bảo mật dữ liệu theo quy định; quản lý, hướng dẫn, đánh giá nhân viên trong nhóm; điều phối tasklist, đáp ứng yêu cầu ad-hoc từ BGĐ','tốt nghiệp đại học chuyên ngành liên quan; SQL (PostgreSQL, Oracle); Python (tự động hóa, mô hình dự báo, xử lý dữ liệu); MS Office (báo cáo, trực quan hóa, slide); 2 năm kinh nghiệm vị trí tương đương; kinh nghiệm tài chính - collection','','2026-10-14','data_analyst','data_analyst','data_analyst','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2307475','https://www.topcv.vn/viec-lam/data-analyst-lead-social-intelligence/2307475.html','2026-10-11T19:17:47+07:00','Data Analyst Lead – Social Intelligence','CÔNG TY CỔ PHẦN YOUNET','Hồ Chí Minh','4 năm','Thoả thuận','Lãnh đạo nhóm Data Analyst tại YouNet Media (Social Media & E-commerce Intelligence): quản lý nhóm và phân bổ nguồn lực (15%); đảm bảo chất lượng dữ liệu trước khi giao khách hàng (10%); quản lý dự án Social Listening quy mô lớn/phức tạp, chuẩn hóa quy trình QA/QC, ứng dụng AI (prompt engineering, phân loại/tự động hóa) tối ưu xử lý dữ liệu (40%); tư vấn dữ liệu cho khách hàng trọng điểm (25%); kiểm soát chi phí vận hành dự án (10%).','Cử nhân Business, Marketing hoặc Data Analytics liên quan; hiểu biết sâu nền tảng social media; kỹ năng phân tích dữ liệu và làm báo cáo; giao tiếp, thuyết trình tốt; tỉ mỉ; làm việc độc lập và nhóm; tối thiểu 4 năm ở vị trí tương đương là lợi thế; tiếng Anh, TOEIC 800 là lợi thế.','','2026-10-21','data_analyst','data_analyst','data_analyst','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2308458','https://www.topcv.vn/brand/vpbank/tuyen-dung/senior-team-leader-business-intelligence-eda-division-hn-ta174-j2308458.html','2026-10-11T19:17:47+07:00','Senior/ Team Leader Business Intelligence (EDA Division) - HN - TA174','Ngân Hàng TMCP Việt Nam Thịnh Vượng (VPBank)','Hà Nội (89 Láng Hạ, Phường Đống Đa)','Trên 5 năm','Thoả thuận','Phụ trách tính toán và đảm bảo tính chính xác kịp thời các chương trình trả thưởng khối khách hàng cá nhân (lương kinh doanh, thúc đẩy bán, marketing, môi giới, hoa hồng); cung cấp số liệu định kỳ; cải tiến quy trình tính toán/thanh toán rút ngắn TAT; tư vấn chính sách/cơ chế tính toán; tính toán lộ trình thăng tiến và dữ liệu PMS.','Đại học kinh tế/ngân hàng/kế toán/tài chính/CNTT; kiến thức sản phẩm/dịch vụ ngân hàng bán lẻ; kỹ năng sáng tạo giải quyết vấn đề; SQL/Oracle; Python/R; BI tool (Superset/PBI/Quicksight); tối thiểu 5 năm quản lý hệ thống báo cáo/phân tích chuyên sâu ngân hàng tài chính; kinh nghiệm tính toán KPI/payment scheme; làm việc độc lập/nhóm, phân tích, quản lý thời gian, tư duy logic.','','2026-10-23','data_analyst','data_analyst','data_analyst','chức danh quản lý','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2309444','https://www.topcv.vn/viec-lam/data-analysis-specialist/2309444.html','2026-10-11T19:17:47+07:00','Data Analysis Specialist','CHI NHÁNH LONG BÌNH CÔNG TY TNHH OLAM VIỆT NAM','Đồng Nai (Phường Biên Hòa / Phường Long Bình)','5 năm','Thoả thuận','Phân tích dữ liệu sản xuất/vận hành để cải thiện hiệu suất và giảm chi phí; tối ưu quy trình end-to-end (bottleneck, loại bỏ lãng phí); theo dõi/đánh giá dữ liệu sản xuất, báo cáo cho lãnh đạo; theo dõi xu hướng ngành, đưa khuyến nghị data-driven.','Nền tảng Tài chính & Kế toán; ít nhất 5 năm kinh nghiệm; đi làm ASAP; tiếng Anh giao tiếp tốt (nói/viết).','','2026-10-23','data_analyst','data_analyst','data_analyst','','excluded','Yêu cầu kinh nghiệm 5 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2311515','https://www.topcv.vn/viec-lam/giam-sat-bi-business-intelligence/2311515.html','2026-10-11T19:17:47+07:00','Giám Sát BI (Business Intelligence)','Công ty CP Casper Việt Nam','Hà Nội','3 năm','Thoả thuận','Xây dựng và vận hành hệ thống BI phục vụ ra quyết định cho Kinh doanh, Tài chính, CSKH theo mô hình data-driven; phát triển/duy trì Dashboard, KPI Report trên Power BI; thiết kế Data Model, DAX, Power Query, visual chuẩn UI/UX; tích hợp dữ liệu đa nguồn (SQL, SAP, SharePoint, Excel, API), thiết lập ETL/ELT tự động; data governance; thu thập yêu cầu, xác định KPI; đào tạo người dùng; phân tích xu hướng, đề xuất cải tiến.','Tốt nghiệp CNTT, Hệ thống thông tin, Toán – Tin, Kinh tế – Thống kê; tối thiểu 3 năm kinh nghiệm BI/Data Analytics/Power Platform; thành thạo Power BI (Desktop & Service), DAX, Power Query, SQL; kinh nghiệm xử lý dữ liệu đa nguồn; ưu tiên Power Automate, Python, API integration; tư duy hệ thống, giao tiếp tốt.','','2026-10-24','data_analyst','data_analyst','data_analyst','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2314538','https://www.topcv.vn/viec-lam/bi-developer/2314538.html','2026-10-11T19:17:47+07:00','BI Developer','CÔNG TY CỔ PHẦN TƯ VẤN CÔNG NGHỆ NGS','Hà Nội','5 năm','30 - 40 triệu','thiết kế, phát triển, duy trì dashboard Power BI, báo cáo Jasper, mô hình phân tích; trực quan hóa tương tác, KPI, báo cáo data storytelling; viết SQL, stored procedure, view, transformation; xây dựng mô hình dữ liệu (star/snowflake); thu thập yêu cầu báo cáo từ nghiệp vụ; khám phá dữ liệu, phân tích xu hướng/thống kê; định nghĩa và duy trì BI governance (metadata, version control, phân quyền, chuẩn chất lượng dữ liệu); quản trị Power BI Service và Jasper Server (datasets, gateway, lịch refresh); trình bày insight cho stakeholder; khắc phục sự cố, tối ưu SQL/model/report','5 năm BI development/analytics/reporting; Power BI và/hoặc Jasper Reports; SQL mạnh (tối ưu truy vấn, data modeling, transformation); Power BI Desktop, DAX, Power Query (M); ETL, BI data flow, pipeline; phân tích thống kê/định lượng; trực quan hóa, thiết kế dashboard, KPI framework, data storytelling; đại học CNTT/HTTT/Data Analytics (ưu tiên)','','2026-10-28','data_analyst','data_analyst','data_analyst','','excluded','Yêu cầu kinh nghiệm 5 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2318491','https://www.topcv.vn/viec-lam/business-intelligence-lead/2318491.html','2026-10-11T19:17:47+07:00','Business Intelligence Lead','CÔNG TY CỔ PHẦN CÔNG NGHỆ ALPHAWAY','Hà Nội (72 Trần Hưng Đạo, Phường Cửa Nam)','3 năm','Thoả thuận','Thiết kế/duy trì BI solutions, dashboard, báo cáo; xây dựng chiến lược/roadmap data products; chuyển nhu cầu dữ liệu thành tính năng sản phẩm; quản lý delivery/performance; thúc đẩy đổi mới và data literacy.','3+ năm BI/analytics/data product; Power BI/Tableau, SQL, data modeling; Agile, cloud (Azure/AWS); giao tiếp, problem-solving, stakeholder management; tư duy chiến lược.','','2026-11-01','data_analyst','data_analyst','data_analyst','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2319131','https://www.topcv.vn/viec-lam/truong-nhom-phan-tich-du-lieu-data-analyst/2319131.html','2026-10-11T19:17:47+07:00','Trưởng Nhóm Phân Tích Dữ Liệu (Data Analyst)','Alphaway Technology','Hà Nội (72 Trần Hưng Đạo, Phường Cửa Nam)','2 năm','Tới 38 triệu','Xây dựng hệ thống chỉ tiêu, KPI, metrics; khai thác/phân tích dữ liệu từ hệ thống nghiệp vụ; mapping dữ liệu, xây dựng/vận hành mô hình dữ liệu, dashboard; kiểm thử/đối soát Data Mart với dữ liệu nguồn.','Đại học/thạc sĩ tài chính ngân hàng/thống kê/khoa học dữ liệu; tối thiểu 2 năm BI/Data Analytics/Reporting; ưu tiên ngân hàng/tài chính; thành thạo Power BI, SQL; Python/R; data modeling, ETL, OLAP; ưu tiên kinh nghiệm ML (XGBoost/LightGBM/CatBoost/transformer); data governance, metadata.','','2026-11-01','data_analyst','data_analyst','data_analyst','chức danh quản lý','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2319606','https://www.topcv.vn/brand/abbank/tuyen-dung/cvcc-chuyen-gia-phan-tich-du-lieu-khoi-ngan-hang-so-va-du-lieu-j2319606.html','2026-10-11T19:17:47+07:00','CVCC/Chuyên Gia Phân Tích Dữ Liệu – Khối Ngân Hàng Số Và Dữ Liệu','Ngân Hàng TMCP An Bình (ABBANK)','Hà Nội','Trên 5 năm','Thoả thuận','tham gia thiết kế/phát triển sản phẩm, dịch vụ ngân hàng số (KHCN, SME, KHDN); dùng phân tích dữ liệu để am hiểu khách hàng, cá nhân hóa, tối ưu trải nghiệm khách hàng; tiếp nhận yêu cầu phân tích, đánh giá tính khả thi, thống nhất mục tiêu/phạm vi dự án; xây dựng báo cáo/dashboard định kỳ/ad-hoc; kiểm tra/cập nhật/bổ sung dữ liệu phục vụ báo cáo digital banking; trực quan hóa dữ liệu, đưa insight khách hàng hỗ trợ ra quyết định','đại học CNTT/ĐTVT/Kinh tế/Ngân hàng; 10+ năm phát triển phần mềm trong Tài chính/Ngân hàng/Viễn thông/BĐS; thống kê và mô hình phân tích; trực quan hóa dữ liệu; SQL, Python (Pandas, Numpy, Matplotlib), Excel, PowerBI/Tableau; xác suất thống kê sâu; Machine Learning; Tài chính-ngân hàng/Fintech; Data Modeling (ưu tiên); thuyết trình, giải quyết vấn đề, quản lý thời gian; tiếng Anh giao tiếp và đọc hiểu','2026-10-04','2026-11-02','data_analyst','data_analyst','data_analyst','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2322780','https://www.topcv.vn/viec-lam/senior-data-analyst/2322780.html','2026-10-11T19:17:47+07:00','Senior Data Analyst','CÔNG TY TNHH BEYONDSOFT TECHNOLOGY (VIETNAM)','Hồ Chí Minh','5 năm','Thoả thuận','phân tích dữ liệu, tạo insight kinh doanh; phối hợp stakeholders, biến câu hỏi kinh doanh thành insight/khuyến nghị; phân tích nguyên nhân gốc, xu hướng, đo lường hiệu suất; định nghĩa KPI/scorecard; viết SQL phức tạp trích xuất/chuyển đổi/kiểm tra dữ liệu lớn; kiểm soát chất lượng dữ liệu; thiết kế/duy trì Power BI semantic model (star schema, metrics/DAX dùng chung), tối ưu hiệu năng; dùng AI (Copilot, ChatGPT, Claude) tăng hiệu quả insight','5+ năm SQL (complex joins, CTE, window functions, tối ưu truy vấn, dữ liệu lớn cấp doanh nghiệp); 3+ năm Power BI (semantic models, data modeling, star schema, DAX, calculation groups, data governance); phân tích nghiệp vụ, giao tiếp, quản lý stakeholder; tiếng Anh giao tiếp thành thạo; AI tools, GenAI/AI agents/prompt engineering (ưu tiên); Microsoft Fabric/Azure, Python (ưu tiên); đại học trở lên','','2026-11-30','data_analyst','data_analyst','data_analyst','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2322986','https://www.topcv.vn/brand/educa/tuyen-dung/chuyen-vien-phan-tich-du-lieu-growth-data-analyst-analytics-specialist-luong-upto-35m-thuong-tai-ha-noi-j2322986.html','2026-10-11T19:17:47+07:00','Chuyên Viên Phân Tích Dữ Liệu /Growth Data Analyst /Analytics Specialist( Lương Upto 35M+ Thưởng) Tại Hà Nội','CÔNG TY CỔ PHẦN GIÁO DỤC EDUCA CORPORATION (tiêu đề trang ghi EDUPIA)','Hà Nội: Tòa Comatce, 61 Ngụy Như Kon Tum, Phường Thanh Xuân (Phường Thanh Xuân thuộc quận Thanh Xuân cũ)','3 năm','Tới 35 triệu','(1) Phân tích và Mô hình hóa (70%): thực hiện dự án end-to-end (thu thập, làm sạch dữ liệu...); phối hợp DA, DE khai thác dữ liệu hành vi khách hàng từ CRM, LMS, Telesale, Marketing; xây dựng mô hình (phân loại, hồi quy...): scoring khách hàng tiềm năng cho cross-sale/up-sale, phân khúc khách hàng cho marketing, tối ưu hóa mô hình; thiết kế chiến lược tăng trưởng và giữ chân khách hàng dài hạn. (2) Cố vấn Kinh doanh (30%): làm việc với Product Owners, Marketing, Sales; truyền tải insight cho đối tượng không chuyên; đề xuất chiến lược dựa trên dữ liệu thúc đẩy tăng trưởng doanh thu/tối ưu.','Cử nhân trở lên; ít nhất 3 năm kinh nghiệm xử lý, khai thác, phân tích dữ liệu; trải nghiệm thực tế dự án chuẩn bị dữ liệu cho mục tiêu kinh doanh; từng làm dữ liệu cho công ty Product, e-commerce, fintech, SaaS hoặc scale-up; thành thạo công cụ truy vấn, tổng hợp dữ liệu; kỹ năng phân tích, đánh giá chất lượng, trực quan hóa; làm việc nhóm với AI/ML và kỹ thuật dữ liệu; tư duy kinh doanh; tố chất leader & ownership.','','2026-11-05','data_analyst','data_analyst','data_analyst','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2323081','https://www.topcv.vn/brand/misa/tuyen-dung/data-business-analyst-credit-rating-j2323081.html','2026-10-11T19:17:47+07:00','Data Business Analyst (Credit Rating)','Công ty Cổ phần MISA','Hà Nội','3 năm','Thoả thuận','thu thập, xử lý, phân tích số liệu nội bộ và bên ngoài; đảm bảo dữ liệu đầy đủ, chính xác, sạch, sẵn sàng; viết tài liệu phân tích thiết kế cho đội thi công (nguồn dữ liệu, cách lấy/xử lý, giao diện); kiểm tra chất lượng dữ liệu liên tục; viết hướng dẫn sử dụng công cụ, đo lường việc sử dụng, tiếp nhận cải tiến; phối hợp cải tiến quy trình thu thập, xử lý và sử dụng dữ liệu','kiến thức phân tích/xử lý dữ liệu, quy trình phát triển phần mềm, CSDL (SQL, NoSQL); xác suất – thống kê (ưu tiên); Power BI, Tableau, Excel, SQL thành thạo; viết tài liệu kỹ thuật, giao tiếp, thuyết trình; ít nhất 3 năm phân tích/làm sạch dữ liệu, tạo báo cáo; ANOVA, A/B testing, Pre-post analysis (ưu tiên)','','2026-11-05','data_analyst','data_analyst','data_analyst','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2323527','https://www.topcv.vn/brand/vpbank/tuyen-dung/audit-data-analytics-specialist-id11908-j2323527.html','2026-10-11T19:17:47+07:00','Audit Data Analytics Specialist - ID11908','Ngân Hàng TMCP Việt Nam Thịnh Vượng (VPBank)','Hà Nội','3 năm','Thoả thuận','phân tích dữ liệu kiểm toán, xử lý big data; lập trình truy vấn SQL/Python/Alteryx phát hiện bất thường, gian lận; phân tích mô tả/chẩn đoán/dự báo; thẩm định độ tin cậy và chất lượng dữ liệu (IPE, ITGCs, data lineage, ETL); tuân thủ bảo vệ dữ liệu (Nghị định 13/2023/NĐ-CP, Luật An ninh mạng; masking/ẩn danh/mã hóa, giám sát audit trail); tự động hóa, xây dựng thư viện kịch bản dùng chung; dashboard Power BI/Tableau; nghiên cứu ứng dụng AI/GenAI/NLP trong kiểm toán','đại học KHDL/CNTT/MIS/Thống kê/Kế toán-Kiểm toán/Tài chính-Ngân hàng; 3–5 năm Data Analytics/Risk Analytics/Kiểm toán nội bộ/CNTT tại ngân hàng/tài chính/Big4; SQL nâng cao, Python/Alteryx/R, Power BI/Tableau, Excel nâng cao; IT audit, IPE, ITGCs, bảo vệ dữ liệu cá nhân; tư duy hoài nghi nghề nghiệp, diễn giải dữ liệu cho lãnh đạo; tiếng Anh chuyên ngành CNTT/dữ liệu; chứng chỉ Data Analyst Associate, Alteryx Designer, ACDDA, CISA, CDPSE, CIA (ưu tiên)','2026-10-07','2026-11-06','data_analyst','data_analyst','data_analyst','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2326321','https://www.topcv.vn/viec-lam/data-analyst-lead/2326321.html','2026-10-11T19:17:47+07:00','Data Analyst (Lead)','CÔNG TY CỔ PHẦN CÔNG NGHỆ ALPHAWAY','Hà Nội','3 năm','20 - 27 triệu','thu thập, xử lý, làm sạch, kiểm tra chất lượng dữ liệu đa nguồn (SQL Server, BigQuery, Snowflake, PostgreSQL, MySQL); xây dựng và duy trì báo cáo, dashboard tương tác (ưu tiên Apache Superset; Power BI, Tableau, Looker); phối hợp Data Engineer đảm bảo pipeline và warehouse ổn định, chính xác, kịp thời; xây dựng và cải tiến Data Dictionary, tài liệu dashboard, best practices BI','đại học CNTT, Toán – Tin, Kinh tế; từ 3 năm Data Analyst; SQL (query phức tạp, CTE, window functions, tối ưu performance); dashboard chuyên sâu: Apache Superset (ưu tiên), Power BI (DAX), Tableau, Looker/Looker Studio; dimensional modeling (DIM/FACT/SCD), Star Schema, grain, surrogate key, conformed dimension','2026-10-09','2026-11-08','data_analyst','data_analyst','data_analyst','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2326531','https://www.topcv.vn/viec-lam/data-analyst-lead/2326531.html','2026-10-11T19:17:47+07:00','Data Analyst (Lead)','Alphaway Technology (footer trang: CÔNG TY CỔ PHẦN CÔNG NGHỆ ALPHAWAY)','Hà Nội: Phường Hai Bà Trưng (Phường Hai Bà Trưng thuộc quận Hai Bà Trưng cũ) - Phạm vi làm việc trên toàn khu vực trên.','2 năm','22 - 32 triệu','Thu thập, xử lý, làm sạch và kiểm tra chất lượng dữ liệu từ nhiều nguồn (SQL Server, BigQuery, Snowflake, PostgreSQL, MySQL...); xây dựng và duy trì các báo cáo, dashboard tương tác trên một hoặc nhiều công cụ BI: Apache Superset (ưu tiên), Power BI, Tableau, Looker (Looker Studio hoặc Looker core); phối hợp với đội Data Engineer để đảm bảo pipeline dữ liệu ổn định và dữ liệu trong warehouse luôn chính xác, kịp thời; đóng góp vào việc xây dựng và cải tiến Data Dictionary, Documentation dashboard và Best Practices về BI.','Tốt nghiệp Đại học các ngành CNTT, Toán – Tin, Kinh tế, hoặc tương đương; từ 2 năm trở lên kinh nghiệm làm Data Analyst; thành thạo SQL (viết query phức tạp, CTE, window functions, tối ưu performance); có kinh nghiệm thực tế xây dashboard chuyên sâu trên ít nhất 1 trong các công cụ: Apache Superset (ưu tiên), Power BI (DAX thành thạo là lợi thế lớn), Tableau, Looker/Looker Studio; hiểu và có kinh nghiệm thực tế về dimensional modeling (DIM/FACT/SCD): hiểu rõ Star Schema và các khái niệm grain, surrogate key, conformed dimension.','','2026-11-09','data_analyst','data_analyst','data_analyst','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2322980','https://www.topcv.vn/viec-lam/middle-data-analyst-tu-2-nam-kinh-nghiem/2322980.html','2026-10-11T19:17:47+07:00','Middle Data Analyst (Từ 2 Năm Kinh Nghiệm)','Công ty CP Khoa học Dữ liệu','Hà Nội','2 năm','15 - 20 triệu','xử lý và kiểm soát chất lượng dữ liệu sản phẩm thương mại điện tử (50%); làm sạch, chuẩn hóa, gán nhãn dữ liệu bằng Python/Excel/AI Model (50K–500K dòng/dự án); xây dựng báo cáo nghiên cứu thị trường định kỳ (30%); phân tích dữ liệu tìm insight và case-study tăng trưởng cho thương hiệu (10%); hỗ trợ khách hàng về dữ liệu/dashboard đã bàn giao (10%)','cử nhân phân tích dữ liệu, thống kê, toán, khoa học máy tính; báo cáo/dashboard tự động bằng Python, SQL, Excel (bắt buộc); từ 2 năm kinh nghiệm phân tích hoặc làm sạch dữ liệu bằng công cụ tự động; kỹ năng trình bày insight, tư duy giải quyết vấn đề, tỉ mỉ; kinh nghiệm báo cáo nghiên cứu thị trường (lợi thế)','','2026-11-06','data_analyst','data_analyst','data_analyst','','review','Cấp Middle/All Level cần kiểm tra');
INSERT INTO "jobs" VALUES('TopCV','1037081','https://www.topcv.vn/viec-lam/chuyen-vien-du-lieu-lon-big-data/1037081.html','2026-10-11T19:40:00+07:00','Chuyên Viên Dữ Liệu Lớn (Big Data)','Ngân hàng TMCP Đông Nam Á - SEABANK','Hà Nội','1 năm','Thoả thuận','Xây dựng kiến trúc; Phát triển công cụ khai thác dữ liệu lớn; Xử lý/chuyển đổi/quản trị dữ liệu lớn; Triển khai ứng dụng/mô hình xử lý dữ liệu (Hadoop, Spark, Kafka); Nền tảng lưu trữ/xử lý/khai thác dữ liệu đồng nhất; Thiết kế bảng biểu/vùng lưu trữ/pipeline dữ liệu/chuẩn nén/phân tầng dữ liệu; Phân tích/xử lý nguồn dữ liệu bán cấu trúc và phi cấu trúc; Kết nối dữ liệu; Đồng bộ/xử lý dữ liệu thời gian thực (near realtime); Data streaming; Hệ thống đám mây; Đánh giá giải pháp kỹ thuật/kiến trúc; Xây dựng tài liệu thiết kế/triển khai/vận hành','Hệ thống lưu trữ/xử lý dữ liệu phân tán; Hadoop; Spark; Elastic Search; Spark ETL with Scala; Python; Streaming; Đồng bộ/chuyển đổi dữ liệu lớn; Oracle; Cloudera; Confluent; SQL DB (Oracle, MySQL, PostgreSQL, MariaDB, Amazon Aurora); No-SQL DB (Elasticsearch, Cassandra, HBase, BigQuery, Pinot); Graph DB (Neo4j, TigerGraph, Neptune); Memory DB (Redis, Hazelcast, Memcached); Temenos Data Lake; Tư duy lập trình; Phân tích hệ thống; BI (OAS, Tableau, Power BI, Google Looker); Agile; Kinh nghiệm tài chính ngân hàng; Tối thiểu 1 năm Big Data Engineer; Tiếng Anh (đọc viết nghe nói); Kỹ năng giao tiếp; Làm việc nhóm','2026-10-05','2026-11-04','data_engineer','data_analyst;de_aiml','data_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','1748578','https://www.topcv.vn/viec-lam/data-engineer-co-xe-dua-don/1748578.html','2026-10-11T19:40:00+07:00','Data Engineer (Có Xe Đưa Đón)','CÔNG TY CỔ PHẦN CÔNG NGHỆ AN NINH MẠNG QUỐC GIA VIỆT NAM','Hưng Yên, Hà Nội','1 năm','Thoả thuận','xây dựng/vận hành data pipeline; ETL; crawling/scraping; Spark; Kafka; NiFi; Airflow; ClickHouse; Elasticsearch; MongoDB; Neo4j; S3; Docker; Kubernetes; công cụ thu thập/xử lý dữ liệu; ứng dụng AI; debug; tối ưu hiệu năng','ĐH CNTT/Khoa học dữ liệu; tiếng Anh đọc hiểu tài liệu; 1 năm kinh nghiệm Data Engineer; data pipeline; ETL/ELT; batch vs streaming; database SQL/NoSQL; data modeling; OLAP; star schema; Python; Java/Scala; SQL; Spark; Kafka; NiFi; Airflow; ClickHouse; Elasticsearch; MongoDB; Neo4j; S3; Docker; Kubernetes; LLM/prompt (ưu tiên); tuổi 20–28','','2026-10-15','data_engineer','de_aiml','data_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2008022','https://www.topcv.vn/brand/fptsoftwareacademy/tuyen-dung/fresher-data-engineer-j2008022.html','2026-10-11T19:40:00+07:00','Fresher Data Engineer','FPT Software','Hà Nội','Không yêu cầu','6 - 8 triệu','tham gia chương trình đào tạo chuyên sâu 3-4 tháng cho 15 Fresher Data Engineer; Database/SQL: khái niệm & sử dụng SQL truy vấn dữ liệu (select, insert, update, delete, joins, trigger, function/procedure); tối ưu câu truy vấn (tuning performance); Python; Data Analysis và Data Science với thư viện Python; AWS for Developers; PowerBI cơ bản; phát triển phần mềm theo quy trình chuyên nghiệp; luyện tập kỹ năng code trong dự án với chuyên gia công nghệ','sinh viên năm cuối/đã tốt nghiệp Đại học CNTT/Khoa học máy tính; tư duy lập trình tốt; thành thạo ít nhất một ngôn ngữ lập trình, ưu tiên Python; kiến thức SQL/NoSQL, cấu trúc dữ liệu và giải thuật; hiểu biết cơ bản về ETL, Data Pipeline, Big Data; kiến thức/nền tảng AI là lợi thế; tiếng Anh đọc hiểu và giao tiếp tốt; tham gia đào tạo/làm việc full-time; tinh thần học hỏi cao, tư duy logic, kỹ năng giải quyết vấn đề; yêu cầu: Đại học trở lên, IELTS 6.0','2026-10-04','2026-11-01','data_engineer','de_aiml','data_engineer','','eligible','Phù hợp: tiêu đề fresher; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2092204','https://www.topcv.vn/viec-lam/data-engineer/2092204.html','2026-10-11T19:40:00+07:00','Data Engineer','CÔNG TY CỔ PHẦN PARALINE SOFTWARE','Hà Nội','2 năm','Thoả thuận','thiết kế, phát triển và vận hành hệ thống dữ liệu phục vụ phân tích nghiệp vụ và báo cáo; xây dựng và duy trì pipeline ETL/ELT thu thập, xử lý, tích hợp dữ liệu nhiều nguồn; tối ưu hiệu năng xử lý và truy xuất dữ liệu; làm việc với CSDL quan hệ, viết & tối ưu truy vấn SQL, thiết kế cấu trúc dữ liệu; phát triển chương trình xử lý dữ liệu bằng Python/PySpark (làm sạch, chuyển đổi, tổng hợp); xử lý và chuẩn hóa dữ liệu nghiệp vụ (file Excel, dữ liệu bán cấu trúc); tham gia xây dựng hệ thống lưu trữ (Data Lake, Data Warehouse); tuân thủ quy định bảo mật dữ liệu và quy trình phát triển hệ thống; hỗ trợ dữ liệu cho phân tích nâng cao và bài toán ứng dụng dữ liệu','tối thiểu 2 năm kinh nghiệm Data Engineer; tốt nghiệp Đại học CNTT/Khoa học máy tính/Hệ thống thông tin/Công nghệ phần mềm; thành thạo SQL (tuning SQL, B-Tree Index, Composite Index, Partition); kinh nghiệm PostgreSQL, tối ưu hiệu năng truy vấn dữ liệu lớn; thành thạo PySpark (Spark read/write với PostgreSQL, tối ưu partitionBy); kinh nghiệm xây dựng/vận hành pipeline ETL/ELT bằng Apache Airflow hoặc tương đương; Python và Pandas xử lý, làm sạch, phân tích dữ liệu từ Excel; hiểu vòng đời dữ liệu, quy trình ETL/ELT phục vụ BI, AI/ML; tư duy hệ thống, chủ động, teamwork; ưu tiên: kinh nghiệm bảo hiểm, tài chính, ngân hàng','','2026-11-07','data_engineer','de_aiml','data_engineer','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2152218','https://www.topcv.vn/viec-lam/data-platform-engineer-junior/2152218.html','2026-10-11T19:40:00+07:00','Data Platform Engineer (Junior)','Công Ty Truyền Thông Và Công Nghệ ICOMM Việt Nam','Hà Nội','Dưới 1 năm','Thoả thuận (mô tả: up to 30.000.000 VNĐ)','Phát triển service thu thập, parsing, xử lý dữ liệu bằng .NET/Python; xây dựng, bảo trì pipeline ETL/ELT từ API, website, file, log, nguồn dữ liệu mở; làm việc với Kafka, RabbitMQ, message-driven; thiết kế, tối ưu validate, transform, dedup, indexing, nạp dữ liệu vào SQL Server, Elasticsearch, Solr; tích hợp datasource vào query engine; viết test, logging, metrics, tài liệu kỹ thuật; xử lý lỗi pipeline, tối ưu hiệu năng, giảm độ trễ, nâng cao độ ổn định; ứng dụng AI/LLM hỗ trợ sinh parser, mapping schema, unit test, tài liệu, phân tích log','0.5–2 năm kinh nghiệm backend/data engineer/integration engineer; lập trình .NET hoặc Python; API, dữ liệu cấu trúc/bán cấu trúc, database, logging; ETL/ELT, pipeline, retry, idempotency, batching, scheduling; SQL Server, MySQL, PostgreSQL, MongoDB, Elasticsearch, Solr; Docker, Git; tư duy tự động hóa, tinh thần tự học; ưu tiên: Kafka, RabbitMQ, Playwright, Selenium, Appium, deploy Linux/Docker/Kubernetes, data quality, schema validation, lineage, observability, sử dụng AI/LLM','','2026-10-31','data_engineer','de_aiml','data_engineer','','eligible','Phù hợp: tiêu đề junior; kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2245832','https://www.topcv.vn/brand/cmctelecom/tuyen-dung/data-engineer-j2245832.html','2026-10-11T19:40:00+07:00','Data Engineer','Công ty Cổ phần Hạ tầng Viễn thông CMC (CMC Telecom)','Hà Nội','2 năm','Thoả thuận','thiết kế và phát triển pipeline phức tạp (ETL/ELT, streaming) độc lập; đảm bảo hiệu năng và độ tin cậy; vận hành, triển khai các job ETL, tổng hợp dữ liệu từ nhiều nguồn; xây dựng CI/CD cho data pipeline; viết test tự động; thiết kế schema, tối ưu truy vấn, quản lý partition và vòng đời dữ liệu; nghiên cứu và triển khai công nghệ data lakehouse (Iceberg, Delta Lake), tối ưu storage format; độc lập thiết kế và triển khai connector đa nguồn, đa phương thức (batch/streaming, API, DB, SaaS); xây dựng & triển khai data service (phát hiện bất thường, data profiling); xây dựng rule Data Quality tự động; thiết lập monitoring và alerting pipeline; triển khai data masking, encryption cơ bản theo yêu cầu bảo mật; chủ động làm việc với các nhóm (AI/ML, BI, Platform); hỗ trợ onboarding thành viên mới','tốt nghiệp Đại học CNTT/Khoa học máy tính/Toán ứng dụng/Big Data; tối thiểu 2-4 năm kinh nghiệm xây dựng và vận hành data pipeline; thành thạo complex query (window functions, CTE, recursive), ETL job bằng Python/PySpark; kinh nghiệm vận hành, tối ưu query trên nhiều CSDL SQL và NoSQL; kinh nghiệm pipeline Spark/Kafka, thiết lập DAG orchestration phức tạp; kinh nghiệm triển khai dịch vụ data trên cloud (EMR, Dataproc, BigQuery), sử dụng Docker; kinh nghiệm thiết lập CI/CD pipeline cho data project; code review hiệu quả; nghiên cứu và đề xuất công nghệ phù hợp; chứng chỉ Cloud Data (AWS/GCP Data Engineer, Databricks, dbt) là lợi thế; phối hợp đa nhóm, trình bày giải pháp kỹ thuật; làm việc độc lập với nhiệm vụ phức tạp','2026-10-06','2026-11-07','data_engineer','data_analyst;de_aiml','data_engineer','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2272113','https://www.topcv.vn/viec-lam/chuyen-vien-master-data-van-hanh-sap-b1-rpfo-pos/2272113.html','2026-10-11T19:40:00+07:00','Chuyên Viên Master Data & Vận Hành SAP B1/RPFO POS','Công Ty TNHH Thương Mại Laria – Siêu Thị Farmers Market','Hồ Chí Minh','2 năm','20 - 28 triệu','quản trị Master Data trên SAP Business One (Item/Customer/Vendor/Warehouse, barcode); quản lý bảng giá; chương trình khuyến mãi trên RPFO POS; UAT; kiểm tra đồng bộ SAP B1–RPFO POS (Master Data, Price, Sales, Inventory); retry/resync theo SOP; quản lý user và phân quyền (Least Privilege); vận hành automation n8n; duy trì SOP; báo cáo vận hành','CĐ/ĐH CNTT, Hệ thống thông tin, Kinh tế, Kế toán, QTKD; 2–3 năm kinh nghiệm Master Data/ERP/POS Application Support; SAP Business One (lợi thế lớn); POS bán lẻ; Excel (PivotTable, XLOOKUP/VLOOKUP, Power Query); SQL cơ bản; n8n; REST API; JSON; tích hợp hệ thống; kiến thức hàng hóa, barcode, UoM, kho, bảng giá, khuyến mãi, tồn kho; ưu tiên Retail/FMCG/siêu thị/chuỗi cửa hàng','','2026-10-15','data_engineer','de_aiml','data_engineer','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2304617','https://www.topcv.vn/viec-lam/on-job-training-data-engineer/2304617.html','2026-10-11T19:40:00+07:00','On Job Training Data Engineer','FPT Software','Hồ Chí Minh','Không yêu cầu','Thoả thuận','Develop, maintain, optimize data pipelines; Python; PySpark; Microsoft Fabric; cloud platforms; data integration/transformation/analytics; cross-functional collaboration; troubleshooting; continuous learning','Cử nhân CNTT/Khoa học máy tính/Kỹ thuật dữ liệu; Python; SQL; ETL/ELT; analytical thinking; problem-solving; communication; teamwork; English IELTS 6.0+ (TOEIC 750); làm việc toàn thời gian T2–T6','','2026-10-31','data_engineer','de_aiml','data_engineer','','eligible','Phù hợp: tiêu đề on job training; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2306512','https://www.topcv.vn/viec-lam/data-engineer-san-pham-product/2306512.html','2026-10-11T19:40:00+07:00','Data Engineer (Sản Phẩm Product)','Công ty Cổ phần Công nghệ KiotViet','Hà Nội','2 năm','Tới 40 triệu','Design/implement/maintain data pipelines (scalable, reliable); Design/implement/manage data warehouse, data marts; Collect/process/store/analyze customer data; Ensure data quality and consistency; Data processing/transformation pipelines (raw to usable); Collaborate with Data Scientists and Data Analysts; Build high-performance, mission critical Data products (customer-facing and internal services)','Minimum 2 year experience in similar role; Data structures and algorithms; Python; Java; Structured Query Language; Data warehouse concepts and practices; Developing/building Data warehouse, Data marts; Deploying ML model (plus); Eager to learn','2026-09-20','2026-10-18','data_engineer','de_aiml','data_engineer','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2309145','https://www.topcv.vn/viec-lam/data-engineer/2309145.html','2026-10-11T19:40:00+07:00','Data Engineer','Công ty Cổ phần Data Impact','Hà Nội','2 năm','Thoả thuận','Thiết kế/phát triển/vận hành pipeline dữ liệu tự động, có khả năng mở rộng; Thu thập dữ liệu từ nguồn bên ngoài; Ingest/Transform/lưu trữ dữ liệu; Xây dựng và duy trì tầng dữ liệu theo kiến trúc dữ liệu phổ biến; Tăng chất lượng dữ liệu; Tinh chỉnh truy vấn SQL/Spark; Tối ưu workflow; Xử lý sự cố hệ thống phân tán quy mô lớn; Real-time và Batch processing; Phối hợp các bên liên quan; Triển khai luồng xử lý dữ liệu hoàn chỉnh; Chính sách bảo mật; Phân quyền truy cập; Quản trị dữ liệu','Tốt nghiệp Đại học CNTT/Toán tin; Tối thiểu 2 năm kinh nghiệm Data Engineer; Thành thạo Python và SQL; MySQL; PostgreSQL; SQL Server; Oracle; ETL/ELT; Git; FDE (Forward Deployed Engineer); Palantir Platform; Databricks; Big Data; Cloud; Apache Spark; Snowflake; Data Lake/Lakehouse; Phân tích/giải quyết bài toán dữ liệu','2026-09-27','2026-10-30','data_engineer','de_aiml','data_engineer','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2311410','https://www.topcv.vn/viec-lam/data-engineer/2311410.html','2026-10-11T19:40:00+07:00','Data Engineer','Công ty Cổ phần viễn thông FPT','Hà Nội','1 năm','Thoả thuận','thiết kế/xây dựng kiến trúc data pipeline; ETL/ELT; đảm bảo chất lượng dữ liệu; Big Data (Spark, Hadoop, Kafka); API xuất dữ liệu Data Lake/Data Warehouse; tối ưu hiệu năng; hợp tác Data Analyst/Data Scientist','1 năm kinh nghiệm; hệ quản trị CSDL SQL; Python (Pandas, PySpark, SQLAlchemy, Airflow); Big Data (Hadoop, Spark, Kafka, Hive, HDFS); cloud storage (AWS S3, MinIO, GCS); tư duy logic; teamwork; agile; công cụ AI; Đại Học trở lên','2026-09-27','2026-10-24','data_engineer','de_aiml','data_engineer','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2124490','https://www.topcv.vn/viec-lam/data-engineer-lead/2124490.html','2026-10-11T19:40:00+07:00','Data Engineer Lead','CÔNG TY CỔ PHẦN CÔNG NGHỆ ALPHAWAY','Hà Nội','3 năm','Thoả thuận','xây dựng giải pháp và tập trung các tầng xử lý trên hệ thống: Data Warehouse, Data Lake, Data Model; tích hợp tất cả nguồn dữ liệu từ hệ thống ứng dụng vào Data Warehouse/Data Lake; hỗ trợ đơn vị nghiệp vụ khai thác dữ liệu từ hệ thống MIS/DW; phân tích mô hình dữ liệu, dự đoán, dự báo, báo cáo phân tích; báo cáo định kỳ theo quy định hoặc theo yêu cầu quản lý; tham gia các dự án Data Warehouse/Data Lake theo phân công','thành thạo SQL; ít nhất 3 năm kinh nghiệm làm việc; kinh nghiệm làm báo cáo trên công cụ BI (Tableau, Power BI, Oracle BI, Cognos IBM, Jasper...); lập trình báo cáo trên nền tảng AWS, AWS Quicksight; kinh nghiệm triển khai ít nhất một dự án Data Warehouse/báo cáo/ETL cho Ngân hàng/Công ty tài chính; kinh nghiệm phát triển ETL trên Oracle DI, IBM DataStage, SAP Data Services, Talend; kinh nghiệm công cụ tích hợp/khai thác dữ liệu trên AWS (DMS, AWS Glue, workflow...); kiến thức nền tảng dữ liệu AWS (Amazon S3, AWS Foundation, Amazon Redshift...); kiến thức công nghệ đồng bộ dữ liệu AWS DMS, CDC; kinh nghiệm dữ liệu nguồn ứng dụng tác nghiệp Ngân hàng/công ty tài chính; đọc hiểu tài liệu yêu cầu/thiết kế, phối hợp nhóm, kỹ năng trình bày; tốt nghiệp hệ chính quy chuyên ngành CNTT hoặc liên quan','2026-10-09','2026-11-10','data_engineer','de_aiml','data_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2220482','https://www.topcv.vn/viec-lam/data-engineer/2220482.html','2026-10-11T19:40:00+07:00','Data Engineer','CÔNG TY CỔ PHẦN TƯ VẤN CÔNG NGHỆ NGS','Hà Nội','3 năm','20 - 35 triệu','Thiết kế, phát triển, tối ưu hệ thống xử lý dữ liệu; xây dựng, duy trì data pipeline từ SAP, SQL Server, Oracle, API, file; phối hợp nhóm DA/BA; phát triển ETL/ELT bằng SSIS; quản lý hệ thống báo cáo BI; thiết kế data model, schema, phân vùng; tối ưu hiệu suất truy vấn (tuning, indexing, partitioning); đảm bảo chất lượng, toàn vẹn, bảo mật dữ liệu; xử lý ticket yêu cầu khách hàng; chuẩn bị tài liệu dự án (design doc, đề xuất giải pháp)','Tốt nghiệp ĐH CNTT/ĐTVT/KHMT; 3-5 năm kinh nghiệm Data Engineer; SQL, tối ưu truy vấn, dữ liệu lớn; C#/Python/Java; ETL SSIS; ưu tiên SAP BW (DataSource, InfoObject, InfoCube, DSO, Query, Transformation), tích hợp SAP với hệ thống non-SAP, SSAS, Power BI; tiếng Anh công việc là lợi thế; chăm chỉ, nhiệt tình, hòa đồng, trách nhiệm, chủ động, chịu áp lực','','2026-10-31','data_engineer','de_aiml','data_engineer','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2224769','https://www.topcv.vn/viec-lam/data-engineer-leader/2224769.html','2026-10-11T19:40:00+07:00','Data Engineer Leader','Công ty cổ phần Synodus','Hà Nội','Trên 5 năm','Tới 60 triệu','Tư vấn, thiết kế, triển khai giải pháp dữ liệu cho dự án Chuyển đổi số Chính phủ; phân tích yêu cầu nghiệp vụ, đề xuất kiến trúc dữ liệu, lộ trình phát triển nền tảng dữ liệu; thiết kế, xây dựng Data Lake, Data Warehouse, Data Lakehouse; phát triển, tối ưu ETL/ELT, tích hợp dữ liệu nhiều nguồn; xây dựng giải pháp Big Data, xử lý dữ liệu thời gian thực (Real-time Data Processing); đảm bảo data quality, data governance, bảo mật; đánh giá, lựa chọn công nghệ, nền tảng dữ liệu; làm việc trực tiếp với khách hàng, BA, PM; dẫn dắt, review kỹ thuật đội ngũ Data Engineer; xây dựng tài liệu giải pháp, thuyết trình, hỗ trợ Presales','Ít nhất 7 năm kinh nghiệm Data Engineer/Data Platform (triển khai on-premises); tối thiểu 2 năm kinh nghiệm Leader; kinh nghiệm quản lý hoặc Consultant dữ liệu; thành thạo Python, SQL; xử lý dữ liệu quy mô lớn; thiết kế, triển khai Data Warehouse, Data Lake, Lakehouse; Big Data (Spark, Hadoop, Kafka); Data Modeling, ETL/ELT, Data Governance, Data Quality; tư vấn giải pháp, làm việc trực tiếp với khách hàng; xây dựng kiến trúc dữ liệu quy mô lớn; Oracle Data Warehouse là điểm cộng','2026-09-27','2026-10-30','data_engineer','de_aiml','data_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2267172','https://www.topcv.vn/viec-lam/aws-data-engineer-os-bank-lead/2267172.html','2026-10-11T19:40:00+07:00','AWS Data Engineer - OS Bank (Lead)','Công ty TNHH Giải pháp Phân tích dữ liệu Insight Data','Hà Nội','3 năm','Thoả thuận','Phát triển và tối ưu pipeline ETL/ELT trên AWS; Xây dựng, vận hành workflow dữ liệu; Phát triển hệ thống xử lý dữ liệu thời gian thực; Tích hợp dữ liệu qua RESTful API; Xây dựng báo cáo Near Real-time; Theo dõi, tối ưu hiệu năng hệ thống; Phối hợp triển khai giải pháp dữ liệu','Tốt nghiệp Đại học CNTT; Từ 3 năm kinh nghiệm; AWS (S3, Glue, Lambda, Redshift); SQL Server; SSIS; Airflow; dbt; Thành thạo xây dựng ETL/ELT Pipeline; Tối ưu SQL; Xử lý dữ liệu thời gian thực; Kafka; ClickHouse; Tích hợp API; FastAPI; Celery; Data Platform; Data Lakehouse; Data Governance; DataOps','2026-09-20','2026-10-16','data_engineer','de_aiml','data_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2277876','https://www.topcv.vn/brand/smartosc/tuyen-dung/data-engineer-english-speaking-j2277876.html','2026-10-11T19:40:00+07:00','Data Engineer - English Speaking','CÔNG TY CỔ PHẦN SMARTOSC','Đà Nẵng; Hồ Chí Minh','Trên 5 năm','40 - 85 triệu','Design/implement ETL/ELT pipelines; Batch và streaming processing; Ingest từ databases/APIs/files/event streams; CDC; Schema evolution; Data Lake/Lakehouse layers; Curated datasets; Dimensional models (star/snowflake schemas, slowly changing dimensions); Orchestrate pipelines (Airflow/Databricks Workflows); Data quality checks; Reconciliation; Remediation; Metadata; Data lineage; Catalog documentation; Security/access controls; Encryption; Secrets management; Optimize SQL/Spark/storage/compute; Production reliability (SLAs); Observability; Alerting; Incident resolution; Git/CI/CD/automated testing/IaC; Data contracts','5+ năm kinh nghiệm data engineering; Python; SQL; Spark/PySpark; ETL/ELT; Batch/streaming; CDC; Kafka; Azure Event Hubs; Amazon Kinesis; Cloud (GCP/AWS); Databricks; Snowflake; BigQuery; Redshift; Data Lake/Lakehouse; Delta Lake; Parquet; Dimensional modeling; Schema evolution; Airflow/Databricks Workflows; Git; CI/CD; Terraform; Data quality; Lineage; Metadata/catalog tools; Security/access control; Professional working English; Certifications (Databricks, Snowflake, Airflow, GCP, AWS, Azure); dbt; Data Vault; Event-time processing; Data mesh; Governed data products','','2026-10-21','data_engineer','de_aiml','data_engineer','','excluded','Yêu cầu kinh nghiệm Trên 5 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2283544','https://www.topcv.vn/viec-lam/data-engineer/2283544.html','2026-10-11T19:40:00+07:00','Data Engineer','Công ty Cổ phần Công nghệ eUp','Hồ Chí Minh','4 năm','Thoả thuận','vận hành và tối ưu hệ thống dữ liệu trên S3, Apache Iceberg, Athena/Glue; đảm bảo hiệu năng và chi phí; xây dựng và chuẩn hóa định nghĩa chỉ số kinh doanh (doanh thu, CAC, retention, DAU/MAU...); triển khai và vận hành Apache Superset; phục vụ báo cáo nội bộ và dashboard nhúng; đánh giá và triển khai công cụ điều phối pipeline (Dagster/Airflow) thay thế cơ chế cron; hướng dẫn, hỗ trợ và chia sẻ kiến thức với đội ngũ; thiết kế hệ thống lưu trữ dữ liệu học tập (Learning Record Store), phối hợp đội AI; tham gia họp dự án, báo cáo tiến độ và đề xuất giải pháp kỹ thuật','tốt nghiệp Đại học CNTT (ưu tiên KHMT, AI); từ 4 năm kinh nghiệm Data Engineering với hệ thống dữ liệu quy mô lớn; thành thạo hệ sinh thái AWS (S3, Athena/Presto/Trino, Glue Catalog, IAM...); kiến thức định dạng dữ liệu dạng cột (Parquet) và table format hiện đại (Iceberg...); thành thạo SQL và Python (pandas, pyarrow, boto3...); kinh nghiệm thực tế với dbt; đã vận hành công cụ điều phối pipeline (Airflow, Dagster, Prefect); sử dụng thành thạo Git; tư duy làm việc chuyên nghiệp (review, kiểm thử, khôi phục)','2026-09-27','2026-10-31','data_engineer','de_aiml','data_engineer','','excluded','Yêu cầu kinh nghiệm 4 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2297125','https://www.topcv.vn/viec-lam/data-engineer-lead/2297125.html','2026-10-11T19:40:00+07:00','Data Engineer (Lead)','CÔNG TY TNHH TRUYỀN HÌNH FPT','Hồ Chí Minh','2 năm','Thoả thuận','xây dựng/vận hành data pipeline; ingest sự kiện hành vi người dùng từ Kafka; batch sources; data warehouse; thiết kế/tối ưu model dữ liệu trên ClickHouse (user profile, attribute, event aggregate); tích hợp service nội bộ qua interface trừu tượng; Airflow DAG; export dữ liệu (hash PII); unit/integration test; code review; migration DB; monitoring & alert; design doc (HLA, ERD)','2–4 năm kinh nghiệm Data Engineer; SQL (đọc execution plan); analytical database (ClickHouse, BigQuery, Redshift, Snowflake, Druid); RDBMS (PostgreSQL/MySQL); workflow orchestration (Airflow/Dagster/Prefect: dependency, backfill, idempotency); Kubernetes; CI/CD (GitLab CI); Infrastructure as Code; Spark/Flink; sản phẩm B2C traffic lớn (OTT, e-commerce, fintech); data privacy/PII (hashing, consent, opt-out); Đại Học trở lên; cấp bậc Trưởng nhóm','2026-09-11','2026-10-15','data_engineer','de_aiml','data_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2297445','https://www.topcv.vn/viec-lam/data-engineer-lakehouse-big-data/2297445.html','2026-10-11T19:40:00+07:00','Data Engineer (Lakehouse/ Big Data)','CÔNG TY TNHH MỘT THÀNH VIÊN AN NINH MẠNG VIETTEL','Hà Nội','4 năm','Thoả thuận','Xây dựng và mở rộng data pipeline; Ingest dữ liệu từ nguồn mới (REST API, XML/CSV/JSON, Kafka) về lakehouse; Incremental load; Checkpoint; Schema evolution; Chuẩn hoá, clean, dedup dữ liệu; Đối sánh và hợp nhất dữ liệu; Xây serving layer (upsert PostgreSQL/MongoDB); Viết và bảo trì DAG (dependency, retry, backfill, schedule); Data expectation; Test tự động; Xử lý alert; Debug lỗi và hiệu năng (data skew, small file, OOM); Tối ưu query; Unit test; Code review; CI; Phối hợp Product, BI, AI; Metadata; Lineage; Data dictionary','Từ 4 năm kinh nghiệm Data Engineer; SQL nâng cao (window function, CTE, EXPLAIN); Python (pytest, exception handling, logging); Spark/PySpark (partition, shuffle, join strategy, Spark UI); Airflow/Dagster/Prefect; Data warehouse/lakehouse; Data modeling; Incremental load; Schema evolution; PostgreSQL; MongoDB; S3/MinIO; Docker; Data quality; Java; Scala; Spark Streaming; Batch processing; ETL/Data Pipeline; Nice-to-have: Apache Iceberg; Delta Lake; Hudi; Trino/Presto; Great Expectations; Soda; dbt test; OpenMetadata; DataHub; Amundsen; Kafka; Kubernetes; AWS/GCP/Azure; Data governance/security; Agentic AI','2026-09-11','2026-12-31','data_engineer','de_aiml','data_engineer','','excluded','Yêu cầu kinh nghiệm 4 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2300149','https://www.topcv.vn/viec-lam/data-product-semantic-layer-engineer/2300149.html','2026-10-11T19:40:00+07:00','Data Product & Semantic Layer Engineer','FPT Software','Hà Nội','5 năm','Thoả thuận','Design/build/optimize Data Products; Medallion architecture (Bronze, Silver, Gold); Business reporting/analytics/AI use cases; Develop/maintain data pipelines, workflows, transformations; Reusable data models; Business metrics; Semantic layers; Data governance standards; Metadata; Lineage; Ownership; Access controls; Data quality; Freshness; Observability; Monitoring; Validation; Automated testing; Databricks Genie; Technical documentation; Maintainable/reusable solutions; Mentor junior team members; Knowledge sharing','5 năm kinh nghiệm Data Engineering/Data Products/Analytics Engineering; Databricks; SQL; Python/PySpark; Delta Lake; Data modelling (facts, dimensions, business keys, domain models); Unity Catalog; Metadata management; Lineage; Access control; Semantic layers; Business metrics; Data quality; Databricks Genie; Professional English proficiency (written and spoken); Stakeholder management; Communication; Leadership; Coaching; Documentation; Problem-solving','','2026-10-14','data_engineer','de_aiml','data_engineer','','excluded','Yêu cầu kinh nghiệm 5 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2307492','https://www.topcv.vn/viec-lam/chuyen-vien-he-thong-du-lieu/2307492.html','2026-10-11T19:17:47+07:00','Chuyên Viên Hệ Thống Dữ Liệu','Công ty TNHH Phát triển công nghệ điện tử Bình Anh','Hà Nội','3 năm','18 - 22 triệu','Quản trị Data Warehouse; quản trị chất lượng dữ liệu; hỗ trợ khai thác dữ liệu và báo cáo; vận hành và cải tiến hệ thống báo cáo.','Đại học CNTT/Hệ thống thông tin; Data Warehouse, ETL/ELT, Data Modeling; thành thạo Oracle SQL; Stored Procedure/Function/Package trên Oracle; Index, Partition, Statistics, Performance Tuning Oracle; chuyển đổi yêu cầu nghiệp vụ thành mô hình dữ liệu.','','2026-10-29','data_analyst','data_analyst','data_engineer','quản trị Data Warehouse','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2307790','https://www.topcv.vn/viec-lam/data-engineer-upto-27-tr-gross-lam-t2-den-t6-du-an-onsite-bank/2307790.html','2026-10-11T19:40:00+07:00','Data Engineer - Upto 27 Tr (Gross) - Làm T2 Đến T6 - Dự Án Onsite Bank','Công ty Cổ phần Giải pháp Công nghệ TTC Việt Nam','Hà Nội','3 năm','20 - 27 triệu','Phân tích dữ liệu từ DWH/Data Mart; thiết kế Data Vault (Hub, Link, Satellite), Data Warehouse, Data Mart; xây dựng ETL/ELT từ Core system (T24, Way4), Kafka, API, S3/MinIO; xây dựng dashboard/báo cáo, Data API, Data Engine, Data Allocation; chuẩn hóa KPI và business metrics; phân tích nghiệp vụ Collection, Risk, Customer 360, Finance, Fraud; làm việc với BA, business user, stakeholder; thiết kế data model các tầng; tối ưu hiệu năng (SQL tuning, partition, indexing); quản lý lifecycle dữ liệu (Hot-Warm-Cold, Archiving); triển khai Data Quality & validation; hỗ trợ use case Customer 360, Collection, Risk','Tốt nghiệp ĐH CNTT; tư duy logic, tác phong chuyên nghiệp; BI tools (Tableau, PowerBI, SAP BusinessObjects); ETL (IBM DataStage, SAP Data Services, AWS Glue); CDC (Oracle Goldengate, Kafka, AWS DMS); SQL, Python, Java; kiến trúc Data Warehouse, Data Vault, Data Mart, Star Schema, Snowflake; ưu tiên kinh nghiệm Tài chính/Ngân hàng; tiếng Anh giao tiếp cơ bản','2026-09-27','2026-11-18','data_engineer','de_aiml','data_engineer','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2314150','https://www.topcv.vn/viec-lam/lead-data-engineer/2314150.html','2026-10-11T19:40:00+07:00','Lead Data Engineer','CÔNG TY CỔ PHẦN CÔNG NGHỆ SICIX','Hà Nội','3 năm','20 - 40 triệu','Thiết kế, xây dựng, vận hành pipeline thu thập, xử lý dữ liệu (ETL/ELT) từ database, API, file, log, third-party; xây dựng, tối ưu Data Warehouse/Data Lake; thiết kế data model phục vụ báo cáo, phân tích; xây dựng, giám sát, tối ưu job batch/real-time (streaming); hợp tác với Data Analyst, phòng ban nghiệp vụ; cung cấp dữ liệu sạch, chuẩn hóa cho Dashboard; xây dựng cơ chế kiểm soát data quality, data validation, giám sát, xử lý lỗi; đảm bảo bảo mật, phân quyền truy cập; nghiên cứu, đề xuất công nghệ mới; viết, duy trì tài liệu kỹ thuật (data dictionary, sơ đồ luồng dữ liệu)','Tốt nghiệp ĐH CNTT/Toán-Thống kê/Kinh tế; 3 năm kinh nghiệm Data Engineer; thành thạo SQL; Python hoặc Java/Scala; ETL/ELT (Apache, dbt, Talend); Big Data (Spark, Kafka, Hadoop) là lợi thế; kiến trúc Data Warehouse, Data Lake, star schema, snowflake; thiết kế, tối ưu SQL trên dữ liệu lớn; CSDL (MySQL, PostgreSQL), NoSQL (MongoDB, Redis); Cloud (AWS, GCP, Azure), S3, Redshift, BigQuery là lợi thế; data governance, data quality; ưu tiên streaming, tối ưu hiệu năng dữ liệu lớn','','2026-10-28','data_engineer','de_aiml','data_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2315835','https://www.topcv.vn/viec-lam/database-engineer-dba/2315835.html','2026-10-11T19:40:00+07:00','Database Engineer (DBA)','Công Ty TNHH LG CNS VIỆT NAM','Hà Nội','3 năm','Thoả thuận','vận hành & tối ưu hệ thống database đảm bảo high availability, bảo mật, ổn định; tham gia dự án database on-premises & cloud (AWS, Azure, GCP); tham gia thiết kế, xây dựng, kiểm thử hệ thống database trên public cloud; phối hợp chuyên gia DB Hàn Quốc trong triển khai, migration, performance tuning, troubleshooting; quản lý đối tượng DB (Table, Index, View, Stored Procedure...); duy trì chiến lược backup & recovery; giám sát hiệu năng hệ thống & xử lý sự cố; hỗ trợ triển khai & phát hành ứng dụng; cài đặt & quản lý hệ thống database (Oracle, MSSQL, MySQL)','kinh nghiệm thực chiến ít nhất 2 nền tảng database (Oracle, MSSQL, MySQL, PostgreSQL, MongoDB...); kiến thức/kinh nghiệm database migration; kinh nghiệm làm việc trên public cloud (AWS, GCP, Azure); khả năng giao tiếp tiếng Anh; tư duy phân tích, tư duy hệ thống, chủ động, teamwork; ưu tiên: kinh nghiệm thiết kế/xây dựng/vận hành DB trên cloud (RDS, Redshift, BigQuery...); phát triển SQL và performance tuning (MySQL, MariaDB, PostgreSQL, Oracle); Shell Scripting, PL/SQL, Python, công cụ ETL','2026-10-04','2026-10-29','data_engineer','de_aiml','data_engineer','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2317290','https://www.topcv.vn/viec-lam/data-engineer-upto-27-tr-gross-t2-t6-onsite-bank/2317290.html','2026-10-11T19:40:00+07:00','Data Engineer - Upto 27 Tr (Gross) - T2 - T6 - Onsite Bank','Công ty Cổ phần Giải pháp Công nghệ TTC Việt Nam','Hà Nội','3 năm','20 - 27 triệu','phân tích dữ liệu từ DWH/Data Mart; thiết kế Data Vault (Hub, Link, Satellite), Data Warehouse và Data Mart; xây dựng ETL/ELT từ Core system (T24, Way4...), Kafka, API, S3/MinIO; xây dựng dashboard/báo cáo, Data API, Data Engine, Data Allocation; chuẩn hóa KPI và business metrics; phân tích chủ đề nghiệp vụ (Collection, Risk, Customer 360, Finance, Fraud); làm việc với BA, business user và stakeholder; thiết kế Data model các tầng nền tảng dữ liệu doanh nghiệp; tối ưu hiệu năng (SQL tuning, partition, indexing); quản lý lifecycle dữ liệu (Hot – Warm – Cold, Archiving); triển khai Data Quality & validation; hỗ trợ use case Customer 360, Collection, Risk','tối thiểu 3 năm kinh nghiệm Data Engineer; thành thạo SQL; kinh nghiệm ETL/ELT và Data Warehouse/Data Mart; kinh nghiệm Python; kiến thức data modeling và xử lý dữ liệu; ưu tiên: Kafka hoặc CDC/Data Streaming; Data Vault, Star Schema, Snowflake Schema; AWS Glue, AWS DMS, Oracle GoldenGate; Power BI, Tableau; kinh nghiệm lĩnh vực Tài chính/Ngân hàng; đã làm việc với T24, Way4 hoặc hệ thống Core Banking','','2026-11-18','data_engineer','de_aiml','data_engineer','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2317682','https://www.topcv.vn/viec-lam/data-team-leader/2317682.html','2026-10-11T19:40:00+07:00','Data Team Leader','NTQ Solution','Hà Nội','1 năm','Thoả thuận','Quản lý, dẫn dắt, xây dựng đội ngũ Data Engineer; phân công công việc, định hướng phát triển; thiết kế, xây dựng, tối ưu data pipelines, data warehouse, data lake; hands-on ETL/ELT phức tạp, đảm bảo toàn vẹn, bảo mật; tham gia Presales: phân tích yêu cầu khách hàng, ước lượng effort; làm việc, phỏng vấn, trao đổi với khách hàng nước ngoài bằng tiếng Anh; thiết kế mô hình dữ liệu (Data Modeling) phục vụ BI/Analytics; theo dõi, giám sát, tối ưu hiệu năng, xử lý sự cố (troubleshooting); nghiên cứu, thử nghiệm công nghệ Big Data, Cloud Data Platform; code review, mentoring, đào tạo thành viên; xây dựng coding standards, data testing, hoàn thiện quy trình','Ít nhất 1 năm ở vị trí Lead/Sub-lead hoặc kinh nghiệm quản lý team; tiếng Anh giao tiếp trôi chảy (tương đương IELTS); thành thạo Python, Scala hoặc Java; tối ưu SQL; ETL/ELT & Big Data (Apache Spark, Apache Airflow); Cloud: AWS (Glue/Redshift...); Data Modeling (Star Schema, Snowflake); leadership: quản lý công việc, lập kế hoạch, phân công task; ưu tiên: chứng chỉ Cloud/Data (AWS Certified Data Engineer, GCP Professional Data Engineer), Real-time Data Streaming (Kafka, Flink, Spark Streaming), Data Governance/Data Quality/Data Security, môi trường Software Outsourcing, AI/MLOps','','2026-10-31','data_engineer','de_aiml','data_engineer','chức danh quản lý; dẫn dắt team Data Engineer','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2322968','https://www.topcv.vn/viec-lam/data-engineering-leader/2322968.html','2026-10-11T19:40:00+07:00','Data Engineering Leader','CÔNG TY CP DỊCH VỤ THƯƠNG MẠI ĐIỆN TỬ N & H','Hồ Chí Minh','5 năm','Thoả thuận','Thiết kế, vận hành, tối ưu Data Platform; xây dựng Data Warehouse/Data Mart; phát triển ETL/ELT pipeline bằng Python, REST API, Microsoft Graph API; tích hợp dữ liệu từ AWS S3, SAP HANA, PostgreSQL, Oracle, MySQL, SQL Server, MongoDB, SharePoint; phát triển Data Portal tiếp nhận/xử lý dữ liệu Excel; phát triển Notebook trên Microsoft Fabric xử lý dữ liệu lớn; xây dựng AWS Lambda tự động đồng bộ dữ liệu; tối ưu Stored Procedures, Indexes, truy vấn phức tạp; tự động phân quyền/cắt quyền người dùng, sao lưu báo cáo SSRS; phối hợp phòng ban nghiệp vụ, đảm bảo chính xác, ổn định, bảo mật','Tốt nghiệp ĐH CNTT/KHMT/HTTT; 5 năm kinh nghiệm Data Engineer/Data Platform/BI-Data Warehouse; thành thạo Python, SQL, stored procedures; thiết kế/vận hành Data Warehouse/Data Mart; ETL/ELT pipeline; PostgreSQL, MySQL, SQL Server, Oracle, MongoDB; REST API, Microsoft Graph API; AWS (S3, Lambda); Microsoft Fabric/Notebook, SSRS là lợi thế; Data Modeling, Indexing, Query Optimization; bảo mật dữ liệu, phân quyền người dùng; tư duy logic, chủ động; phối hợp phòng ban','2026-10-07','2026-11-06','data_engineer','de_aiml','data_engineer','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','1773238','https://www.topcv.vn/viec-lam/giang-vien-cong-nghe-thong-tin-khoa-hoc-may-tinh/1773238.html','2026-10-11T19:40:00+07:00','Giảng Viên Công Nghệ Thông Tin/ Khoa Học Máy Tính','Trường Đại học CMC','Hà Nội; Hồ Chí Minh','1 năm','Thoả thuận','giảng dạy các học phần (lập trình C, C+, C#, Python, Java, Web, Mobile, CSDL, Hệ QTCSDL, Công nghệ phần mềm, Triển khai phần mềm; cấu trúc dữ liệu và giải thuật, Toán rời rạc, AI và Học máy, Khai phá dữ liệu; mạng máy tính, Hệ điều hành, Kiến trúc máy tính, Cloud, An toàn bảo mật thông tin); nghiên cứu khoa học theo quy định của nhà trường; phát triển chuyên môn: xây dựng/chỉnh sửa đề cương học phần, cố vấn học tập...','tốt nghiệp Thạc sĩ trở lên các chuyên ngành CNTT, Khoa học máy tính, Kỹ thuật máy tính...; ưu tiên có kinh nghiệm giảng dạy đại học; kinh nghiệm làm việc thực chiến về CNTT và KHMT; ứng dụng CNTT trong giảng dạy, nghiên cứu; đọc và nghiên cứu tài liệu bằng tiếng Anh; giao tiếp, giảng dạy bằng tiếng Anh; giao tiếp, kết nối tốt; định hướng phát triển lâu dài trong ngành giáo dục; phẩm chất đạo đức nghề nghiệp, ý thức chấp hành pháp luật; tác phong sư phạm, trung thực, chịu áp lực công việc cao; sáng tạo và tư duy độc lập','2026-10-07','2026-10-31','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','1865273','https://www.topcv.vn/viec-lam/thuc-tap-sinh-phan-tich-dau-tu/1865273.html','2026-10-11T19:17:47+07:00','Thực Tập Sinh Phân Tích Đầu Tư','CÔNG TY TNHH ĐẦU TƯ VÀ PHÁT TRIỂN FINTOP','Hà Nội, Hồ Chí Minh','Không yêu cầu','2 - 3 triệu','nghiên cứu, phân tích thị trường đầu tư, chứng khoán, tài chính, kinh tế; phân tích doanh nghiệp, ngành kinh tế; cung cấp thông tin, cơ hội, dữ liệu đầu tư; tham gia hội thảo, báo cáo nghiên cứu phân tích đầu tư; xây dựng và phát triển kênh phân tích chia sẻ thông tin/dữ liệu đầu tư cho cộng đồng; làm báo cáo phân tích: nghiên cứu thị trường, phân tích ngành, phân tích doanh nghiệp, phân tích định lượng; họp và đào tạo với lãnh đạo, cán bộ quản lý; đào tạo, hướng dẫn triển khai cho nhóm','đam mê lĩnh vực phân tích, đầu tư; định hướng phát triển lâu dài; kinh nghiệm thực chiến thị trường đầu tư, nghiên cứu, phân tích doanh nghiệp, ngành, kinh tế vĩ mô; kết quả đầu tư hiệu quả (lợi thế); chủ động, năng động, sáng tạo, cầu thị; giao tiếp, truyền đạt tốt; làm việc nhóm, chuyên nghiệp; phân tích, trình bày, tư duy logic, đàm phán, thuyết phục; kỹ năng văn phòng; trình độ đại học; nền tảng Kinh tế, Tài chính (lợi thế)','','2026-11-06','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','eligible','Phù hợp: tiêu đề thực tập sinh; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','1987324','https://www.topcv.vn/viec-lam/nhan-vien-doi-soat/1987324.html','2026-10-11T19:17:47+07:00','Nhân Viên Đối Soát','Công Ty TNHH MTV Viễn Thông Quốc Tế FPT','Hà Nội (Tầng 17–18, Tòa A, FPT Tower, số 10 Phạm Văn Bạch, Phường Cầu Giấy)','2 năm','Thoả thuận','Tiếp nhận nhu cầu Trung tâm Kinh doanh, kiểm tra hồ sơ chứng từ, chuyển thông tin đến nhà cung cấp để khai báo dịch vụ, theo dõi tiến độ và cập nhật các bên; kiểm tra/duyệt khai báo trên trang nội bộ; nhận thông tin cước/dịch vụ phát sinh từ NCC, phân tích số liệu, đối soát với số liệu công ty để chốt với NCC; trình ký biên bản đối soát, nhận/kiểm tra hóa đơn, đối chiếu công nợ, làm hồ sơ thanh toán NCC; đối soát với khách hàng, gửi biên bản đối soát cho kinh doanh, đề nghị xuất hóa đơn; kiểm tra số liệu kênh nội bộ, lập bảng kê, thủ tục thanh toán trên hệ thống nội bộ; lập báo cáo theo yêu cầu.','Tốt nghiệp đại học trở lên; ít nhất 2 năm kinh nghiệm vị trí tương đương; kỹ năng phân tích số liệu tỉ mỉ, chính xác, thành thạo Excel; trách nhiệm, cần mẫn, giao tiếp tốt, chịu được áp lực; thích ứng nhanh, chủ động tổ chức và kiểm soát công việc; sáng tạo; tiếng Anh thành thạo là lợi thế.','','2026-10-31','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2131596','https://www.topcv.vn/viec-lam/ai-artist-intern/2131596.html','2026-10-11T19:40:00+07:00','AI Artist Intern','CÔNG TY CỔ PHẦN SÁNG TẠO WONDER LEAF','Hồ Chí Minh','Dưới 1 năm','Tới 2 triệu','Sản xuất phim hoạt hình thiếu nhi bằng AI (Text-to-Image, Video AI, Motion AI); chuẩn bị asset cho các shot theo kịch bản; tạo keyframe theo storyboard/stillomatic; chỉnh sửa ảnh AI (inpaint, upscale, variation); tạo video AI theo storyboard; phối hợp đạo diễn hình ảnh và team leader','Công cụ AI tạo hình ảnh (Nano Banana, Midjourney); công cụ AI tạo video (Seedance, Kling); viết prompt; bố cục, ánh sáng, chuyển động; character consistency; Creativity; Problem-solving; (ưu tiên) Photoshop, Premiere, storyboard','','2026-10-31','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: tiêu đề intern; kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2157892','https://www.topcv.vn/viec-lam/giao-vien-day-mon-tri-tue-nhan-tao-part-time/2157892.html','2026-10-11T19:40:00+07:00','Giáo Viên Dạy Môn Trí Tuệ Nhân Tạo (Part-Time)','BrightChamps','Hồ Chí Minh','Dưới 1 năm','0.2 - 0.2 triệu','giảng dạy Trí tuệ Nhân tạo (GenAI); học sinh 6–12 tuổi; chương trình Summer Camp; quản lý lớp học; môi trường học tập tích cực; phương pháp giảng dạy sinh động, dễ hiểu; theo dõi và hỗ trợ học tập','kinh nghiệm giảng dạy AI offline; học sinh tiểu học; kiến thức cơ bản AI; ứng dụng AI cơ bản; quản lý lớp học; giao tiếp với trẻ nhỏ; chứng chỉ giảng dạy / chứng chỉ GenAI; lập trình (Python, Java); kỹ năng giảng dạy; truyền đạt thông tin; thiết kế bài giảng; tạo động lực học viên; thích ứng phương pháp giảng dạy mới; ưu tiên kinh nghiệm Summer Camp / ngoại khóa','2026-10-04','2026-10-30','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2168153','https://www.topcv.vn/viec-lam/account-marketing-cum-plan-executiveung-dung-ai/2168153.html','2026-10-11T19:40:00+07:00','ACCOUNT MARKETING CUM PLAN EXECUTIVE(Ứng Dụng AI)','CÔNG TY CỔ PHẦN TRUYỀN THÔNG ONSET MARKETING','Đà Nẵng','Dưới 1 năm','8 - 12 triệu','làm việc trực tiếp với khách hàng, tiếp nhận brief, tư vấn giải pháp Marketing; hiểu mục tiêu kinh doanh nhà hàng để định hướng chiến lược nội dung và quảng cáo; xây dựng quan hệ lâu dài, gia tăng hài lòng và tái ký hợp đồng; lập kế hoạch marketing tháng/quý cho từng khách hàng; xác định mục tiêu chiến dịch (traffic, booking, doanh thu, nhận diện thương hiệu); lập timeline content, ads, ưu đãi; đề xuất campaign, chương trình khuyến mãi theo mùa vụ/lễ hội; theo dõi và điều chỉnh kế hoạch theo hiệu quả thực tế; điều phối team nội bộ (Content, Design, Media, Digital) và team ngoại bộ (Review, KOC/KOL, mẫu); quản lý timeline, checklist, deadline; đảm bảo triển khai đúng brief; ứng dụng AI: tổng hợp dữ liệu, rút insight, đề xuất cải tiến; gợi ý ý tưởng, lập kế hoạch/chiến dịch; xử lý nội dung cơ bản; chỉnh sửa content, hình ảnh đơn giản; tối ưu proposal, báo cáo; tóm tắt meeting notes, tạo checklist; kiểm soát chất lượng nội dung; cập nhật tiến độ, quản lý kỳ vọng khách hàng; báo cáo định kỳ tuần/tháng; phân tích kết quả chiến dịch (engagement, leads, doanh thu); xử lý phản hồi; soạn proposal, báo giá, biên bản họp, hợp đồng; xây dựng và cải tiến quy trình bằng công cụ số và AI','kinh nghiệm Account/Project/Client Service (ưu tiên Agency); giao tiếp tốt, khéo léo, xử lý tình huống linh hoạt; trách nhiệm cao, chủ động giải quyết vấn đề; thành thạo AI để tăng hiệu suất công việc (bắt buộc); tư duy hệ thống; đa nhiệm; quản lý thời gian tốt; hiểu ngành FnB hoặc từng làm dự án nhà hàng; kiến thức Facebook Ads/TikTok Ads/Google Ads; đọc báo cáo và phân tích hiệu quả chiến dịch; viết nội dung cơ bản','','2026-10-14','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2168192','https://www.topcv.vn/viec-lam/content-marketing-ung-dung-ai/2168192.html','2026-10-11T19:40:00+07:00','Content Marketing (Ứng Dụng AI)','CÔNG TY CỔ PHẦN TRUYỀN THÔNG ONSET MARKETING','Đà Nẵng','1 năm','7 - 11 triệu','xây dựng kế hoạch nội dung tháng/quý đa nền tảng (Fanpage, TikTok, Website, Google Ads); nghiên cứu thị trường, phân tích insight khách hàng, xây dựng chân dung mục tiêu; lên concept, content direction cho chiến dịch (khai trương, ưu đãi, seasonal campaigns); phối hợp Account, Design, Media; viết content đa nền tảng (Facebook, TikTok, Website, Landing Page, Ads); viết kịch bản video ngắn, viral reel, TVC ngắn; tối ưu nội dung quảng cáo theo Performance Mindset (CTR/CR); viết bài chuẩn SEO, xây dựng bộ từ khóa; dùng AI phân tích đối thủ, khảo sát xu hướng, xây dựng outline; AI tinh chỉnh thông điệp, cá nhân hóa CTA; tái định dạng nội dung (Text-to-Video, Blog-to-Social); thử nghiệm công cụ AI mới; thiết kế hình ảnh social cơ bản; dựng video ngắn bắt trend; AI tạo hình ảnh/video (Midjourney, Runway, Canva AI)','1+ năm Content Marketing (ưu tiên Agency hoặc F&B/Lifestyle); lập kế hoạch nội dung đa kênh theo phễu khách hàng; kỹ thuật đặt câu lệnh (Prompt) trên ChatGPT, Claude, Gemini; nội dung chuẩn SEO; tư duy viết bài chuyển đổi (Performance Content); tư duy marketing, hiểu khách hàng; Canva, CapCut; ứng dụng AI tạo hình ảnh/video (Midjourney, Leonardo, Runway); chủ động, trách nhiệm, chịu được áp lực deadline; làm việc đa dự án; tư duy performance (Facebook/TikTok/Google Ads); đọc dữ liệu và tối ưu nội dung; xây dựng quy trình content bằng AI; gu thẩm mỹ, nhạy bén với xu hướng','2026-09-20','2026-10-14','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2169120','https://www.topcv.vn/viec-lam/bien-kich-ung-dung-ai/2169120.html','2026-10-11T19:40:00+07:00','Biên Kịch Ứng Dụng AI','CÔNG TY CỔ PHẦN TẬP ĐOÀN ĐỨC TÍN TOÀN CẦU','Hà Nội','1 năm','10 - 15 triệu','Viết kịch bản cùng AI (brainstorm, chỉnh sửa, định hình câu chuyện); định hình phong cách hình ảnh/tinh thần thương hiệu; casting diễn viên AI (nhân vật ảo nhất quán xuyên series); đạo diễn bằng câu lệnh (hướng dẫn AI diễn xuất, cảm xúc, lời thoại); phối hợp editor/designer dựng bối cảnh; quyết định từng khung hình (góc máy, bố cục, take nào pass/render lại); hậu kỳ (dựng phim, chỉnh màu, nhạc, hòa âm)','Viết kịch bản; kể chuyện bằng hình; công cụ AI video (Seedance, Kling) và AI ảnh (Midjourney, Nano Banana); viết prompt chuyên nghiệp; dựng phim cơ bản; học công cụ AI mới; ElevenLabs; Suno; HeyGen; Giải quyết vấn đề; Nghiên cứu và Phân tích','','2026-10-24','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2178186','https://www.topcv.vn/viec-lam/nhan-vien-kinh-doanh-giai-phap-ai-ban-hang/2178186.html','2026-10-11T19:40:00+07:00','Nhân Viên Kinh Doanh Giải Pháp AI Bán Hàng','CÔNG TY CỔ PHẦN CÔNG NGHỆ AIBUS','Hà Nội','Dưới 1 năm','10 - 15 triệu','Phân loại Lead tiềm năng từ nguồn Ads; Tư vấn giải pháp chuyên sâu, phân tích quy trình khách hàng; Demo giải pháp Azbot, hướng dẫn dùng thử; Thu thập thông tin, phối hợp kỹ thuật tạo bot mẫu "may đo"; Đàm phán gói dịch vụ, ký hợp đồng, theo dõi thanh toán, công nợ; Chăm sóc Account giai đoạn đầu, tái ký và giới thiệu khách hàng mới','Tốt nghiệp Đại học/Cao đẳng; Hiểu biết sản phẩm phần mềm (SaaS); Tư duy phễu khách hàng (Marketing Funnel); Giao tiếp hoạt ngôn, giọng rõ ràng, chuẩn; Tin học văn phòng; Phân tích dữ liệu; Chăm sóc khách hàng; Bán hàng; Tư duy phản biện; Lắng nghe; Sử dụng CRM','','2026-11-30','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2233421','https://www.topcv.vn/viec-lam/presale-giai-phap-ai-camera/2233421.html','2026-10-11T19:40:00+07:00','Presale Giải Pháp AI Camera','CÔNG TY CỔ PHẦN CÔNG NGHỆ HANET','Hà Nội','2 năm','Từ 20 triệu','Tiếp nhận yêu cầu và bài toán khách hàng cùng đội kinh doanh; Khảo sát hiện trạng, hệ thống hạ tầng; Thiết kế sơ đồ kiến trúc giải pháp (Topology), lựa chọn thiết bị, phần mềm, mô hình triển khai (On-premise/Cloud); Viết proposal, thuyết minh kỹ thuật, BoQ, hồ sơ thầu; Thuyết trình, demo, trình bày giải pháp kỹ thuật; Đào tạo đội kinh doanh về sản phẩm HANET AI Camera; Tính toán chi phí, cấu hình thiết bị, báo giá; Phối hợp kỹ thuật & R&D kiểm thử tính năng AI, chuẩn bị demo; Lưu trữ tài liệu kỹ thuật, bản vẽ, proposal mẫu','Tốt nghiệp Đại học CNTT, Điện tử Viễn thông, Tự động hóa; 2 năm Presale/Kỹ sư giải pháp (CCTV, AI Camera, Smart City, Access Control, IT/Network); Camera IP, NVR, Server, LAN/WAN, 4G; AI (nhận diện khuôn mặt, biển số, ReID, phân tích hành vi); ONVIF, RTSP, WebRTC, MQTT, AI Box, Edge AI; PowerPoint, Excel, Visio, AutoCAD; Thuyết trình, tư duy hệ thống, đọc bản vẽ kỹ thuật; Tiếng Anh/Tiếng Trung đọc hiểu','2026-09-11','2026-10-17','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2266529','https://www.topcv.vn/viec-lam/video-editor-ung-dung-ai-thu-nhap-hap-dan-upto-35m/2266529.html','2026-10-11T19:40:00+07:00','Video Editor (Ứng Dụng AI) - Thu Nhập Hấp Dẫn Upto 35M','CÔNG TY TNHH DAHO MEDIA','Hà Nội','Dưới 1 năm','Tới 35 triệu','Dựng và hậu kỳ video YouTube; Đảm bảo chất lượng hình ảnh, âm thanh, nhịp dựng; Dùng công cụ AI tạo hình ảnh, video theo nội dung/cảm xúc câu chuyện; Kết hợp hiệu ứng, đồ họa, âm nhạc, sound effect; Phối hợp đội ngũ nội dung về tiến độ, chất lượng','Tư duy dựng phim; Kể chuyện bằng hình ảnh; CapCut; Premiere Pro; DaVinci Resolve; Cảm nhận nhịp dựng; Bố cục khung hình; Góc máy; Xử lý màu sắc, ánh sáng; Yêu thích YouTube, công nghệ AI, sáng tạo; Chủ động, trách nhiệm, sẵn sàng học hỏi; Không yêu cầu bằng cấp; Ưu tiên: dựng phim ngắn, video storytelling, documentary, portfolio thực tế','2026-09-20','2026-10-20','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2271650','https://www.topcv.vn/viec-lam/marketing-executive-giai-phap-ai-automation/2271650.html','2026-10-11T19:40:00+07:00','Marketing Executive Giải Pháp AI & Automation','CÔNG TY CỔ PHẦN OKHUB VIỆT NAM','Hà Nội','1 năm','12 - 15 triệu','Lập & triển khai chiến dịch marketing (digital, content, email, social); nhận diện thương hiệu, tạo lead, tăng trưởng người dùng; nội dung & tài liệu bán hàng SaaS du lịch (landing page, case study, demo script); nghiên cứu thị trường & đối thủ SaaS du lịch; quản lý & tối ưu SEO/SEM, Email, Social, Paid Ads; KPI (CAC, MQL, SQL, conversion rate, churn rate); website, blog, newsletter; đối tác/agency; sự kiện, hội thảo ngành','1-2 năm Marketing Executive; ưu tiên SaaS/B2B tech; ngành du lịch (OTA, khách sạn, lữ hành, travel-tech); SEO; SEM; Email Marketing; Social Media; Google/Facebook Ads; viết content; phân tích số liệu; Google Analytics; Excel; edit video (Capcut), hình ảnh; công cụ AI; làm việc độc lập & nhóm; Tiếng Anh đọc hiểu','','2026-10-31','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2276335','https://www.topcv.vn/viec-lam/2d-ai-artist/2276335.html','2026-10-11T19:40:00+07:00','2D AI Artist','CÔNG TY CỔ PHẦN PHÁT TRIỂN CÔNG NGHỆ ARCHER STUDIO','Hà Nội','2 năm','Thoả thuận','Thiết kế art style game idle tycoon/casual mobile; UI/UX 2D; character, environment, props; sản xuất bộ asset lớn; marketing assets; ứng dụng AI image vào sản xuất; phối hợp Game Designer/PO/Animator/Developer; sáng tạo concept art','2–3 năm 2D Game Artist; Digital Creative mobile game; Photoshop; Illustrator; Clip Studio/Procreate; Midjourney; Google Nano Banana; ComfyUI node-based; reference-driven workflow; style-lock methodology; paint over; đồng bộ artstyle; UI/UX game mobile casual; vẽ tay/digital painting; animation/Spine/After Effects (lợi thế); portfolio','2026-09-20','2026-10-18','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2296345','https://www.topcv.vn/viec-lam/nhan-vien-thiet-ke-graphic-designer-su-dung-ai/2296345.html','2026-10-11T19:40:00+07:00','Nhân Viên Thiết Kế - Graphic Designer (Sử Dụng AI)','CÔNG TY CỔ PHẦN TRUYỀN THÔNG VÀ GIẢI TRÍ HG ENTERTAINMENT','Hà Nội','1 năm','9 - 13 triệu','Thiết kế thumbnail YouTube bằng công cụ AI và phần mềm thiết kế; chỉnh sửa/hoàn thiện hình ảnh AI-generated; cân chỉnh màu sắc, ánh sáng, bố cục; thiết kế typography thumbnail; nghiên cứu/thử nghiệm công cụ AI mới; xây dựng template và thư viện hình ảnh/prompt/AI asset; tối ưu quy trình sản xuất thiết kế','Photoshop; Illustrator; tư duy thẩm mỹ; công cụ sản xuất hình ảnh AI (Mid Journey, Stable Diffusion); khả năng tự nghiên cứu/học công cụ mới; kỹ năng cộng tác; đam mê công nghệ','','2026-11-08','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2298773','https://www.topcv.vn/viec-lam/video-ai-marketing/2298773.html','2026-10-11T19:40:00+07:00','Video AI Marketing','CÔNG TY TNHH IMPLANT NHA KHOA I-DENT','Hồ Chí Minh','Dưới 1 năm','Thoả thuận','phát triển nội dung marketing bằng AI (hình ảnh, video ngắn, kịch bản video, concept truyền thông, nội dung bán hàng online); dùng công cụ AI và Capcut sản xuất nội dung đa định dạng; nghiên cứu, thử nghiệm, đề xuất công cụ AI và quy trình tự động hoá; triển khai nội dung trên TikTok, Facebook, YouTube và các kênh online; phối hợp các bộ phận phát triển nội dung social commerce, affiliate marketing; theo dõi, đánh giá hiệu quả nội dung theo chỉ số video; thử nghiệm, tối ưu, cải tiến chất lượng nội dung và quy trình; xây dựng thư viện nội dung, thư viện prompt, guideline hình ảnh/video','tốt nghiệp Đại học ngành kinh tế/công nghệ (được đào tạo hoặc có kinh nghiệm video AI); kinh nghiệm Content Marketing, Social Media, TikTok Content, Video Content...; thành thạo gen AI (ChatGPT, Gemini) và Capcut; công cụ AI làm video (Grok, Veo3, Kling); ưu tiên từng sản xuất nội dung video/hình ảnh bán hàng, affiliate, performance; đã nghiên cứu workflow AI; học nhanh công nghệ mới, tinh thần thử nghiệm, tối ưu liên tục; tư duy thực chiến','2026-10-04','2026-10-14','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2304515','https://www.topcv.vn/viec-lam/presale-giai-phap-ai-camera/2304515.html','2026-10-11T19:40:00+07:00','Presale Giải Pháp AI Camera','Công ty Cổ phần Tập đoàn G','Hà Nội','2 năm','Tới 20 triệu','Phân tích nhu cầu khách hàng; thiết kế & tư vấn giải pháp AI Camera; hỗ trợ sales chào thầu, demo, triển khai dự án (ngân hàng, trụ sở cơ quan, chung cư, tòa nhà; phường/xã thông minh; giao thông, đô thị thông minh); phối hợp kỹ thuật & R&D','CNTT, Điện tử Viễn thông, Tự động hóa; 2+ năm Presale/kỹ sư giải pháp (CCTV, AI, Camera, Smart City, Access Control, IT/Network); Camera IP; NVR; Server; lưu trữ; LAN/WAN; 4G; thuật toán AI (nhận diện khuôn mặt, biển số, ReID, phân tích hành vi); ONVIF; RTSP; WebRTC; MQTT; AI Box; Edge AI; tư duy hệ thống; đọc bản vẽ kỹ thuật; PowerPoint; Excel; Visio; AutoCAD; thuyết trình; Tiếng Anh/Trung','','2026-10-17','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2306328','https://www.topcv.vn/viec-lam/project-management-associate/2306328.html','2026-10-11T19:17:47+07:00','Project Management Associate','Công Ty TNHH Sản Xuất Hàng May Mặc Việt Nam','Phú Thọ (KCN Bá Thiện 2, Xã Bình Tuyền)','Dưới 1 năm','Thoả thuận','Quản lý & theo dõi dự án chuyển đổi số từ lập kế hoạch đến triển khai; giám sát tiến độ, deliverables, KPI; hỗ trợ bàn giao giải pháp cho process owners; phối hợp nội bộ và đối tác triển khai giải pháp số.','Sinh viên mới tốt nghiệp được ứng tuyển; ưu tiên kinh nghiệm quản lý dự án số/tích hợp công nghệ; kiến thức cơ bản Excel VBA, Python, SQL; quan tâm xu hướng số; ứng dụng AI trong công việc; phân tích, giải quyết vấn đề; tiếng Anh giao tiếp tốt (~IELTS 6.0, không yêu cầu chứng chỉ).','','2026-10-22','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','eligible','Phù hợp: kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2307991','https://www.topcv.vn/brand/lxpantos/tuyen-dung/planning-staff-11-5-month-contract-j2307991.html','2026-10-11T19:17:47+07:00','Planning Staff (11.5 Month-Contract)','LX PANTOS VIETNAM','Hà Nội (Tầng 24, Handico Tower, Phạm Hùng, Từ Liêm)','2 năm','Thoả thuận','Tuyển planning enthusiast — lập/quản lý báo cáo hiệu suất kinh doanh định kỳ, phân tích doanh số hàng tháng, đảm bảo tính chính xác dữ liệu, hỗ trợ báo cáo ad-hoc cho ban quản lý và sales.','2 năm kinh nghiệm quản lý dữ liệu/báo cáo; tiếng Hàn là lợi thế lớn; Excel thành thạo (Pivot, XLOOKUP/VLOOKUP); tiếng Anh tốt; tỉ mỉ, đa nhiệm; CV tiếng Anh.','','2026-10-21','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2309877','https://www.topcv.vn/viec-lam/nhan-vien-content-marketing-ung-dung-ai/2309877.html','2026-10-11T19:40:00+07:00','Nhân Viên Content Marketing (Ứng Dụng AI)','CÔNG TY CỔ PHẦN ĐÀO TẠO VÀ THIẾT KẾ AWE','Hà Nội','2 năm','13 - 18 triệu','sáng tạo và sản xuất nội dung đa kênh (Fanpage, Website); ứng dụng mô hình content 3P, 4H; ứng dụng AI tạo sinh (ChatGPT, Claude, Gemini) lên ý tưởng và dàn ý; AI hỗ trợ tạo hình ảnh, xử lý đồ họa; thiết kế banner, thumbnail, poster (Canva, Photoshop, AI tools); biên tập video ngắn recap, chia sẻ kiến thức (CapCut/Premiere); hỗ trợ truyền thông sự kiện (trước - trong - sau hội thảo, workshop); điều phối, chụp ảnh/quay recap sự kiện; theo dõi tương tác và tỷ lệ chuyển đổi; tối ưu nội dung','tốt nghiệp Đại học/Cao đẳng Marketing, Truyền thông, PR (hoặc khóa học liên quan); khóa học/chứng nhận/kinh nghiệm ứng dụng AI; am hiểu hành vi khách hàng; cấu trúc copywriting (3P, 4H, AIDA); thành thạo tạo prompt; điều phối công cụ AI (ChatGPT, Claude, Gemini); gu thẩm mỹ; Canva/Photoshop căn bản; kinh nghiệm tổ chức/truyền thông sự kiện cơ bản; tác phong nhanh nhẹn, bắt trend; tư duy mở, chủ động ứng dụng công nghệ','2026-09-27','2026-10-22','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2313658','https://www.topcv.vn/viec-lam/quan-tri-va-van-hanh-he-thong-misa-amis/2313658.html','2026-10-11T19:17:47+07:00','Quản Trị Và Vận Hành Hệ Thống - Misa Amis','CÔNG TY CỔ PHẦN TẬP ĐOÀN CÔNG NGHỆ TLT','Hồ Chí Minh','Không yêu cầu','10 - 12 triệu','Phân tích yêu cầu nghiệp vụ, đề xuất giải pháp phần mềm Misa; thiết kế, lập trình, kiểm thử, triển khai phần mềm Misa; quản trị, bảo trì, nâng cấp, khắc phục sự cố, đầu mối liên hệ bên Misa; bảo mật dữ liệu; đào tạo/hỗ trợ người dùng; nghiên cứu công nghệ mới; hoàn thiện chương trình số hóa theo định hướng chuyển đổi số.','Tốt nghiệp ĐH/CĐ CNTT, KHMT, phần mềm hoặc liên quan; không yêu cầu kinh nghiệm (được đào tạo), ưu tiên kinh nghiệm MISA/ERP/HRM/CRM; kiến thức lập trình, CSDL, HĐH, mạng; tư duy logic, phân tích, giải quyết vấn đề; làm việc độc lập và nhóm.','2026-09-27','2026-10-26','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','eligible','Phù hợp: không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2313834','https://www.topcv.vn/viec-lam/nhan-vien-performance-marketing-ung-dung-ai/2313834.html','2026-10-11T19:40:00+07:00','Nhân Viên Performance Marketing (Ứng Dụng AI)','CÔNG TY CỔ PHẦN CÔNG NGHỆ SANDBOXVN','Hà Nội','1 năm','12 - 18 triệu','lập kế hoạch và triển khai chiến dịch Digital/Performance Marketing trên Meta Ads; nghiên cứu thị trường, khách hàng, đối thủ và xu hướng; quản lý, theo dõi, tối ưu chiến dịch (CPL, CPA, CTR, Conversion Rate, ROAS/ROI); theo dõi, phân tích dữ liệu (Ads Manager, Google Analytics); phối hợp Sales tối ưu chất lượng Lead; tham gia Content, Creative, Landing Page, Tracking, A/B Testing; ứng dụng AI vào Research, Content, Hình ảnh/Video, Phân tích dữ liệu, Automation; cập nhật thuật toán, chính sách nền tảng; lập báo cáo định kỳ','1 năm kinh nghiệm Performance/Digital Marketing; triển khai và tối ưu quảng cáo; Meta Ads; Zalo Ads/Google Ads/TikTok Ads là lợi thế; tư duy Performance & Data-driven; tối ưu chuyển đổi; đa nhiệm Ads–Content–Creative–Landing Page–Tracking; ứng dụng AI vào Marketing (AI Content, AI Image/Video, AI Data Analysis, Automation); tư duy thử nghiệm, sáng tạo; khả năng tự học; ưu tiên kinh nghiệm Lead Generation, Growth Marketing, Marketing Automation; giọng miền Bắc; có phương tiện di chuyển','','2026-11-08','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2313906','https://www.topcv.vn/viec-lam/thuc-tap-sinh-nghien-cuu-va-ung-dung-ai-van-phong/2313906.html','2026-10-11T19:40:00+07:00','Thực Tập Sinh Nghiên Cứu Và Ứng Dụng AI Văn Phòng','CÔNG TY TNHH LANDMART','Hồ Chí Minh','Không yêu cầu','Thoả thuận','nghiên cứu, ứng dụng công cụ AI vào công việc Hành chính, Nhân sự, Kế toán, Marketing; xây dựng mẫu câu lệnh (prompt); xử lý thông tin; tổng hợp báo cáo; tự động hóa công việc lặp lại; viết tài liệu, quay video hướng dẫn; hỗ trợ các bộ phận sử dụng AI; kiểm tra kết quả, theo dõi hiệu quả; đề xuất cải tiến','ưu tiên sinh viên CNTT, Hệ thống thông tin quản lý, Thương mại điện tử, Quản trị kinh doanh; kỹ năng tin học văn phòng; đã sử dụng AI; chủ động tìm hiểu công cụ mới; cẩn thận, kiểm chứng kết quả AI; phối hợp nhóm; bảo mật thông tin; có sản phẩm ứng dụng AI hoặc quy trình tự động hóa là lợi thế; kiến thức lập trình là lợi thế','','2026-10-26','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: tiêu đề thực tập sinh; không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','2315805','https://www.topcv.vn/viec-lam/content-marketing-ung-dung-ai-thuc-chien-tai-ha-dong-ha-noi-thu-nhap-upto-18-trieu-thuong-hieu-qua/2315805.html','2026-10-11T19:40:00+07:00','Content Marketing (Ứng Dụng AI Thực Chiến) Tại Hà Đông, Hà Nội - Thu Nhập Upto 18 Triệu + Thưởng Hiệu Quả','CÔNG TY CỔ PHẦN ĐÀO TẠO VÀ THIẾT KẾ AWE','Hà Nội','2 năm','Tới 18 triệu','lên kế hoạch và sản xuất content đa kênh (Fanpage, Website...); ứng dụng mô hình content 3P, 4H; khai thác công cụ AI tạo sinh (ChatGPT, Claude, Gemini) lên ý tưởng, dàn ý, viết bài; dùng AI tạo hình ảnh, xử lý đồ họa, tối ưu luồng công việc; thiết kế banner, thumbnail, poster (Canva, Photoshop, AI tools); biên tập/edit video ngắn (CapCut/Premiere); xây dựng kế hoạch truyền thông trước–trong–sau sự kiện, hội thảo, workshop; chụp ảnh/quay recap, hỗ trợ tổ chức sự kiện; theo dõi tương tác, tỷ lệ chuyển đổi, tối ưu','tốt nghiệp ĐH/CĐ Marketing, Truyền thông, PR (hoặc hoàn thành khóa đào tạo tương đương); khóa học/chứng nhận/kinh nghiệm thực chiến ứng dụng AI; am hiểu hành vi khách hàng và cấu trúc copywriting (3P, 4H, AIDA); thành thạo tạo prompt, điều phối công cụ AI (ChatGPT, Claude, Gemini); gu thẩm mỹ, Canva, Photoshop căn bản; kinh nghiệm tổ chức, truyền thông sự kiện/workshop; tốc độ, bắt trend, chủ động đề xuất giải pháp; tư duy mở, ứng dụng công nghệ','','2026-10-29','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2318112','https://www.topcv.vn/viec-lam/nhan-vien-ung-dung-ai/2318112.html','2026-10-11T19:40:00+07:00','Nhân Viên Ứng Dụng AI','VĂN PHÒNG ĐẠI DIỆN TẠI HÀ NỘI – CÔNG TY TNHH BEST SUN TECHNOLOGY.','Hồ Chí Minh','1 năm','12 - 20 triệu','Khảo sát, phân tích quy trình nội bộ; Đề xuất, thiết kế giải pháp ứng dụng AI tối ưu hóa; Triển khai công cụ AI (tự động hóa báo cáo, phân tích dữ liệu, chatbot, xử lý tài liệu); Đánh giá, kiểm thử, tối ưu giải pháp AI (prompt engineering, xử lý lỗi, kiểm soát chất lượng đầu ra); Đào tạo, hướng dẫn nhân viên dùng AI; Biên soạn tài liệu, quy trình, best practices; Theo dõi, đánh giá hiệu quả, đề xuất cải tiến liên tục; Nghiên cứu, cập nhật xu hướng AI','1–3 năm ứng dụng AI, chuyển đổi số, vận hành số, tư vấn công nghệ; Dùng AI thực tế (ChatGPT, Claude, Gemini...); Hiểu quy trình nghiệp vụ (bán hàng, CSKH, marketing, vận hành, nhân sự); Phân tích, tư duy logic, problem-solving; Giao tiếp, trình bày, training; Chịu áp lực, quản lý nhiều dự án; Tốt nghiệp Cao đẳng trở lên; Tư duy mở, đổi mới; Chủ động, cầu tiến, trách nhiệm','','2026-10-31','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2318279','https://www.topcv.vn/viec-lam/chuyen-vien-kinh-doanh-giai-phap-ai-phan-mem/2318279.html','2026-10-11T19:40:00+07:00','Chuyên Viên Kinh Doanh – Giải Pháp AI & Phần Mềm','Công Ty Cổ Phần Khoa Học Máy Tính ICSC','Hồ Chí Minh','1 năm','9 - 20 triệu','Tìm kiếm, tiếp cận, phát triển khách hàng doanh nghiệp (B2B); Tư vấn, kinh doanh giải pháp (AI/AI Agent/AI Chatbot, AI Camera/Computer Vision, phần mềm, tự động hóa, số hóa vận hành); Làm việc với Chủ doanh nghiệp, CEO, Founder, Manager, cấp ra quyết định; Phân tích nhu cầu, xác định cơ hội kinh doanh, đề xuất giải pháp; Phối hợp Technical/Solution xây dựng phương án, demo, proposal, báo giá; Thuyết trình giải pháp, theo dõi cơ hội, đàm phán, chốt hợp đồng; Quản lý pipeline khách hàng, phát triển network; Chăm sóc khách hàng trong/sau triển khai, upsell/cross-sell; Theo dõi thị trường','1–3 năm Sales B2B/Business Development; Ưu tiên kinh doanh Software, SaaS, ERP, AI, IT, giải pháp công nghệ; Chủ động tìm kiếm, phát triển khách hàng mới; Tư vấn, thuyết trình, đàm phán, xử lý phản đối, chốt hợp đồng; Xây dựng, quản lý, theo sát pipeline; Định hướng kết quả, chịu áp lực doanh số; Tự học sản phẩm, giải pháp công nghệ mới; Network khách hàng doanh nghiệp','2026-10-04','2026-10-31','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2318707','https://www.topcv.vn/viec-lam/junior-software-engineer/2318707.html','2026-10-11T19:40:00+07:00','Junior Software Engineer','CÔNG TY CỔ PHẦN NOVAAI VIETNAM','Hà Nội','Dưới 1 năm','Từ 15 triệu','phát triển Web & Backend (thiết kế, xây dựng, cải tiến tính năng); tích hợp AI & LLM (OpenAI, Claude, Gemini, AI...); thử nghiệm công nghệ/framework/AI Coding Tools mới; tối ưu hệ thống, debug, bảo trì, nâng cấp hiệu năng; phối hợp đội ngũ kỹ thuật và sản phẩm','Node.js/JavaScript/TypeScript; Web & Backend; API, HTTP protocol, Database (SQL/NoSQL); đọc hiểu tài liệu kỹ thuật tiếng Anh; điểm cộng: React/Next.js, Python, nền tảng AI/ML/LLM, AI coding tools (Cursor, Claude Code, GitHub Copilot), Docker, Cloud (AWS/GCP), dự án cá nhân/GitHub/hackathon','','2026-10-31','ai_ml_engineer','de_aiml','other','không thuộc 3 nhóm nghề mục tiêu','eligible','Phù hợp: tiêu đề junior; kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2324861','https://www.topcv.vn/viec-lam/chuyen-vien-dao-tao-dao-tao-so-va-ung-dung-ai/2324861.html','2026-10-11T19:40:00+07:00','Chuyên Viên Đào Tạo (Đào Tạo Số Và Ứng Dụng AI)','Trường Đại học CMC','Hà Nội','2 năm','Thoả thuận','vận hành đào tạo trực tuyến; E-learning; Blended Learning; lập kế hoạch học phần; tổ chức triển khai học phần E-learning/Blended Learning; quản lý khóa học; quản lý học liệu; quản lý dữ liệu giảng viên–sinh viên; theo dõi tiến độ, mức độ tham gia học tập; hỗ trợ giảng viên, sinh viên; tổ chức hướng dẫn, tập huấn; tổng hợp, phân tích dữ liệu; báo cáo; đề xuất cải tiến; xây dựng, chuẩn hóa, cập nhật quy định, quy trình; vận hành hệ sinh thái học tập AI-Native; Trợ giảng AI; thiết lập học phần với Khoa/giảng viên; quản lý, chuẩn hóa nguồn tri thức; đánh giá hoạt động Trợ giảng AI; phân tích hiệu quả hệ thống; thu thập phản hồi; cải tiến nội dung, tính năng, quy trình; quản lý chuẩn đầu ra tiếng Anh sinh viên; quản lý hồ sơ, quyết định','tốt nghiệp Đại học trở lên; ưu tiên CNTT, Hệ thống thông tin, Công nghệ giáo dục; 02 năm kinh nghiệm đào tạo/E-learning/EdTech; triển khai/vận hành hệ thống E-learning; hiểu biết AI; Blended Learning; Flipped Classroom; ứng dụng AI trong giáo dục; sử dụng, khai thác công cụ công nghệ, AI; hướng dẫn, đào tạo người dùng; phối hợp nhiều nhóm đối tượng; tổng hợp, quản lý dữ liệu; lập báo cáo; cẩn thận; trách nhiệm; phân tích, xử lý tình huống','2026-10-09','2026-11-08','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm 2 năm');
INSERT INTO "jobs" VALUES('TopCV','2325867','https://www.topcv.vn/viec-lam/nhan-vien-ke-hoach-chien-luoc/2325867.html','2026-10-11T19:17:47+07:00','Nhân Viên Kế Hoạch Chiến Lược','CÔNG TY TNHH THỰC PHẨM QUỐC TẾ NAM DƯƠNG','Hồ Chí Minh','1 năm','11 - 15 triệu','phân tích dữ liệu và quản lý báo cáo: dữ liệu bán hàng, thị trường, vận hành; duy trì hệ thống báo cáo định kỳ cho Ban Điều hành; theo dõi doanh số, sản lượng, hiệu suất kinh doanh theo kênh; báo cáo hiệu quả kinh doanh, phân tích chênh lệch thực tế vs kế hoạch; dự báo xu hướng kinh doanh ngắn hạn và dài hạn; theo dõi KPI và OKR toàn công ty; cảnh báo rủi ro, chỉ tiêu chưa đạt; hỗ trợ xây dựng dashboard quản trị; tham gia xây dựng kế hoạch kinh doanh năm và ngân sách; phân tích khả thi (Feasibility Study) cho dự án mới/mở rộng; nghiên cứu thị trường, đối thủ, xu hướng ngành; phân tích chi phí sản phẩm, hỗ trợ quyết định giá bán','tốt nghiệp đại học Kinh doanh, Kinh tế, Logistics, Chuỗi cung ứng, Kỹ thuật công nghiệp, Phân tích dữ liệu; tối thiểu 1 năm Kế hoạch chiến lược, Phân tích kinh doanh, Kế hoạch cung ứng/tài chính; môi trường FMCG hoặc sản xuất (ưu tiên); Excel nâng cao (Pivot Table, Power Query, Data Analysis); xây dựng mô hình phân tích và dự báo dữ liệu; Power BI, Access hoặc BI khác (ưu tiên); giao tiếp, phối hợp liên phòng ban; làm việc dưới áp lực, giải quyết vấn đề','','2026-11-08','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','eligible','Phù hợp: kinh nghiệm 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2326628','https://www.topcv.vn/viec-lam/nhan-vien-kinh-doanh-sales-b2b-giai-phap-ai/2326628.html','2026-10-11T19:40:00+07:00','Nhân Viên Kinh Doanh / Sales B2B - Giải Pháp AI','CÔNG TY TNHH TECH APOLLO','Hồ Chí Minh','Dưới 1 năm','6 - 16 triệu','nghiên cứu thị trường, khai phá nhu cầu, tạo cơ hội bán hàng chất lượng (SQL); nghiên cứu & chuẩn hóa dữ liệu (rà soát hệ thống dữ liệu doanh nghiệp mục tiêu, phân tích tín hiệu kinh doanh, phân loại khách hàng tiềm năng); tìm kiếm & xác thực (research đa nền tảng, gọi điện thoại mapping, truy xuất thông tin liên lạc người ra quyết định); tiếp cận ban đầu (chiến dịch tiếp cận cá nhân hóa qua tin nhắn và email, giới thiệu giải pháp AI); phối hợp tác chiến (đo lường mức độ quan tâm, phối hợp đội ngũ Sales thiết lập cuộc hẹn/meeting); quản trị hệ thống (cập nhật dữ liệu và lịch sử tương tác lên nền tảng quản trị nội bộ); hỗ trợ công việc được giao khác','tối thiểu 06 tháng kinh nghiệm bán giải pháp phần mềm B2B (ưu tiên CRM, ERP) hoặc Telesales; tư duy dữ liệu (kiên nhẫn, tỉ mỉ, xử lý khối lượng dữ liệu lớn mỗi ngày); kỹ năng tìm kiếm xuất sắc (Google, LinkedIn, Facebook, Zalo); tư duy khai phá/hunter mindset (cold-call, kiên trì bám đuổi mục tiêu, đối mặt với sự từ chối); kỹ năng giao tiếp; thái độ làm việc (kỷ luật với các chỉ số hành động hàng ngày, chủ động, trung thực, trách nhiệm); kỹ năng cần có: Giao tiếp, Bán Hàng B2b; kỹ năng nên có: hiểu biết về du lịch, Phần mềm B2B; Đại học trở lên','2026-10-09','2026-11-08','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: kinh nghiệm Dưới 1 năm');
INSERT INTO "jobs" VALUES('TopCV','2327269','https://www.topcv.vn/viec-lam/chuyen-vien-ung-dung-ai-ai-enablement-associate/2327269.html','2026-10-11T19:40:00+07:00','Chuyên Viên Ứng Dụng AI (AI Enablement Associate)','Công ty Cổ phần Truyền Thông Tập Trung Mặt Trời Vàng','Hồ Chí Minh','Không yêu cầu','Thoả thuận','hiểu rõ và tổng hợp yêu cầu của công ty (đặc biệt của CEO) đối với hệ thống AI quản lý bán hàng; thúc đẩy và thu thập phản hồi của đội ngũ kinh doanh về việc sử dụng công cụ AI; theo dõi dữ liệu hiệu quả sử dụng của AI Agent (tỷ lệ phản hồi chính xác, tỷ lệ sử dụng, mức độ hài lòng...); thiết lập và duy trì cơ chế giao tiếp, điều phối giữa phòng ban (Bán hàng, IT, HR...) và với nhà cung cấp; tham gia xây dựng lộ trình ứng dụng AI của công ty, nhân rộng kinh nghiệm thành công; cập nhật xu hướng và công cụ ứng dụng AI mới nhất, đề xuất xây dựng','tốt nghiệp Đại học trở lên (ưu tiên Khoa học Máy tính, Khoa học Dữ liệu...); 0-3 năm kinh nghiệm (ưu tiên có dự án ứng dụng công cụ AI); hiểu biết khái niệm cơ bản Prompt Engineering, RAG, quy trình làm việc của AI Agent; khả năng học hỏi, tự giác cao; giao tiếp và phối hợp giữa các bộ phận; quản lý dự án cơ bản; Tiếng Trung và tiếng Anh tốt; ưu tiên đã sử dụng công cụ AI để xây dựng AI Agent hoặc quy trình tự động hóa','2026-10-10','2026-11-09','ai_ml_engineer','de_aiml','other','','eligible','Phù hợp: không yêu cầu kinh nghiệm');
INSERT INTO "jobs" VALUES('TopCV','1835121','https://www.topcv.vn/viec-lam/truong-phong-quan-ly-hieu-suat-kinh-doanh/1835121.html','2026-10-11T19:17:47+07:00','Trưởng Phòng Quản Lý Hiệu Suất Kinh Doanh','VNDIRECT','Hà Nội (Phường Cầu Giấy)','Trên 5 năm','Thoả thuận','Thiết lập mô hình phân tích & cung cấp insights; thiết kế/triển khai báo cáo tự động, dashboard real-time; cải tiến quy trình qua phân tích dữ liệu/P&L; xây dựng chính sách khối bán lẻ; điều phối liên phòng ban; quản trị nhân sự và phát triển đội ngũ.','Đại học trở lên (phân tích dữ liệu/thống kê/kinh tế); từ 7 năm kinh nghiệm phân tích dữ liệu, tối thiểu 3 năm phân tích kinh doanh ngành tài chính/chứng khoán/bảo hiểm và 3 năm quản lý đội ngũ; tư duy chiến lược, SQL/Python/R, Power BI/Tableau; CRM, AI; lãnh đạo đội nhóm.','2026-10-05','2026-11-04','data_analyst','data_analyst','other','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','1928068','https://www.topcv.vn/viec-lam/senior-data-analytics-consultant-presales/1928068.html','2026-10-11T19:40:00+07:00','Senior Data & Analytics Consultant/ Presales','SVTECH','Hà Nội','3 năm','Thoả thuận','Tư vấn giải pháp Data & Analytics; Thuyết trình/tổ chức workshop; Hỗ trợ RFI/RFP; Xây dựng đề xuất kỹ thuật (technical proposal); Thiết kế luồng dữ liệu phân tích end-to-end; Thiết kế kiến trúc tổng thể; Điều phối nhóm kỹ thuật (Engineering, Analyst, Solution Architect); Phân tích kỹ thuật và nghiệp vụ; PoC; Demo; Triển khai giải pháp; Hỗ trợ kỹ thuật; Đào tạo khách hàng; Phối hợp Account Manager; Tìm kiếm, phát triển cơ hội kinh doanh; Duy trì quan hệ khách hàng','3–5 năm kinh nghiệm Data Architecture/Data Engineering/Solution Consulting/Technical Presales; Tư vấn giải pháp; Thuyết trình; Workshop; Demo giải pháp; PoC; RFI/RFP; Data Lake; Data Lakehouse; Data Warehouse; Databricks; Cloudera; Hadoop; Spark; Kafka; SAP; Teradata; Oracle; Tốt nghiệp Đại học CNTT/Viễn thông; Kỹ năng giao tiếp (Tiếng Anh & Việt); Growth Mindset; Trực quan hóa dữ liệu; Phân tích dữ liệu','','2026-10-24','data_engineer','de_aiml','other','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2198361','https://www.topcv.vn/viec-lam/chuyen-vien-cao-cap-phan-tich-tai-chinh-kinh-doanh-j2198361.html','2026-10-11T19:17:47+07:00','Chuyên Viên Cao Cấp Phân Tích Tài Chính Kinh Doanh','CÔNG TY CỔ PHẦN TẬP ĐOÀN ĐẦU TƯ I.P.A','Hà Nội (95 Trần Thái Tông, Phường Cầu Giấy)','4 năm','Thoả thuận','Vai trò — tổ chức dữ liệu, xây dựng báo cáo quản trị và phân tích hiệu quả tài chính–kinh doanh. 1. Kiến trúc dữ liệu: quy hoạch luồng dữ liệu tài chính–kinh doanh, chuẩn mực dữ liệu, tối ưu ghi nhận/tổ chức/khai thác dữ liệu. 2. Hệ thống báo cáo quản trị: thiết kế dashboards tự động, báo cáo định kỳ/đột xuất, cảnh báo sớm chỉ số sức khỏe tài chính–kinh doanh. 3. Phân tích hiệu suất: mô hình P&L, phân tích biến động thực tế vs kế hoạch, cố vấn giải pháp tối ưu. 4. Hoạch định tài chính: budgeting, forecasting, theo dõi thực thi ngân sách, thẩm định hiệu quả P&L của phương án đầu tư/chính sách.','Tốt nghiệp đại học trở lên Tài chính/Kế toán/Kiểm toán/Phân tích dữ liệu; chứng chỉ ACCA/CPA/CFA; từ 4–5 năm kinh nghiệm Financial Analysis/FP&A/Business Finance, kinh nghiệm phân tích KQKD, xây dựng cơ chế kinh doanh và báo cáo quản trị; hiểu mô hình bán lẻ/F&B/FMCG hoặc hệ thống dữ liệu phức tạp; đam mê dữ liệu, cẩn trọng, logic, trách nhiệm, chịu áp lực; thành thạo SQL, Power BI, Financial Model; hiểu kế toán/tài chính quản trị, cấu trúc P&L, ngân sách, forecast; giải quyết vấn đề, trình bày báo cáo trực quan; kỹ năng sử dụng AI.','2026-09-20','2026-10-31','data_analyst','data_analyst','other','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2226137','https://www.topcv.vn/viec-lam/finance-data-senior/2226137.html','2026-10-11T19:17:47+07:00','Finance & Data Senior','CÔNG TY CỔ PHẦN TRƯỜNG HỌC CÔNG NGHỆ MINDX','Hà Nội (Tầng 5, Số 71 Nguyễn Chí Thanh, Phường Giảng Võ)','2 năm','Từ 25 triệu','Phân tích báo cáo tài chính, doanh thu, chi phí, lợi nhuận, dòng tiền và hiệu quả từng mảng kinh doanh (actual và plan); xây dựng dashboard/báo cáo quản trị cho Ban Tổng Giám đốc; đối soát dữ liệu với Kế toán/Sales/Vận hành; số hóa quy trình báo cáo, chuẩn hóa dữ liệu; làm việc với accounting agent, auditor để kiểm toán chi nhánh ở nước ngoài; hỗ trợ tài liệu cho nhà đầu tư; ứng dụng AI/AI Agent trong công việc.','Tốt nghiệp đại học Tài chính/Kế toán/Kiểm toán/Kinh tế; kinh nghiệm phân tích tài chính, báo cáo quản trị, FP&A hoặc kiểm soát hiệu quả kinh doanh; thành thạo Excel/Google Sheets, ưu tiên Power BI/Tableau/Metabase, SQL hoặc Python; dùng thành thạo các công cụ AI (ChatGPT, Gemini, Claude, Copilot); tư duy dữ liệu tốt, cẩn trọng, giao tiếp rõ ràng; ưu tiên kinh nghiệm xây dựng dashboard, số hóa báo cáo, từng làm việc tại Big4/tư vấn/quỹ đầu tư/startup, tài liệu tài chính cho nhà đầu tư/M&A.','','2026-10-30','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2226144','https://www.topcv.vn/viec-lam/finance-data-senior/2226144.html','2026-10-11T19:17:47+07:00','Finance & Data Senior','MindX Technology School','Hà Nội (Tầng 5, 71 Nguyễn Chí Thanh, Phường Giảng Võ)','1 năm','Từ 25 triệu','Phân tích báo cáo tài chính, doanh thu, chi phí, lợi nhuận, dòng tiền và hiệu quả từng mảng kinh doanh; xây dựng dashboard/báo cáo quản trị cho Ban Tổng Giám đốc; đối soát dữ liệu với Kế toán/Sales/Vận hành; ứng dụng AI/AI Agent tổng hợp dữ liệu, kiểm tra sai lệch, phân tích nhanh, tạo báo cáo; số hóa quy trình báo cáo, chuẩn hóa dữ liệu; hỗ trợ số liệu làm việc với nhà đầu tư.','Đại học Tài chính/Kế toán/Kiểm toán/Kinh tế; kinh nghiệm phân tích tài chính, báo cáo quản trị, FP&A; dùng thành thạo công cụ AI (ChatGPT, Gemini, Claude, Copilot, AI Agent); Excel/Google Sheets; ưu tiên Power BI/Tableau/Metabase, SQL/Python; tư duy dữ liệu, cẩn trọng, giao tiếp rõ ràng; ưu tiên kinh nghiệm dashboard, số hóa báo cáo, Big4/tư vấn/quỹ đầu tư, tài liệu cho nhà đầu tư/M&A.','','2026-10-30','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2262646','https://www.topcv.vn/viec-lam/business-planning-staff-korean-speaking/2262646.html','2026-10-11T19:17:47+07:00','Business Planning Staff (Korean Speaking)','Công ty TNHH Kinh doanh miễn thuế Lotte Phú Khánh','Đà Nẵng (Indochina Tower, 74 Bạch Đằng, Phường Hải Châu)','1 năm','Thoả thuận','Thu thập/cập nhật thông tin kinh doanh (lịch bay, sales data, market info); hỗ trợ quản lý dự án (planning, scheduling, tracking, reporting); lập báo cáo hiệu suất bán hàng và kết quả kinh doanh; hỗ trợ quản lý ngân sách và báo cáo P&L; hỗ trợ dự báo doanh thu; quản lý tài liệu/dữ liệu planning; hỗ trợ Planning Manager trong báo cáo và công việc planning hàng ngày; phiên dịch khi cần; quản lý yêu cầu truy cập hệ thống và công việc hành chính khác.','Cử nhân Quản trị kinh doanh/Kế toán/Tài chính; 1 năm kinh nghiệm (tiếng Hàn) hoặc 3+ năm (tiếng Anh); thành thạo tiếng Hàn hoặc tiếng Anh, phân tích dữ liệu, Excel; MS Office.','2026-09-11','2026-10-11','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','excluded','Địa điểm ngoài Việt Nam (Đà Nẵng (Indochina Tower, 74 Bạch Đằng, Phường Hải Châu))');
INSERT INTO "jobs" VALUES('TopCV','2300875','https://www.topcv.vn/viec-lam/giam-doc-van-hanh-du-an-ai/2300875.html','2026-10-11T19:40:00+07:00','Giám Đốc Vận Hành Dự Án AI','CÔNG TY CỔ PHẦN XUẤT NHẬP KHẨU BÌNH TÂY (BITEX)','Hồ Chí Minh','5 năm','Thoả thuận','Xây dựng chiến lược & mô hình kinh doanh ngành hàng AI (đồ chơi giáo dục AI, đồ gia dụng AI, Robot AI); định vị thương hiệu, tăng trưởng, mở rộng thị trường; nghiên cứu xu hướng AI/Robotics/Smart Home/IoT; danh mục sản phẩm & phân khúc khách hàng; hợp tác công nghệ, OEM/ODM; tham mưu CEO/HĐQT; chịu trách nhiệm P&L (doanh thu, lợi nhuận, EBITDA, ROI); kế hoạch kinh doanh & ngân sách; Product Roadmap, thương mại hóa; phát triển dòng sản phẩm AI; quản trị chuỗi cung ứng (mua hàng, nhập khẩu, tồn kho, phân phối); phát triển thị trường B2B (trường học, trung tâm giáo dục, doanh nghiệp) & B2C (AI & Smart Home); phân phối toàn quốc, thương mại điện tử, đa kênh; đối tác chiến lược; xây dựng tổ chức & đội ngũ (KPI/OKR)','Đại học QTKD, Kỹ thuật, Công nghệ, Điện tử, Tự động hóa (ưu tiên MBA); 5+ năm quản lý; xây dựng doanh nghiệp/ngành hàng mới; quản lý chuỗi cung ứng; phát triển sản phẩm; kinh doanh; vận hành; ưu tiên AI & Robotics, điện tử tiêu dùng, Smart Home','2026-09-20','2026-10-14','ai_ml_engineer','de_aiml','other','chức danh điều hành','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2303168','https://www.topcv.vn/viec-lam/communications-innovation-ai-expert/2303168.html','2026-10-11T19:40:00+07:00','Communications Innovation & AI Expert','NGÂN HÀNG THƯƠNG MẠI CỔ PHẦN KỸ THƯƠNG VIỆT NAM (Techcombank)','Hà Nội','3 năm','Thoả thuận','nghiên cứu, đề xuất, triển khai giải pháp AI nâng cao hiệu quả truyền thông và gắn kết nhân viên; xây dựng mô hình, quy trình, sáng kiến ứng dụng AI tối ưu truyền tải thông tin; theo dõi xu hướng AI, công nghệ mới, chuyển đổi số; khai thác dữ liệu từ nền tảng truyền thông/số, đo lường hiệu quả truyền thông; xây dựng báo cáo, dashboard, insight phục vụ ra quyết định; cá nhân hóa nội dung, tối ưu hành trình người dùng dựa trên dữ liệu; triển khai chương trình truyền thông, employee engagement, chuyển đổi văn hóa; tư vấn đơn vị áp dụng phương thức truyền thông hiện đại; làm cầu nối giữa nghiệp vụ, công nghệ, truyền thông; xây dựng văn hóa đổi mới sáng tạo; nâng cao nhận thức và kỹ năng ứng dụng AI của cán bộ nhân viên','Đại học trở lên (CNTT, Khoa học dữ liệu, Hệ thống thông tin, Truyền thông số, Marketing Technology); 3-5 năm kinh nghiệm (AI Adoption, Digital Transformation, Digital Communications, Data Analytics, Employee Experience, Change Management); hiểu biết AI, Generative AI, Data Analytics; nền tảng số, hành vi người dùng; chuyển đổi số, đổi mới sáng tạo; ưu tiên từng triển khai AI/chuyển đổi số trong doanh nghiệp','','2026-10-16','ai_ml_engineer','de_aiml','other','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2307215','https://www.topcv.vn/viec-lam/vien-ha-tang-cntt-ung-dung-ai-it-infrastructure-ai-specialist/2307215.html','2026-10-11T19:40:00+07:00','Viên Hạ Tầng CNTT & Ứng Dụng AI (IT Infrastructure & AI Specialist)','CÔNG TY CỔ PHẦN VẬN TẢI VÀ THƯƠNG MẠI ĐƯỜNG SẮT','Hà Nội','3 năm','16 - 18 triệu','quản trị hạ tầng CNTT; vận hành máy chủ, máy trạm, thiết bị lưu trữ, thiết bị ngoại vi, Data Center; hạ tầng mạng LAN/WAN, WiFi, Internet, VPN; thiết bị bảo mật; Firewall; IDS/IPS; phân quyền truy cập; kiểm soát truy cập từ xa; theo dõi hiệu năng; giám sát hoạt động; xử lý sự cố phần cứng, mạng; backup dữ liệu; dự phòng; Disaster Recovery; đề xuất, triển khai giải pháp AI; tăng năng suất; tối ưu chi phí; nghiên cứu, phát triển, ứng dụng AI; tự động hóa báo cáo; phân tích dữ liệu; dự báo; trợ lý số nội bộ; tra cứu quy trình, quy định, nghiệp vụ; OCR; nhận dạng chứng từ, hợp đồng; nhập liệu tự động; Chatbot; Callbot; quản trị dữ liệu: thu thập, làm sạch, chuẩn hóa, bảo mật; kiểm soát an toàn thông tin; phòng chống mã độc; rà soát lỗ hổng bảo mật; ứng cứu sự cố; phối hợp phòng ban; nhiệm vụ khác theo phân công của Trưởng phòng','tốt nghiệp Đại học CNTT; tin học văn phòng; tiếng Anh giao tiếp cơ bản; tối thiểu 03 năm kinh nghiệm CNTT; kiến thức hạ tầng CNTT, hệ thống mạng, bảo mật; nghiên cứu, triển khai giải pháp AI trong doanh nghiệp; giao tiếp; phối hợp nhiều phòng ban; tổ chức; quản lý thời gian; làm việc độc lập; làm việc nhóm; 25 - 35 tuổi; nhanh nhẹn; chủ động; trách nhiệm','','2026-10-21','ai_ml_engineer','de_aiml','other','','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2308244','https://www.topcv.vn/viec-lam/ky-su-phat-trien-thiet-ke-ic/2308244.html','2026-10-11T19:40:00+07:00','Kỹ Sư Phát Triển & Thiết Kế IC','CÔNG TY TNHH VTI EDUCATION','Nhật Bản','Dưới 1 năm','Từ 45 triệu','Nghiên cứu & phát triển IC Brushless Motor Driver; thiết kế hệ thống, mạch Analog, kiểm tra sản phẩm; kiểm soát chất lượng & sản xuất hàng loạt; hỗ trợ khách hàng (trong nước & quốc tế); mở rộng thị trường, hỗ trợ kỹ thuật trực tiếp','Vi mạch CMOS Analog; thiết kế RTL (Verilog/HDL); Điện - Điện tử hoặc CNTT/KHMT; Tiếng Nhật JLPT N4; Tiếng Anh TOEIC 550; Đại học trở lên','','2026-10-21','ai_ml_engineer','de_aiml','other','','excluded','Địa điểm ngoài Việt Nam (Nhật Bản)');
INSERT INTO "jobs" VALUES('TopCV','2308263','https://www.topcv.vn/viec-lam/ky-su-thiet-ke-phat-trien-ai-secure-mcu/2308263.html','2026-10-11T19:40:00+07:00','Kỹ Sư Thiết Kế & Phát Triển AI / Secure MCU','CÔNG TY TNHH VTI EDUCATION','Nhật Bản','Dưới 1 năm','Từ 45 triệu','Thiết kế & phát triển Edge AI-MCU tối ưu chi phí; suy luận & tự học trên thiết bị; thiết kế mạch Digital/Analog; phân tích dữ liệu sinh trắc (Vital), pin, cảm biến; phát triển thuật toán AI suy luận/học tập trên thiết bị; đơn vị chức năng tốc độ cao tiết kiệm chi phí','Thiết kế RTL; kiểm tra tính năng; Logic Synthesis; Timing Constraints; Static/Dynamic timing; Functional Safety; Fail-safe; ESD/EMC; công cụ VCS; Tiếng Nhật JLPT N4; Tiếng Anh TOEIC 550; Đại học trở lên','','2026-10-21','ai_ml_engineer','de_aiml','other','','excluded','Địa điểm ngoài Việt Nam (Nhật Bản)');
INSERT INTO "jobs" VALUES('TopCV','2312886','https://www.topcv.vn/viec-lam/chuyen-vien-kiem-thu-du-lieu-data-tester/2312886.html','2026-10-11T19:17:47+07:00','Chuyên Viên Kiểm Thử Dữ Liệu - Data Tester','Công ty Cổ phần The First One','Hồ Chí Minh (Tòa nhà Sailing Tower, 111A Pasteur, Phường Sài Gòn)','3 năm','31 - 38 triệu','Đọc hiểu yêu cầu nghiệp vụ, tài liệu thiết kế, quy tắc xử lý dữ liệu; xác định phạm vi, kịch bản và dữ liệu cần kiểm thử; xây dựng test case, checklist và truy vấn SQL theo từng luồng dữ liệu; dùng SQL đối soát nguồn–đích, kiểm tra tính đầy đủ/chính xác/nhất quán/logic chuyển đổi; kiểm thử luồng tích hợp/đồng bộ/chuyển đổi/báo cáo theo phạm vi giao; ghi nhận lỗi kèm bằng chứng, phối hợp BA/Developer xác định nguyên nhân, kiểm thử lại sau xử lý; theo dõi kết quả, báo cáo tiến độ, cảnh báo kịp thời rủi ro ảnh hưởng chất lượng dữ liệu.','Tốt nghiệp CNTT/Khoa học máy tính/Hệ thống thông tin/Khoa học dữ liệu hoặc ngành công nghệ liên quan; kinh nghiệm kiểm thử phần mềm/dữ liệu level Middle/Senior, chủ động thiết kế và thực hiện test case; SQL tốt để truy vấn/đối chiếu/phân tích, hiểu CSDL quan hệ; đọc hiểu yêu cầu, phân tích lỗi, trao đổi rõ ràng với nhóm nghiệp vụ/kỹ thuật; cẩn thận, trách nhiệm; ưu tiên kinh nghiệm ngân hàng/tài chính, ETL/ELT/Data Warehouse/data migration, đối soát đa hệ thống, công cụ quản lý lỗi/test case, kiểm thử API.','2026-09-27','2026-10-25','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','excluded','Yêu cầu kinh nghiệm 3 năm (>2 năm)');
INSERT INTO "jobs" VALUES('TopCV','2313254','https://www.topcv.vn/brand/nganhangthuongmaicophanquandoi/tuyen-dung/chuyen-vien-cao-cap-chuyen-gia-kiem-dinh-mo-hinh-kinh-doanh-senior-business-model-validation-analyst-bi-khoi-du-lieu-2026td453781-j2313254.html','2026-10-11T19:17:47+07:00','Chuyên Viên Cao Cấp, Chuyên Gia Kiểm Định Mô Hình Kinh Doanh - Senior Business Model Validation Analyst (BI) - Khối Dữ Liệu (2026TD453781)','NGÂN HÀNG TMCP QUÂN ĐỘI – MBBANK','Hà Nội','3 năm','Thoả thuận','thu thập dữ liệu, xây dựng báo cáo đánh giá mô hình kinh doanh; giám sát xây dựng hệ thống đo lường chỉ tiêu kiểm định mô hình; đánh giá chất lượng mô hình qua chương trình thử nghiệm thực tế; báo cáo theo dõi, đánh giá danh mục sản phẩm ứng dụng mô hình phân tích dữ liệu kinh doanh; phối hợp kinh doanh phát triển end-to-end sản phẩm đầu ra từ mô hình dữ liệu lên hệ thống','cử nhân kinh tế, tài chính, ngân hàng, KHDL, KHMT, thống kê, toán tin; tối thiểu 3 năm phân tích dữ liệu trong ngân hàng; phân tích kinh doanh, quản trị danh mục, triển khai mô hình dự báo/ML, đánh giá chất lượng mô hình (ưu tiên); SQL, Tableau, Power BI, Oracle (ưu tiên); lập trình R/Python (ưu tiên); TOEIC 550 trở lên','2026-09-27','2026-10-25','data_analyst','data_analyst','other','','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2318059','https://www.topcv.vn/viec-lam/head-of-ai-ai-product-transformation/2318059.html','2026-10-11T19:40:00+07:00','Head Of AI (AI Product & Transformation)','Sava Meta (CÔNG TY CỔ PHẦN CÔNG NGHỆ SAVA META)','Hà Nội','Trên 5 năm','Thoả thuận','Xây dựng tầm nhìn/chiến lược AI và roadmap; giám sát R&D và triển khai AI trên nhiều team; lãnh đạo và phát triển đội ngũ AI; phối hợp phòng ban/khách hàng về giải pháp AI; đánh giá rủi ro và tuân thủ (GDPR, quy định AI); đo lường hiệu quả chương trình AI (ROI, tác động kinh doanh)','Lãnh đạo đội ngũ AI/ML kỹ thuật; kinh nghiệm AI/ML thực tiễn; kiến thức ML; deep learning; NLP; computer vision; xây dựng chiến lược AI phù hợp mục tiêu kinh doanh; tư duy chiến lược; phân tích; giao tiếp xuất sắc tiếng Việt và tiếng Anh','','2026-11-01','ai_ml_engineer','de_aiml','other','chức danh điều hành','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2318952','https://www.topcv.vn/viec-lam/head-of-data-tai-upbase-ai-big-data-ecom-partner/2318952.html','2026-10-11T19:40:00+07:00','Head Of Data Tại UpBase-AI & Big Data Ecom Partner','CÔNG TY CỔ PHẦN CÔNG NGHỆ UPBASE','Hà Nội','Trên 5 năm (kinh nghiệm quản lý: 3 năm)','Thoả thuận','Xây dựng Data Strategy & roadmap; xây dựng, phát triển Data Team (Data Analyst, Data Engineer, Analytics Engineer, Data Scientist/AI Engineer); làm việc trực tiếp với BOD, Business, Product; xây dựng Data Warehouse, Data Mart, BI & Reporting; chuẩn hóa KPI, metrics, data governance, data quality; dẫn dắt chuyển hóa dữ liệu thành insight, forecasting, recommendation, scoring, ứng dụng AI/ML cho E-commerce; đưa Data vào quyết định tăng trưởng, khách hàng, marketing, vận hành, tài chính, sản phẩm; xây dựng văn hóa data-driven; biến Data thành sản phẩm/dịch vụ cho khách hàng doanh nghiệp','Trên 5 năm kinh nghiệm Data Analytics/BI/Data Engineering/Data Science; tối thiểu 3 năm quản lý đội nhóm Data; ưu tiên kinh nghiệm ecommerce/retail/marketplace/SaaS/fintech/logistics; xây dựng data strategy, roadmap, operating model; thành thạo SQL; BI tools (Power BI, Tableau, Looker Studio, Metabase); hiểu biết data warehouse, ETL/ELT, data modeling, data pipeline, data quality, data governance; phân tích kinh doanh, chuyển dữ liệu thành insight','2026-10-04','2026-10-31','data_engineer','de_aiml','other','chức danh điều hành','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2326707','https://www.topcv.vn/viec-lam/senior-innovation-project-engineer-automation/2326707.html','2026-10-11T19:40:00+07:00','Senior Innovation Project Engineer - Automation','CÔNG TY TNHH METASOURCE','Khánh Hòa, Hồ Chí Minh','Trên 5 năm','Thoả thuận','phạm vi dự án đổi mới và cải tiến liên tục; tìm kiếm và đánh giá cơ hội tự động hóa (xử lý vải, may, nhồi, hoàn thiện, đóng gói); đánh giá đề xuất đầu tư; quản lý tiến độ, ngân sách, rủi ro nhiều dự án; dẫn dắt kỹ thuật với nhà cung cấp và đối tác nghiên cứu; thiết lập thử nghiệm và dự án thí điểm; thu thập và phân tích dữ liệu phục vụ ROI; theo dõi dự án tự động hóa (AGV, CTU); triển khai công nghệ ra sản xuất; phối hợp đội ngũ IE/SOP/IT/kỹ thuật/bảo trì','8+ năm kỹ thuật công nghiệp/sản xuất/tự động hóa; dẫn dắt dự án đổi mới từ phạm vi đến triển khai; bằng ĐH cơ khí/điện/điện tử/cơ điện tử; kinh nghiệm sản phẩm may/thiết bị may công nghiệp; đánh giá và triển khai tự động hóa/máy móc; kỹ năng dữ liệu và xây dựng ROI (SMV, Excel/Power BI); tiếng Anh kỹ thuật thành thạo; đi công tác thường xuyên; PMP/PRINCE2/Agile/Lean/Six Sigma (ưu tiên); robotics/machine vision/PLC/AGV (ưu tiên)','2026-10-09','2026-11-08','ai_ml_engineer','de_aiml','other','không thuộc 3 nhóm nghề mục tiêu','excluded','Tiêu đề cấp Senior/Lead/Manager trở lên');
INSERT INTO "jobs" VALUES('TopCV','2323350','https://www.topcv.vn/viec-lam/route-to-market-rtm-specialist/2323350.html','2026-10-11T19:17:47+07:00','Route-To-Market (RTM) Specialist','GOOD FOOD CO., LTD','Hồ Chí Minh: Tòa nhà SARICA, Tháp A1 - 6D9 Nguyễn Cơ Thạch, Phường An Phú Đông (Phường An Phú Đông thuộc Quận 12 cũ)','2 năm (mục yêu cầu ghi 2–3 năm)','Thoả thuận','(1) Coverage & Distribution Expansion: tối ưu tuyến bán hàng GT bằng outlet segmentation; xác định khu vực chưa phục vụ (white space), xây dựng kế hoạch mở rộng coverage; theo dõi coverage KPI. (2) Outlet Segmentation & Targeting: xây dựng mô hình phân khúc điểm bán; phân nhóm outlet để ưu tiên phục vụ và phân bổ nguồn lực; đề xuất tần suất viếng thăm, mức tồn kho tối thiểu, danh mục sản phẩm theo từng phân khúc. (3) Distributor & Sales Team Management: quản lý hiệu suất nhà phân phối; phân tích hiệu quả tuyến, năng suất nhân viên bán hàng. (4) Data Analysis & Reporting: xây dựng báo cáo, dashboard theo dõi KPIs; phân tích dữ liệu bán hàng, tồn kho, thị trường; chuẩn hóa và kiểm soát chất lượng dữ liệu. (5) Trade Program Execution: triển khai chương trình trưng bày, khuyến mãi, activation tại điểm bán; đo lường hiệu quả.','Tốt nghiệp ĐH Kinh tế, QTKD, Marketing...; 2–3 năm kinh nghiệm RTM, phát triển thị trường, quản lý nhà phân phối, ưu tiên ngành hàng tiêu dùng; hiểu kênh GT và hệ thống phân phối; kỹ năng phân tích dữ liệu, Excel/Power BI; tư duy chiến lược, kỹ năng lập kế hoạch; giao tiếp, đàm phán, quản lý mối quan hệ; sẵn sàng đi thị trường.','2026-10-06','2026-11-05','data_analyst','data_analyst','other','không thuộc 3 nhóm nghề mục tiêu','review','Yêu cầu kinh nghiệm dạng khoảng 2–3 năm');
